/* NOOR Codex of Light, the Qur'an study companions.
   114 surahs: 57 opened in full, 57 opened in brief.
   Generated by scripts/gen-quran-study.py from the study-deep-*.json
   tranches and build/study-light.json. Do not edit by hand.
   Loaded deferred: the Mushaf reads perfectly without it. */
window.NOOR_STUDY = {
/* 1 Al-Fatiha, deep, 7 ayat */
1:{"n":1,"depth":"deep","context":["Al-Fatiha came down in Makkah in the first years of revelation, by the word of Ibn Abbas, Qatadah, and the majority of the early commentators. The message was still young, the believers were few, and the daily prayer was taking its first shape in a city that worshipped stone. Into that small circle Allah sent down not a story and not a law but a complete conversation: seven verses that teach a human being how to stand before his Maker and what to say first.","It became the spine of the Prophet’s ﷺ life and of every life joined to his. No prayer is valid without it, so the early community repeated it a minimum of seventeen times a day, in fear in Makkah and in victory in Madinah, until its words wore a channel in the heart. In the hadith qudsi, a report in which the Prophet ﷺ relates the speech of his Lord, Allah says He divided this surah between Himself and His servant: the servant praises, and Allah answers him line by line."],"name_story":"Al-Fatiha means the Opener: the Book opens with it, and the prayer opens with it, and in truth the whole religion opens with it. The Prophet ﷺ also called it Umm al-Quran and Umm al-Kitab, the Mother of the Book, because every theme of the Quran is folded inside it in seed form. Allah Himself named it as-Sab’ al-Mathani, the Seven Oft-Repeated, in Surah al-Hijr, and the companions knew it as a ruqyah, a healing recitation, after one of them cured a scorpion sting with nothing else.","movements":[{"range":"1-3","h":"Praise before asking","note":"The servant begins not with need but with the name of Allah, gratitude for the Lord of all worlds, and mercy named twice before anything else."},{"range":"4-5","h":"The Master and the covenant","note":"Ownership of the Day of Judgment leads straight into the surah’s hinge: You alone we worship, You alone we ask for help."},{"range":"6-7","h":"The one request","note":"After all that praise the servant asks for a single thing, the straight path, defined by the people who walked it and the two ways that lost it."}],"themes":[{"t":"Praise before petition","d":"The surah trains the soul to see who Allah is before saying what it wants, so that asking becomes worship rather than demand."},{"t":"Mercy holding majesty","d":"Ar-Rahman ar-Rahim, the Entirely Merciful and Especially Merciful, is repeated around the Master of the Day of Judgment, so hope and awe stand in one frame."},{"t":"Guidance as daily bread","d":"The believer asks for the path seventeen times a day because guidance is not a possession but a provision, renewed like breath."},{"t":"Walking with a caravan","d":"The path is defined by companionship, the people Allah favored, so faith is never pictured as a road walked alone."}],"heart":["Recited slowly, al-Fatiha rearranges a person. You come to it full of your own concerns, and it makes you begin with His praise instead, and somewhere between al-hamd, the praise, and iyyaka na’budu, You alone we worship, the concerns shrink to their true size. It is a daily audit of direction: am I still on the path, still with the caravan of the favored ones, still afraid of drifting into anger or wandering?","The one who prays it with presence hears the other half of the conversation. The Prophet ﷺ taught that when the servant says the praise, Allah says: My servant has praised Me. Slow recitation turns the most familiar words in the world back into what they were the first night: a meeting."],"passages":[{"ref":"1:2","why":"Stop on the first word of praise and let it gather every blessing you did not think to count."},{"ref":"1:4","why":"The Master of the Day of Judgment: one verse that quietly settles every injustice you have seen."},{"ref":"1:5","why":"The hinge of the whole Quran, worship and help in a single breath, said in the plural because you never stand alone."},{"ref":"1:6","why":"The greatest request a creature can make, asked at least seventeen times a day because the need never closes."}],"connections":[{"to":2,"why":"Al-Fatiha ends asking for guidance and al-Baqarah answers on its first page: this is the Book, a guidance for the God-conscious."},{"to":15,"why":"In al-Hijr Allah names this surah the Seven Oft-Repeated and weighs it against the whole magnificent Quran."}],"virtue":{"text":"The Prophet ﷺ told Abu Sa’id ibn al-Mu’alla that al-Fatiha is the greatest surah in the Quran, and in the hadith qudsi Allah calls it a prayer divided between Himself and His servant, answered line by line. This is among the firmest virtue reports in the whole Book.","src":"Bukhari 4474; Muslim 395","level":"sunnah"}},
/* 2 Al-Baqarah, deep, 286 ayat */
2:{"n":2,"depth":"deep","context":["Al-Baqarah is the first long revelation of Madinah and it came down not at once but across most of the ten years there, verse joining verse as a scattered band of emigrants turned into a city with law, money, marriages, debts and enemies. Its earliest passages meet a community that had just arrived with nothing; its latest, by the report of many of the early commentators, include the verses of usury revealed near the very end of the Prophet's ﷺ life.","That slow assembly explains its shape. A reader expecting a single argument finds instead a whole civic order being handed down in the order a young society actually needed it, and running underneath the legislation is one continuous question: will this people keep the covenant that the peoples before them broke? The cow of the title is not decoration. It is a story about a community given a simple instruction and arguing its way around it, placed early as a warning to a community about to be given many."],"name_story":"Named for the cow that Bani Israil were commanded to sacrifice in verses 67 to 73. They were told to slaughter a cow, any cow, and instead asked what colour, what age, what kind, until the specification had narrowed so far that the animal was almost impossible to find. The surah keeps the name as a permanent caution: the more a heart looks for room to argue with a clear command, the heavier that command becomes. The Prophet ﷺ also called this surah and Aal Imran az-Zahrawan, the two luminous ones.","movements":[{"range":"1-20","h":"Three kinds of people","note":"The Book opens by sorting its readers before it teaches them: those who believe, those who refuse outright, and the far longer passage on those who say they believe and do not."},{"range":"21-39","h":"Adam, and the first refusal","note":"Humanity is made a khalifah on earth, the angels ask their question, Iblis refuses to bow, and the pattern of guidance offered and rejected begins."},{"range":"40-123","h":"Bani Israil, examined at length","note":"The longest sustained address to a previous community in the Qur'an: the favours given, the covenant taken, and each place it was broken, laid out for a new community about to receive the same trust."},{"range":"124-152","h":"Ibrahim and the change of qiblah","note":"The house at Makkah is rebuilt in the narrative and then in the prayer itself, as the direction of worship turns from Jerusalem and the community's obedience is tested in public."},{"range":"153-242","h":"The law of an ordinary life","note":"Patience, fasting, pilgrimage, fighting, wine and gambling, orphans, marriage, divorce, nursing, widowhood. Worship and household arrangement in one continuous breath."},{"range":"243-286","h":"Spending, and the closing prayer","note":"The stories of a king, a ruined town and Ibrahim's birds; Ayat al-Kursi at the centre; then charity, usury, the longest verse in the Qur'an on recording a debt, and the two verses that close the surah as a supplication."}],"themes":[{"t":"Covenant, kept or broken","d":"The surah is built around agreements: the one taken from Adam, the one taken from Bani Israil, and the one now being taken from the people of Madinah, who are shown at length what breaking it looks like."},{"t":"Law as an act of mercy","d":"Rules on debt, divorce and inheritance sit beside verses on prayer and fasting with no change of register, because the surah does not divide life into a sacred part and an administrative one."},{"t":"Guidance is not neutral ground","d":"It opens by saying the Book is guidance for those already conscious of Allah, and spends twenty verses on the ones who position themselves near faith without entering it."},{"t":"Obedience before explanation","d":"The cow, the qiblah and the fighting verses each test whether a command will be carried out before its wisdom has been made obvious."}],"heart":["Read slowly, Al-Baqarah stops feeling like a legal code and starts feeling like being moved into a house where every room already has a lamp lit in it. You arrive with a question about money, and it is answered. About grief, about a failing marriage, about what to do when you are afraid: answered, in the same voice, without any suggestion that one of these is a lesser subject than the others.","Its two ends are where most reciters break. Ayat al-Kursi in the middle is one sentence of sheer description, and the surah is silent around it. Then the final two verses turn, unannounced, from address into supplication, and the reciter finds himself no longer being told something but saying it: our Lord, do not burden us beyond what we can bear. It is the only proper way to leave a surah this heavy."],"passages":[{"ref":"2:255","why":"Ayat al-Kursi. The Prophet ﷺ named it the greatest verse in the Qur'an; it is one unbroken description of who Allah is, with nothing asked of you in it at all."},{"ref":"2:186","why":"Dropped into the middle of the fasting verses with no introduction: when My servants ask you about Me, I am near. No intermediary is mentioned in the whole verse."},{"ref":"2:216","why":"You may hate a thing and it is good for you. Read this on the far side of a year that did not go the way you asked."},{"ref":"2:285-286","why":"The closing two, which the Prophet ﷺ said would suffice whoever recites them at night. The surah ends by putting a prayer in your mouth."}],"connections":[{"to":1,"why":"Al-Fatiha ends asking to be shown the straight path, and Al-Baqarah opens on the next page answering: this is the Book, guidance."},{"to":3,"why":"The Prophet ﷺ paired these two as az-Zahrawan, the two luminous ones, and the second continues the argument with the People of the Book that the first began."}],"virtue":{"text":"Among the most firmly established of any surah. The Prophet ﷺ said not to make your houses graveyards, for the house in which Al-Baqarah is recited is one Satan does not enter, and that the last two verses suffice whoever recites them at night. He also described Al-Baqarah and Aal Imran coming on the Day of Rising like two clouds shading their reciter.","src":"Muslim 780; Bukhari 5009 and Muslim 807; Muslim 804","level":"sunnah"}},
/* 3 Aal Imran, deep, 200 ayat */
3:{"n":3,"depth":"deep","context":["Aal Imran belongs to Madinah and is framed by two encounters that could hardly be less alike. The first is intellectual: a delegation of Christians from Najran came to debate the Prophet ﷺ about the nature of Isa, and a long opening passage answers them with argument rather than dismissal, insisting on the shared line of prophets before it states where the two accounts part.","The second is a wound. The middle of the surah works through the defeat at Uhud, where seventy of the believers were killed, the Prophet ﷺ himself was injured, and the reversal came after a clear victory had already been in hand. The surah does not soften what happened. It names the disobedience that caused it, and then reframes the loss as a sifting rather than an abandonment."],"name_story":"Named for the family of Imran: the mother of Maryam who vowed the child in her womb to the service of the sanctuary, Maryam herself, and Isa. The naming is deliberate in a surah addressed partly to Christians. Before any disagreement is stated, the family at the centre of their reverence is honoured by name and given some of the most tender narrative in the Qur'an.","movements":[{"range":"1-63","h":"The argument with Najran","note":"Clear verses and ambiguous ones; the family of Imran; the birth of Maryam and of Isa; and the invitation to mubahalah, a mutual invocation, when argument had gone as far as it could."},{"range":"64-101","h":"Come to a common word","note":"An address to the People of the Book that begins from what is shared, then holds the line on what is not, and warns against being turned back after belief."},{"range":"102-120","h":"Hold the rope together","note":"The command to hold fast to the rope of Allah and not be divided, placed immediately before the battle account, which is where division had cost them."},{"range":"121-179","h":"Uhud, examined honestly","note":"The archers who left their post, the rumour that the Prophet ﷺ had been killed, the wounds, and the long correction that follows: this was a test, and the dead are alive with their Lord."},{"range":"180-200","h":"Those who reflect, and the last command","note":"The surah closes on people who remember Allah standing, sitting and lying down, and who look at the sky until it becomes an argument, then ends with four verbs: be patient, outlast, stand firm, and fear Allah."}],"themes":[{"t":"Steadfastness after defeat","d":"The surah's treatment of Uhud refuses both denial and despair. The loss was real, its cause was named, and it is placed inside a longer account in which it is not the end."},{"t":"One line of prophets","d":"Isa, Musa, Ibrahim and Muhammad ﷺ are set in a single sequence, so the disagreement with Najran is presented as a dispute inside one story rather than between two."},{"t":"Unity as a survival instruction","d":"Hold fast to the rope of Allah together and do not be divided arrives just before an account of what division actually cost, which is the surah's way of showing rather than telling."},{"t":"Creation as an argument","d":"The closing passage puts the case for faith not in a proof but in a habit: people who cannot look at the alternation of night and day without their minds moving."}],"heart":["Recited slowly, this is the surah for the period after something has gone badly wrong and the temptation is to conclude that you were never being helped. Its answer is unusually adult. It does not say the defeat did not happen or that it did not hurt. It says the defeat is inside a larger account, that some of it was your own doing, and that both of those can be true without meaning you have been abandoned.","Its final page changes the temperature entirely. After all the argument and all the blood it arrives at men and women standing at night saying our Lord, You did not create this in vain, and the Prophet ﷺ is reported to have wept when these verses came down, saying woe to whoever recites them and does not reflect on them."],"passages":[{"ref":"3:103","why":"Hold firmly to the rope of Allah, all together, and do not become divided. Placed exactly where the community was about to learn the cost of ignoring it."},{"ref":"3:159","why":"Addressed to the Prophet ﷺ immediately after Uhud: had you been harsh and hard-hearted, they would have scattered from around you. Said about the aftermath of a disaster caused partly by disobedience."},{"ref":"3:190-191","why":"The verses the Prophet ﷺ wept over: in the creation of the heavens and the earth are signs for those of understanding."},{"ref":"3:200","why":"The last verse, four commands in one breath, ending a surah about a defeat with an instruction to outlast."}],"connections":[{"to":2,"why":"The Prophet ﷺ named these two together as az-Zahrawan, and the argument begun in Al-Baqarah with the People of the Book is carried forward here."},{"to":19,"why":"Maryam is honoured at length in both, and the two accounts read best beside each other."}],"virtue":{"text":"The Prophet ﷺ said to recite the two luminous ones, Al-Baqarah and Aal Imran, for they will come on the Day of Rising like two clouds, or two flocks of birds in ranks, pleading for their companion. The virtue is reported for the pair rather than for this surah alone.","src":"Muslim 804","level":"sunnah"}},
/* 4 An-Nisa, deep, 176 ayat */
4:{"n":4,"depth":"deep","context":["An-Nisa is Madinan and its occasion is visible in almost every page. Uhud had left roughly seventy men dead in a small community, and the households they left behind were suddenly full of widows and of orphans holding property they were too young to defend. The surah legislates into that exact situation, which is why its opening verses move within a few lines from the creation of humanity out of a single soul to the property of orphans and the rights of women.","It is also the surah in which the hypocrites of Madinah are examined most closely. A community under military pressure had acquired members who calculated their allegiance week by week, and long passages describe the posture precisely: standing lazily for prayer, wavering between two sides, belonging fully to neither."],"name_story":"Named for the women who are its most persistent concern. The naming is not incidental. In a society where a widow could be inherited along with the property, the surah opens by grounding the rights of women in the fact that men and women were made from one soul, and then spends much of its length converting that into enforceable rules on inheritance, dower, marriage and the treatment of orphans.","movements":[{"range":"1-14","h":"One soul, then the ledger","note":"From the creation of humanity from a single soul straight into the property of orphans and the fixed shares of inheritance, with a severe warning about consuming what belongs to the defenceless."},{"range":"15-42","h":"Marriage and the household","note":"Who may be married, the dower as the woman's own right, conduct within the home, and the instruction to live with them in kindness."},{"range":"43-104","h":"Prayer, the Book, and a community at war","note":"Purification, the fear prayer, addresses to the People of the Book, and the rules of fighting including the prohibition on killing a believer."},{"range":"105-126","h":"Justice, even against your own","note":"Occasioned by a case in which a Muslim was nearly acquitted and a Jewish man nearly convicted of a theft the Muslim had committed. The surah refuses it."},{"range":"127-176","h":"The hypocrites, and the last verse of inheritance","note":"The wavering described at length, the correction of claims about Isa, and a closing verse on kalalah, the estate of one who dies with neither parent nor child, revealed last."}],"themes":[{"t":"Guarding those who cannot guard themselves","d":"Orphans and widows are named again and again, and the threat attached to consuming an orphan's property is among the sharpest in the Qur'an."},{"t":"Rights made specific","d":"The surah does not exhort men to be fair. It fixes shares, names the dower as the woman's own, and puts numbers where sentiment would have been easier."},{"t":"Justice without regard to who benefits","d":"Stand firmly for justice as witnesses for Allah, even against yourselves, your parents and your relatives. The occasion of the passage was a case where the community's instinct went the other way."},{"t":"Faith that is calculated","d":"The long treatment of hypocrisy describes not deception of others so much as a permanent hedging, which is why the imagery is of wavering rather than of lying."}],"heart":["Recited slowly, An-Nisa trains a particular kind of attention: it makes you notice who in a situation has no one to speak for them. Its rhythm is the repeated turn from a general principle to the specific person the principle protects, and a reciter comes away less able to leave the weakest party in a room out of the calculation.","It is also the surah that made the Prophet ﷺ weep. He asked Ibn Mas'ud to recite to him from it, and when the recitation reached the verse about bringing a witness from every nation and bringing you as a witness against these, he said enough, and Ibn Mas'ud looked up to find his eyes overflowing."],"passages":[{"ref":"4:1","why":"The opening: created from one soul, and from it its mate. Everything the surah legislates about men and women is built on this sentence."},{"ref":"4:58","why":"Render trusts to whom they are due, and judge with justice. Two clauses that between them cover most of public life."},{"ref":"4:135","why":"Stand firmly for justice even against yourselves, your parents and your kin. Revealed about a case the community had been getting wrong."},{"ref":"4:41","why":"The verse at which the Prophet ﷺ told Ibn Mas'ud to stop, because he was weeping."}],"connections":[{"to":3,"why":"Aal Imran works through the defeat at Uhud; An-Nisa legislates for the households that defeat emptied."},{"to":65,"why":"At-Talaq takes up divorce in detail, and the two are read together on that subject."}],"virtue":{"text":"There is no report promising a specific reward for reciting An-Nisa. What is authentically reported is an incident: the Prophet ﷺ asked Ibn Mas'ud to recite from this surah, and stopped him at verse 41 with his eyes overflowing. That is a report about what the surah did to him, and is given here as that rather than as a promised merit.","src":"Bukhari 4582; Muslim 800","level":"sunnah"}},
/* 5 Al-Ma'idah, deep, 120 ayat */
5:{"n":5,"depth":"deep","context":["Al-Ma'idah is among the last surahs to come down, from the years of treaties, settled authority and the Farewell Pilgrimage. The community it addresses is no longer improvising: it has borders, agreements with other powers, and the ordinary business of a state, and the surah opens accordingly with a command to fulfil contracts.","It carries the verse the community understood immediately as a closing: this day I have perfected your religion for you. Umar is reported to have wept when he heard it, because a thing that is completed has nothing further to come. It was revealed at Arafah during the Farewell Pilgrimage, and the Prophet ﷺ died some months later."],"name_story":"Named for the ma'idah, the table spread with food that the disciples of Isa asked to be sent down from heaven as a sign. The story sits near the end of the surah and is characteristic of it: a request for a sign is granted, and comes attached to a warning that a sign refused after being given is worse than one never asked for.","movements":[{"range":"1-11","h":"Fulfil the contracts","note":"The opening command, then the lawful and unlawful in food, purification, and the covenant taken from the community."},{"range":"12-43","h":"Covenants broken before","note":"The covenants of Bani Israil and of the Christians, the two sons of Adam, and the verse on the sanctity of a single life."},{"range":"44-86","h":"Judging by what was revealed","note":"The relationship of the three scriptures, the command to judge between them by what Allah revealed, and warnings against taking as allies those who mock the religion."},{"range":"87-108","h":"Do not make unlawful what is good","note":"Against inventing prohibitions, then oaths, intoxicants and gambling, game while in ihram, and the law of bequest."},{"range":"109-120","h":"Isa questioned","note":"The table from heaven, and the exchange in which Isa is asked whether he told people to take him and his mother as gods, and answers that he said only what he was commanded."}],"themes":[{"t":"A contract is a religious obligation","d":"The surah opens on fulfilling agreements and returns to oaths and covenants repeatedly, treating a broken word as a matter of faith rather than of manners."},{"t":"Justice owed to people you dislike","d":"Do not let the hatred of a people prevent you from being just. Be just; that is nearer to righteousness. The verse assumes the hatred is real and rules on it anyway."},{"t":"A completed religion","d":"The verse of perfection closes the legislative project, and much of the surah reads like a final tidying of loose obligations."},{"t":"Do not invent prohibitions","d":"A distinct warning against forbidding the good things Allah has made lawful, aimed at a piety that expresses itself by adding restrictions."}],"heart":["Recited slowly, the surah's refrain of covenant begins to feel like a handshake tightening. Being Muslim is presented here as a promise already accepted and now waiting to be kept, and the reciter is repeatedly asked whether the specific agreements of his own week, the contract, the oath, the debt, the marriage, are being honoured with the seriousness the surah assumes.","Its hardest instruction for most readers is the one about justice toward people you dislike. It does not ask you to stop disliking them. It fixes your conduct while the dislike remains, which is a far more usable command than an instruction to feel differently."],"passages":[{"ref":"5:3","why":"This day I have perfected your religion for you. Revealed at Arafah on the Farewell Pilgrimage; Umar is reported to have wept because completion means nothing more is coming."},{"ref":"5:8","why":"Do not let the hatred of a people prevent you from being just. The most demanding sentence in the surah."},{"ref":"5:32","why":"Whoever saves one life, it is as if he saved humanity entirely. Stated as something prescribed to Bani Israil, and carried forward."},{"ref":"5:87","why":"Do not make unlawful the good things Allah has made lawful for you. A correction aimed at excess rather than at laxity."}],"connections":[{"to":2,"why":"Both are long Madinan legislations, and Al-Ma'idah closes much of what Al-Baqarah opened."},{"to":4,"why":"The two together carry most of the family and civic law of the Qur'an."}],"virtue":{"text":"No authentic report establishes a specific merit for reciting Al-Ma'idah. Its standing rests on its content and its timing: it carries the verse of the perfection of the religion, revealed at Arafah in the final year, which the community recognised at once as a closing.","src":"no authentic virtue report","level":"none"}},
/* 6 Al-An'am, light, 165 ayat */
6:{"n":6,"depth":"light","context":"A late Makkan surah, reported to have come down in a single descent escorted by ranks of angels. It answers the theology of the idolaters at its root, dismantling their gods with patient argument rather than decree.","themes":["Pure monotheism argued","Ibrahim’s searching heart","Keys of the unseen","Answering idolatry"],"heart":"Its long, patient reasoning does something rare to a slow reciter: shirk, setting partners beside Allah, stops feeling like other people’s history and starts feeling like a daily temptation being named and cured.","passage":{"ref":"6:162","why":"The verse that gathers a whole life, prayer, sacrifice, living, dying, into one direction."}},
/* 7 Al-A'raf, light, 206 ayat */
7:{"n":7,"depth":"light","context":"A long Makkan surah rehearsing the whole human story, from Adam and Iblis through Nuh, Hud, Salih, Lut, Shu’ayb, and Musa. Its name is the high wall between Paradise and Fire where a final sorting waits.","themes":["Adam and Iblis","Nations that refused","The primordial covenant","Heights between destinies"],"heart":"Recited slowly, it feels like watching your own choices repeat across centuries of ruined towns, until the covenant of every unborn soul surfaces like a memory you had forgotten was yours.","passage":{"ref":"7:172","why":"The covenant before birth: Am I not your Lord? They said, yes, we bear witness."}},
/* 8 Al-Anfal, light, 75 ayat */
8:{"n":8,"depth":"light","context":"Revealed after Badr, the first great battle, when three hundred ill-equipped believers defeated Quraysh. It settles the dispute over spoils and reads the victory back to its true causes: order, obedience, and unseen help.","themes":["Badr remembered","Hearts that tremble","Victory’s true causes","Unity under command"],"heart":"A slow reciter stops counting swords and starts counting states of the heart: trembling at His mention, increase through His verses, trust in Him alone, the surah quietly grades you on its opening lines.","passage":{"ref":"8:2","why":"The portrait of believers whose hearts tremble and whose faith grows with every recited verse."}},
/* 9 At-Tawbah, deep, 129 ayat */
9:{"n":9,"depth":"deep","context":["At-Tawbah comes from around the ninth year in Madinah and the campaign to Tabuk, a march of several hundred miles in extreme heat at harvest time, undertaken against the Byzantine frontier. It is the surah of a community strong enough to have obligations it would rather avoid, and it is unsparing about those who found reasons not to go.","It is also the surah that cancels standing agreements with those who had broken them, and its opening passages read as a formal notice rather than as a sermon. The severity is real and the surah does not apologise for it. What it does, repeatedly, is leave a door open on the other side of the severity, which is why it is named for repentance."],"name_story":"Called At-Tawbah, the Repentance, and also Bara'ah, the Disavowal, which names the two halves of its work. It is the only surah that does not open with the Bismillah, and the early authorities differ on why: one view, reported from Uthman, is that the community was uncertain whether it and Al-Anfal were one surah or two; another is that a declaration of disavowal does not open with the naming of mercy. The honest position is that the reason is disputed.","movements":[{"range":"1-37","h":"The disavowal","note":"Treaties with those who had broken them are cancelled with four months' notice; those who kept their agreements are to be kept with to the end of their term."},{"range":"38-72","h":"Tabuk, and the excuses","note":"The command to march, the heat, the harvest, and a long examination of those who asked to be left behind, alongside the account of the cave."},{"range":"73-99","h":"The hypocrites named","note":"Their oaths, their mosque built to divide, and the distinction drawn between them and the bedouins who simply did not yet know."},{"range":"100-118","h":"The three who were left behind","note":"Ka'b ibn Malik and two others who told the truth about having no excuse, were boycotted for fifty nights, and were then forgiven by name."},{"range":"119-129","h":"Be with the truthful","note":"The closing command, and the last two verses, which several reports identify as among the final revelation."}],"themes":[{"t":"Repentance, even after the worst of it","d":"The surah's severity exists to make its openings meaningful. The three who stayed behind were cut off for fifty nights and then forgiven in revelation."},{"t":"Truth-telling when a lie would be easier","d":"Ka'b's account is preserved because he refused to invent an excuse when eighty others had, and his honesty is what the surah rewards."},{"t":"Agreements honoured even with enemies","d":"The cancellation applies to those who broke faith; those who kept it are explicitly to be kept with until their term ends."},{"t":"Hypocrisy as an organised thing","d":"The mosque built to cause harm shows the surah treating hypocrisy as institutional rather than merely personal."}],"heart":["Its severity does not harden a slow reciter so much as corner him. There is no room in this surah to be vaguely committed; it keeps sorting people by what they actually did when it was inconvenient, and the reciter finds himself being sorted along with them.","Then it breaks open. The account of the three left behind is one of the most human passages in the Qur'an: the earth became narrow for them despite its vastness, and their own souls became narrow, and they knew there was no refuge from Allah except in Him. A repentance that arrives late, after fifty nights of being unable to breathe, is met and accepted."],"passages":[{"ref":"9:40","why":"The cave verse: do not grieve, indeed Allah is with us. Two men, hunted, with the pursuers close enough to be heard."},{"ref":"9:118","why":"The earth became narrow for them despite its vastness. The most exact description of a guilty conscience in the Book."},{"ref":"9:119","why":"Be with the truthful. Placed immediately after the account of three men whose truthfulness cost them fifty nights."},{"ref":"9:128","why":"There has come to you a Messenger from among yourselves. Grieved by what grieves you, concerned over you. Among the last verses revealed."}],"connections":[{"to":8,"why":"Al-Anfal precedes it and treats the earlier battle; the two were close enough in the early community's reading that their separation was discussed."},{"to":66,"why":"At-Tahrim carries the other major passage on turning back to Allah, in a domestic rather than a military setting."}],"virtue":{"text":"No authentic report establishes a specific merit for reciting At-Tawbah. The question most often asked about this surah is not its merit but the absence of the Bismillah at its head, and on that the early authorities genuinely differ, so the companion reports the disagreement rather than choosing between the views.","src":"no authentic virtue report; the Bismillah question is disputed among the early authorities","level":"none"}},
/* 10 Yunus, light, 109 ayat */
10:{"n":10,"depth":"light","context":"A Makkan surah from the years when Quraysh demanded a different Quran or a dazzling sign. It answers with Allah’s unhurried way, revelation rather than spectacle, and recalls the people of Yunus, the one town whose faith arrived in time.","themes":["Revelation over spectacle","Allah’s unhurried decree","A town that believed","Friends without fear"],"heart":"Recited slowly, it loosens the demand that Allah act on your schedule: the reciter feels panic give way to the calm of the awliya’, Allah’s close friends, upon whom there is no fear, nor do they grieve.","passage":{"ref":"10:62","why":"The verse of Allah’s friends: no fear upon them, nor shall they grieve."}},
/* 11 Hud, light, 123 ayat */
11:{"n":11,"depth":"light","context":"Makkan, from the hardest years after the deaths of Khadijah and Abu Talib. The Prophet ﷺ said that Hud and its sisters turned his hair gray: its prophets stand nearly alone, commanded to remain absolutely straight while their worlds collapse.","themes":["Standing firm alone","Nuh’s ark and son","Punished nations","Istiqamah, unbending uprightness"],"heart":"The slow reciter feels the weight that grayed the Prophet’s ﷺ hair: the command fastaqim, stand unswervingly straight, lands not as a slogan but as a lifelong posture held under pressure.","passage":{"ref":"11:112","why":"The command that aged the Prophet ﷺ: stand firm as you have been ordered."}},
/* 12 Yusuf, deep, 111 ayat */
12:{"n":12,"depth":"deep","context":["Surah Yusuf came down in Makkah in the hardest stretch of the Prophet's ﷺ life, in or near the year that took both Khadijah and Abu Talib from him, when the protection he had relied on for a decade was gone and Ta'if had already turned him away. Several of the early commentators report that it answered a challenge put to him about how the children of Israel came to be in Egypt.","What arrived was not a legal ruling or a warning, but a story: one continuous narrative from the first verse to nearly the last, the only place in the Qur'an where that happens. A man being told he has lost everything is given an account of another man who lost everything, in order, and was not lost at all. It was consolation delivered as narrative, which is a particular kind of mercy."],"name_story":"Named for Yusuf, and the Qur'an itself calls what follows ahsan al-qasas, the best of stories, in its third verse. The claim is not sentimental. Nowhere else does the Qur'an give a single life this much unbroken attention, and no other passage carries a reader through so complete an arc: a well, a household, a prison, a throne, and a room in which the brothers who threw him in do not recognise the man in front of them.","movements":[{"range":"1-6","h":"A dream, and a father who understands it","note":"Eleven stars, the sun and the moon prostrating. Ya'qub knows immediately what it means and tells his son to keep it to himself."},{"range":"7-20","h":"The brothers, and the well","note":"Jealousy reasoned into a plan, the shirt returned with false blood, and a father who says something remarkable: beautiful patience."},{"range":"21-35","h":"The house in Egypt","note":"Bought, raised in privilege, and then the scene with the wife of al-Aziz, which the Qur'an handles with unusual restraint and unusual precision."},{"range":"36-57","h":"The prison years","note":"Two fellow prisoners, two dreams, and Yusuf using the moment of their attention to speak about the oneness of Allah before he interprets anything."},{"range":"58-93","h":"The brothers return, not knowing","note":"Grain, a hidden cup, Binyamin held back, and a father going blind with grief while insisting he complains only to Allah."},{"range":"94-111","h":"The shirt, and the forgiveness","note":"Sight restored, the family reunited in Egypt, the childhood dream fulfilled decades late, and a sentence of forgiveness offered at the exact moment revenge was available."}],"themes":[{"t":"Beautiful patience","d":"Sabrun jamil, patience with no complaint made to people. Ya'qub says it twice, and the surah shows him weeping constantly while saying it, so the phrase cannot mean the absence of grief."},{"t":"Decree working through people's worst choices","d":"Every step toward Yusuf's rise is somebody's sin against him. The surah never excuses the brothers, and never suggests the outcome required their innocence."},{"t":"Power as the moment of testing","d":"The character of the man is settled not in the well or in the prison but in the room where he finally has authority over the people who put him there."},{"t":"The long delay","d":"The dream at the start is fulfilled in the final pages, decades later, by which time everyone who could have doubted it has aged."}],"heart":["Read slowly, the surah teaches one sentence that most people need for the rest of their lives: I only complain of my anguish and my sorrow to Allah. Ya'qub is not stoic. He weeps until he loses his sight. What he does not do is take his grief to an audience, and the surah quietly draws the line between carrying pain and performing it.","The other thing it teaches is patience with the length of things. Nothing in this story resolves quickly. The reciter, who usually wants a rescue by the end of the page, is made to wait through a well, a household, a false accusation, years of prison and a famine before the dream from verse four is allowed to come true."],"passages":[{"ref":"12:18","why":"So beautiful patience, and Allah is the one whose help is sought against what you describe. Said by a father who has just been handed his son's bloodied shirt."},{"ref":"12:86","why":"I only complain of my anguish and my sorrow to Allah. The most practical verse in the surah for anyone carrying something they cannot say out loud."},{"ref":"12:87","why":"Do not despair of the mercy of Allah. Spoken to sons setting out on what looks like a hopeless search."},{"ref":"12:92","why":"No blame upon you today. Forgiveness spoken at the one moment when revenge was both possible and, by any ordinary reckoning, deserved."}],"connections":[{"to":93,"why":"Ad-Duha was revealed to console the Prophet ﷺ in the same Makkan years, and the two answer the same fear with different instruments."},{"to":21,"why":"Al-Anbiya gathers the prophets who called out in distress and were answered, which is the compressed version of what this surah tells at length."}],"virtue":{"text":"No authentic report establishes a specific merit for reciting Surah Yusuf, and several that circulate widely are graded weak or fabricated. Its standing rests on what the Qur'an says of it in its own third verse, that it is the best of stories, which is a stronger footing than any of the reports it is being given.","src":"no authentic virtue report; the Qur'an's own description at 12:3","level":"none"}},
/* 13 Ar-Ra'd, deep, 43 ayat */
13:{"n":13,"depth":"deep","context":["Ar-Ra'd sits at a boundary the commentators discuss: its voice is Makkan and its concerns are those of the Makkan period, yet some orderings place it among the Madinan surahs, and the early authorities differ. The honest position is that its period is disputed, and nothing in the surah's meaning depends on which view is taken.","Its setting is a demand for spectacle. The deniers wanted a sign of the kind they could point at, a mountain moved or a dead man raised, and the surah's answer is to redirect their attention to what was already falling on them: rain arriving on dead ground, thunder glorifying Allah in awe, and a revelation doing to hearts what the water does to the earth."],"name_story":"Named for the thunder in verse thirteen, which is described as glorifying Allah with praise, as do the angels, out of awe of Him. The naming is characteristic of the surah: it takes the loudest ordinary thing in the sky and points out that it is already doing what the people demanding a miracle are refusing to do.","movements":[{"range":"1-7","h":"The signs already given","note":"Raised heavens without pillars, the sun and the moon running to an appointed term, and neighbouring plots of land watered with the same water that yield differently."},{"range":"8-18","h":"What He knows, and what glorifies Him","note":"Every female's burden, the guardians before and behind a person, the thunder, the lightning, and the parable of the flood that carries away foam while what benefits people remains."},{"range":"19-29","h":"Those of understanding","note":"People who fulfil the covenant, join what Allah commanded to be joined, and repel evil with good, ending in the verse the whole surah is best known for."},{"range":"30-43","h":"Signs are not the problem","note":"Even if a Qur'an could move mountains or make the dead speak, the matter belongs to Allah, and the messenger's task is delivery, not compulsion."}],"themes":[{"t":"Signs over spectacle","d":"The demand for a dramatic miracle is answered by pointing at rain, growth and thunder, on the argument that a person unmoved by these would not be moved by more."},{"t":"What lasts and what is foam","d":"The parable of the valley in flood, where the froth on the surface goes and what benefits people stays in the earth, is the surah's compressed theory of everything."},{"t":"Remembrance as the settling of the heart","d":"The most quoted verse in the surah is a plain statement of mechanism rather than an exhortation."},{"t":"Delivery, not compulsion","d":"The closing passage limits the messenger's responsibility, which is a mercy to everyone who has ever been unable to convince someone they love."}],"heart":["Recited slowly, this surah works on a specific kind of restlessness: the state of a person who is waiting for God to do something obvious before they will settle. It does not scold that person. It walks them past a series of ordinary things, water and fruit and lightning, until the demand starts to look like a way of not looking.","And then it gives them the sentence they were actually looking for. Unquestionably, by the remembrance of Allah hearts find rest. Not entertainment, not resolution of their circumstances: rest, which is a smaller word and the only one that fits."],"passages":[{"ref":"13:28","why":"Those who believe and whose hearts find rest in the remembrance of Allah. The verse most often needed and least often quoted in full, since the first half names who it is describing."},{"ref":"13:11","why":"Allah does not change the condition of a people until they change what is in themselves. Frequently quoted; worth reading in its own context, which is about guardians and decree."},{"ref":"13:17","why":"The parable of the flood and the foam. One image for how to tell what will still be here later."},{"ref":"13:31","why":"Even if a Qur'an could move mountains, the decision belongs to Allah. The verse that closes the argument about miracles."}],"connections":[{"to":10,"why":"Yunus answers the same demand for a different Qur'an or a dazzling sign, and the two make one argument."},{"to":2,"why":"Al-Baqarah's opening sorts the same three responses to revelation that this surah illustrates."}],"virtue":{"text":"No authentic report establishes a specific merit for reciting Surah Ar-Ra'd. It is included in this companion at depth because of one verse, 13:28, which carries more weight in ordinary Muslim life than most whole surahs do.","src":"no authentic virtue report","level":"none"}},
/* 14 Ibrahim, light, 52 ayat */
14:{"n":14,"depth":"light","context":"Late Makkan, when Quraysh had answered years of blessing with denial. It centers on Ibrahim’s prayer over the barren valley of Makkah itself, asking security for its people and gratitude for its harvests, a prayer the deniers were living inside.","themes":["Gratitude multiplies blessing","Ibrahim’s valley prayer","Word like a tree","Ingratitude’s ruin"],"heart":"The slow reciter finds shukr, gratitude, redefined as survival: if you give thanks, I will surely increase you, spoken by the Lord whose favors the reciter is breathing even mid-verse.","passage":{"ref":"14:7","why":"Allah’s open pledge: if you are grateful, I will certainly give you more."}},
/* 15 Al-Hijr, light, 99 ayat */
15:{"n":15,"depth":"light","context":"Makkan, named for the rock-hewn dwellings of Thamud. Revealed while mockery of the Prophet ﷺ was at its sharpest, it promises that the Reminder is guarded by Allah Himself and prescribes the mocked messenger a strange medicine: glorify, prostrate, and worship until certainty comes.","themes":["The guarded Reminder","Iblis at the beginning","Thamud’s carved homes","Worship until certainty"],"heart":"Recited slowly, its ending works like a prescription on the reciter: when your chest tightens at what they say, glorify, prostrate, and keep going, worship itself becomes the treatment for a constricted heart.","passage":{"ref":"15:9","why":"Allah’s own guarantee: We sent down the Reminder, and We are its Guardian."}},
/* 16 An-Nahl, deep, 128 ayat */
16:{"n":16,"depth":"deep","context":["An-Nahl is Makkan and is known among the commentators as the surah of blessings. It was revealed to a people who were using Allah's own gifts, their cattle, their rain, their trade routes, the shade of their own dwellings, as the raw material of a life that denied Him, and its method is to walk them through those gifts one at a time until the denial becomes conspicuous.","Its closing verses belong to a harder moment. They address a community being persecuted and instruct it to respond in proportion, and then, immediately, to prefer patience. Several reports connect the final passage to the killing of Hamza at Uhud, which would place the ending later than the body of the surah, and the commentators discuss it."],"name_story":"Named for the bee in verses 68 and 69, which is described as having been given wahy, inspiration, by its Lord: take homes in the mountains, in the trees, and in what they construct. Out of its bellies comes a drink of varying colours in which there is healing for people. A small industrious creature is given a form of the same word used for revelation, and the surah lets that sit without further comment.","movements":[{"range":"1-34","h":"The creation, itemised","note":"Cattle, warmth, food, beauty in bringing them home at evening, the horses, the stars for navigation. Blessings listed until the listing becomes an argument."},{"range":"35-64","h":"The excuse examined","note":"The claim that had Allah willed they would not have associated, answered by pointing at the messengers sent to every nation."},{"range":"65-89","h":"Water, milk, honey","note":"The bee, the drink with healing in it, the fruits from which people take both intoxicant and good provision, and the parables of dependence."},{"range":"90-110","h":"Justice, excellence, and giving","note":"The verse recited at the close of Friday sermons across the Muslim world, then the warning against breaking oaths after confirming them."},{"range":"111-128","h":"Ibrahim, and the last instruction","note":"Ibrahim described as a nation in himself, the food laws, the call to the way of your Lord with wisdom and good counsel, and the closing command to patience."}],"themes":[{"t":"Blessing as an argument","d":"The surah does not argue from logic but from inventory. It names what the listener is holding, wearing, eating and riding, and asks where it came from."},{"t":"Gratitude, and its opposite","d":"The favours are countless, and the surah says so plainly: if you should count the favours of Allah, you could not enumerate them."},{"t":"How to call people","d":"Invite to the way of your Lord with wisdom and good instruction, and argue with them in the way that is best. The method is prescribed as carefully as the message."},{"t":"Proportion, then patience","d":"The closing verses permit a response in kind and then immediately say that patience is better, which is the surah's characteristic move."}],"heart":["A slow reciter starts auditing the room around him. Water, cloth, shade, the food in the house, and the surah turns each item into a question that has only one honest answer. By the time it reaches verse ninety, justice and excellence and giving to relatives feel less like commands and more like the rent owed on everything already listed.","The verse most readers carry away is 16:97, the promise of a good life to whoever works righteousness while believing. It is worth noticing where it sits: in a surah about blessing, immediately after a passage about persecution, offered to people whose circumstances were not about to improve."],"passages":[{"ref":"16:18","why":"If you should count the favours of Allah, you could not enumerate them. Try it for one minute and the verse proves itself."},{"ref":"16:97","why":"Whoever does righteousness while believing, We will surely give them a good life. The promise is hayat tayyiba, a good life, not an easy one."},{"ref":"16:90","why":"Justice, excellence, and giving to relatives. Recited at the end of the Friday sermon in most of the Muslim world."},{"ref":"16:125","why":"Invite to the way of your Lord with wisdom and good instruction. The manner of calling is legislated, not left to temperament."}],"connections":[{"to":14,"why":"Ibrahim carries the other great statement on gratitude: if you are grateful, I will increase you."},{"to":31,"why":"Luqman opens by defining wisdom itself as gratitude, which is An-Nahl's argument in one sentence."}],"virtue":{"text":"No authentic report establishes a specific merit for reciting An-Nahl. Its place in ordinary Muslim life is secured instead by a single verse, 16:90, which is recited from the pulpit at the close of the Friday sermon every week in most of the Muslim world.","src":"no authentic virtue report","level":"none"}},
/* 17 Al-Isra, deep, 111 ayat */
17:{"n":17,"depth":"deep","context":["Al-Isra is Makkan and opens on the Night Journey, which came in the bleakest stretch of the Prophet's ﷺ mission: after the deaths of Khadijah and Abu Talib, after Ta'if had driven him out, when the human support around him had effectively collapsed. The journey from the Sacred Mosque to the furthest mosque is stated in a single verse and not elaborated, and the surah moves on.","What follows is unexpected after an opening like that. Rather than dwelling on the miracle, the surah lays out a charter of ordinary conduct: how to treat parents, relatives, the traveller, your own children, your money, your speech, your walk. A man given the most extraordinary night in human history is handed, in the same surah, a list of instructions about being decent at home."],"name_story":"Named for the isra, the night journey itself, and also known as Bani Israil for the long address to the children of Israel that follows. The two names mark the two halves of the surah: an event that cannot be repeated, and a code of conduct that must be, nightly.","movements":[{"range":"1-8","h":"The journey, and a warning","note":"The night journey in one verse, then the two occasions of corruption foretold for Bani Israil and the promise that the pattern repeats: if you return, We will return."},{"range":"9-22","h":"This Qur'an guides to what is most upright","note":"The haste of the human being, the night and day as two signs, and the record that will be spread open."},{"range":"23-39","h":"The charter","note":"Parents, kin, the needy, the traveller, moderation in spending, the prohibition of killing children out of fear of poverty, honesty in measure, and the warning not to pursue what you have no knowledge of."},{"range":"40-72","h":"The objections answered","note":"The claim of daughters for Allah, the seven heavens glorifying Him, Iblis and his stake in the children of Adam."},{"range":"73-111","h":"Steadiness, and the Qur'an itself","note":"The pressure to compromise slightly, the prayer at the two ends of the day, the soul as a matter belonging to Allah, and the challenge that humans and jinn together could not produce the like of this."}],"themes":[{"t":"Conduct as the response to honour","d":"The surah answers the greatest miracle given to the Prophet ﷺ with a list of household instructions, which is a statement about where religion actually lives."},{"t":"Parents, at the age when it is hard","d":"The passage specifies the moment: when one or both reach old age with you. It legislates for the difficult stage, not the easy one."},{"t":"The Qur'an as healing","d":"We send down of the Qur'an that which is healing and mercy for the believers, stated in a surah that opens on the Prophet's ﷺ worst year."},{"t":"Pressure to shift slightly","d":"They were near to tempting you away from what We revealed. The temptation described is not to abandon the message but to soften it a little."}],"heart":["Recited slowly, the middle section reads like being handed your own conduct one line at a time. The reciter lowers his voice at the verse about voices, slows his walk at the verse about walking, and arrives at rabbi irhamhuma, my Lord have mercy on them both, owing a debt to two aging faces he can picture exactly.","The wing of humility in verse 24 is the image most people keep. A bird lowering its wing to shelter something small, offered as the posture a grown adult should take toward a parent who has become difficult, forgetful, or demanding."],"passages":[{"ref":"17:23","why":"Say not to them a word of disrespect. The Arabic is uff, the smallest sound of irritation, and it is the thing prohibited by name."},{"ref":"17:24","why":"Lower to them the wing of humility out of mercy, and say: my Lord, have mercy on them as they raised me when I was small."},{"ref":"17:36","why":"Do not pursue what you have no knowledge of. The hearing, the sight and the heart will all be questioned. Written before anyone could forward a rumour to thousands of people in a second."},{"ref":"17:82","why":"We send down of the Qur'an that which is healing and mercy for the believers."}],"connections":[{"to":31,"why":"Luqman gives the parallel charter, taught by a father to a son rather than revealed to a community."},{"to":53,"why":"An-Najm treats the other part of that night, the ascent, and the two are usually read together."}],"virtue":{"text":"Aisha reported that the Prophet ﷺ would not sleep until he had recited Bani Israil, which is this surah, and Az-Zumar. The report is graded hasan by a number of scholars rather than being of the highest grade, and it describes his practice rather than promising a reward, so it is given here with both qualifications attached.","src":"Tirmidhi 2920; graded hasan","level":"sunnah"}},
/* 18 Al-Kahf, deep, 110 ayat */
18:{"n":18,"depth":"deep","context":["Al-Kahf came down in Makkah in the later middle years, when the argument between the Prophet ﷺ and Quraysh had hardened into siege. Ibn Ishaq relates from Ibn Abbas that Quraysh sent an-Nadr ibn al-Harith and Uqbah ibn Abi Mu’ayt to the Jewish scholars of Yathrib for questions no ordinary man could answer: ask him about young men who vanished in the first age, about a traveler who reached the east and the west of the earth, and about the ruh, the spirit. The chain of this report has a gap scholars are honest about, so it is background rather than certainty, but the surah plainly answers exactly those questions, and it answers them on its own terms.","In the Prophet’s ﷺ life this surah arrived as equipment for endurance. Its four stories map the four trials of any believing community: faith under persecution in the young men of the cave, wealth in the man of the two gardens, knowledge in Musa’s journey to Khidr, and power in Dhul-Qarnayn. The early Muslims, then being pressed toward their own migrations, heard in it that a small band who flee to Allah will be covered by His mercy, and later generations took it as the Friday surah, a weekly washing of the eyes against the glitter of the world."],"name_story":"Al-Kahf means the Cave, after the hollow in the mountain where the young believers slept for three hundred and nine years under Allah’s care. The name holds the surah’s promise: when a people have nothing left but their faith, Allah makes a rock wall into a sanctuary. Some early teachers also grouped it among the surahs beginning with al-hamd, the praise, since it opens by praising the One who sent down a Book with no crookedness in it.","movements":[{"range":"1-8","h":"A straight Book, a decorated earth","note":"Praise for a scripture without crookedness, a warning to those who claim a son for Allah, and the announcement that everything on earth is a test dressed as ornament."},{"range":"9-26","h":"The young men of the cave","note":"A handful of youths choose their Lord over their city, and Allah turns them in their sleep while centuries pass, teaching that He guards what is entrusted to Him."},{"range":"27-46","h":"Companions and the two gardens","note":"The Prophet ﷺ is told to keep his soul patient with the poor believers, then a rich man loses two gardens to a single night, and wealth is renamed: passing adornment beside lasting deeds."},{"range":"47-59","h":"The day the record opens","note":"Mountains move, humanity stands in rows, the book leaves out nothing small or great, and Iblis is exposed as an enemy taken for a friend."},{"range":"60-82","h":"Musa at the meeting of seas","note":"The greatest prophet of his age travels as a student, and three shocking acts unfold into mercy, showing that Allah’s decree is kindness wearing the mask of loss."},{"range":"83-110","h":"Dhul-Qarnayn and the closing scales","note":"A just king reaches the edges of the earth and credits only his Lord, Yajuj and Majuj are sealed behind iron, and the surah ends weighing deeds, an ocean of words, and one prophet ﷺ who is only a man receiving revelation."}],"themes":[{"t":"Trial wearing four faces","d":"Faith, wealth, knowledge, and power are each tested in one story, and in each the same answer holds: attach the thing to Allah or lose it."},{"t":"Refuge and divine care","d":"From the cave to the wall built for two orphans, the surah shows Allah quietly managing His servants’ affairs while they sleep."},{"t":"The limits of knowing","d":"Musa, Khidr, and the sea of ink teach that human knowledge is a bird’s beakful of the ocean, so humility is the scholar’s first tool."},{"t":"Saying in sha’ Allah","d":"Even the Prophet ﷺ is taught never to promise tomorrow without saying if Allah wills, tying every plan to the One who owns time."}],"heart":["Read slowly, al-Kahf works like a corrective lens for the dunya, the lower life. Verse by verse it takes the four things people build identity on, belonging, money, cleverness, and reach, and shows each one held safely only in Allah’s hand. The reciter rises from it lighter: less impressed by gardens, less afraid of kings, more willing to say I do not know, more ready to leave a city if the city demands his religion.","It is also a surah of tenderness toward the small. Allah remembers sleeping youths, a dog at a threshold, two orphans with a treasure under a leaning wall, and a servant told to keep company with those who call on their Lord morning and evening. Whoever recites it on Friday steps out of the week’s noise into that company, and the light between the two Fridays is, in part, this changed way of seeing."],"passages":[{"ref":"18:10","why":"The prayer of the young men entering the cave: mercy from Your presence, and rightness prepared for us, the du’a of everyone stepping into the unknown."},{"ref":"18:24","why":"The verse that teaches in sha’ Allah, if Allah wills, and how to remember your Lord the moment you forget."},{"ref":"18:28","why":"Keep yourself patiently with those who call on their Lord: the Quran’s definition of good company, addressed first to the Prophet ﷺ himself."},{"ref":"18:46","why":"Wealth and children renamed as passing adornment, while lasting righteous deeds are declared the better hope."},{"ref":"18:110","why":"The closing verse: one God, righteous work, and no partners in worship, the whole surah folded into a farewell."}],"connections":[{"to":17,"why":"Al-Isra ends with praise for the One who has taken no son, and al-Kahf opens by warning, with the same praise, those who claim He has."},{"to":85,"why":"The youths of the cave and the believers of the ditch are one lesson in two endings: faith held under fire, and Allah’s pleasure as the true victory."}],"virtue":{"text":"The Prophet ﷺ said that whoever memorizes ten verses from the beginning of al-Kahf is protected from the Dajjal, the false messiah. Its recitation on Friday, bringing light between the two Fridays, is reported from Abu Sa’id al-Khudri and is well supported: many scholars grade it authentic, whether as the Prophet’s ﷺ word or a companion’s established teaching.","src":"Muslim 809; al-Hakim 2/399","level":"sunnah"}},
/* 19 Maryam, deep, 98 ayat */
19:{"n":19,"depth":"deep","context":["Maryam is Makkan and belongs to the years of open persecution, when a group of the believers left for Abyssinia to seek refuge with the Negus, a Christian king. When Quraysh sent envoys to demand their return, Ja'far ibn Abi Talib recited from this surah in his court, and the report is that the king wept until his beard was wet and refused to hand them over.","That is the setting the surah was built for. It reaches across to a Christian listener with the two things he already reveres, Yahya and Isa and the woman who bore him, tells those stories with extraordinary tenderness, and only then states the point on which it will not move: that Allah does not take a son. The order matters. The honouring is not a preamble to the disagreement; it is meant, and the disagreement is stated anyway."],"name_story":"The only surah in the Qur'an named for a woman, and Maryam is the only woman named anywhere in it. She is spoken of here with more attention than in any other passage: her retreat, her fear, her labour under a palm tree, the instruction to shake the trunk toward herself, and her return to a community with a child and no explanation she is permitted to give.","movements":[{"range":"1-15","h":"Zakariyya, asking late","note":"An old man with a weak frame and white hair asking for an heir, and being given one. The surah opens with a prayer that was answered long after it was reasonable to expect it."},{"range":"16-40","h":"Maryam","note":"The withdrawal to a place facing east, the angel, the pains of childbirth, the wish to have died before this, and the vindication that comes from the infant himself."},{"range":"41-50","h":"Ibrahim and his father","note":"The gentlest disagreement in the Qur'an: O my father, repeated four times to a man threatening to stone him."},{"range":"51-65","h":"The line of prophets","note":"Musa, Isma'il, Idris and others named in quick succession, described as those who wept in prostration when the verses of the Merciful were recited to them."},{"range":"66-98","h":"The Merciful, and the claim refused","note":"The name ar-Rahman dominates the closing pages, and the claim that the Merciful has taken a son is answered in the strongest language in the surah."}],"themes":[{"t":"Mercy as the governing name","d":"Ar-Rahman appears more densely here than almost anywhere else, and every story in the surah is arranged as an instance of it."},{"t":"Prayers answered late","d":"Zakariyya asks as an old man. Maryam is vindicated only after she has already had to face her people. Nothing here arrives on time by human reckoning."},{"t":"Speaking gently to those who refuse you","d":"Ibrahim's address to his father is the model: four times O my father, no answering insult, and a quiet withdrawal at the end."},{"t":"Honour first, then disagree","d":"The surah gives Isa and his mother the fullest honour before it states, without softening, what it will not accept about him."}],"heart":["Recited slowly, this is the surah for anyone whose situation cannot be explained to the people around them. Maryam is told to fast from speech and to let the accusation stand; her defence is not something she is allowed to make. Very few readers will have a defence delivered as hers was, but the posture the surah teaches, holding still while being misread, is available to everyone.","It is also the surah to reach for when a prayer has gone unanswered so long that continuing to make it feels foolish. It opens with exactly that man, and does not treat his lateness as an obstacle worth mentioning."],"passages":[{"ref":"19:4","why":"My bones have weakened and my head has filled with white, and never have I been unblessed in my supplication to You. A model of how to ask after decades of asking."},{"ref":"19:23-26","why":"The palm tree, the instruction to shake it, and the dates that fall. Allah tells a woman in labour to do something, rather than simply providing it."},{"ref":"19:41-48","why":"Ibrahim to his father. The most instructive passage in the Qur'an on speaking to a relative who has rejected what you believe."},{"ref":"19:96","why":"Those who believe and do righteous deeds, the Merciful will appoint for them affection. The love comes from Him and is placed in other people."}],"connections":[{"to":3,"why":"The family of Imran is told there with a different emphasis, and the two accounts of Maryam complete each other."},{"to":21,"why":"Al-Anbiya gathers the same prophets under the theme of distress answered."}],"virtue":{"text":"No authentic report establishes a specific merit for reciting Surah Maryam. What is well attested is its use: Ja'far ibn Abi Talib recited its opening before the Negus of Abyssinia, and the king wept and granted the Muslims refuge. That is a report about the surah's effect rather than a promise of reward for reciting it, and it is given here as the former.","src":"no authentic virtue report; the Abyssinia account in Ahmad 1740 and the sirah","level":"none"}},
/* 20 Ta-Ha, deep, 135 ayat */
20:{"n":20,"depth":"deep","context":["Ta-Ha is Makkan, from the early years, and its most famous association is with the conversion of Umar ibn al-Khattab. The account, well known though its chains are discussed, has him setting out to kill the Prophet ﷺ, learning that his own sister had accepted Islam, and finding a page of this surah in her house. He read it, and went instead to declare his belief.","The surah's opening explains why it could do that. It begins by telling the Prophet ﷺ that the Qur'an was not sent down to cause him distress, and then, for more than eighty verses, tells the story of Musa in more detail than anywhere else in the Book: a man who was afraid, who asked for his brother's help because he could not do it alone, and who was sent to the most powerful man on earth anyway."],"name_story":"Ta and Ha are two of the disconnected letters that open several surahs, and the honest position, held by many of the early commentators, is that their meaning is not known with certainty. Some reports treat them as a name or an address to the Prophet ﷺ. The surah is called by them, and the Qur'an does not explain them, which is itself worth sitting with.","movements":[{"range":"1-8","h":"Not to cause you distress","note":"The opening addresses the Prophet's ﷺ own exhaustion before it asks anything of him."},{"range":"9-48","h":"The fire, and the commission","note":"Musa sees a fire, is spoken to directly, is given the staff and the hand, and asks for his chest to be expanded, his task made easy, and his brother appointed with him."},{"range":"49-79","h":"Before Fir'awn, and the sea","note":"The confrontation, the magicians who prostrate and are threatened with crucifixion and do not move, and the crossing."},{"range":"80-98","h":"The calf","note":"Forty nights away and the community has made a calf. Harun's defence, and the confrontation with Samiri."},{"range":"99-135","h":"Adam, and the closing instruction","note":"The forgetting of Adam, the promise that whoever follows the guidance will not go astray nor suffer, and the warning about a life turned away from remembrance."}],"themes":[{"t":"Revelation as relief, not burden","d":"The surah states in its second verse that it was not sent down to distress him, which sets the register for everything after it."},{"t":"Asking for help is part of the commission","d":"Musa's response to the greatest assignment ever given is to ask for his chest to be expanded and for his brother, and both requests are granted without comment."},{"t":"Conviction arriving in an instant","d":"The magicians go from employees of Fir'awn to men facing execution in the space of a single prostration, and the surah lets that happen fast."},{"t":"Turning away has a texture","d":"The closing passage does not threaten a distant punishment for forgetting Allah. It describes a constricted life, here, as the consequence."}],"heart":["Recited slowly, the surah's centre is Musa's prayer at the burning bush, and it is the prayer of somebody who knows he is not adequate to what he has been given. My Lord, expand for me my chest, and ease for me my task, and untie the knot from my tongue. It is short enough to memorise in a minute and is worth having ready before anything you are afraid of.","Its closing pages do something quieter and harder. Whoever turns away from My remembrance will have a constricted life. Not a punishment scheduled for later: a description of now, which any reader who has spent a season away from prayer will recognise before they have finished the verse."],"passages":[{"ref":"20:1-2","why":"Ta-Ha. We did not send down the Qur'an to you to cause you distress. Worth reading whenever the religion has started to feel like one more thing you are failing at."},{"ref":"20:25-28","why":"Musa's prayer. Four short requests, granted in full, made by a man who had every reason to think himself the wrong choice."},{"ref":"20:46","why":"Do not fear. Indeed, I am with you both, hearing and seeing. Said to two men about to walk into the court of Fir'awn."},{"ref":"20:124","why":"Whoever turns away from My remembrance will have a depressed life. A diagnosis rather than a threat."}],"connections":[{"to":28,"why":"Al-Qasas tells the earlier part of Musa's life, and the two together make one continuous account."},{"to":94,"why":"Ash-Sharh answers the same request Musa made, expanding the chest, and gives it to the Prophet ﷺ as a statement rather than a prayer."}],"virtue":{"text":"No authentic report establishes a specific merit for reciting Ta-Ha; reports naming a reward for it are graded weak. The account of Umar's conversion through a page of this surah is widely transmitted in the sirah literature and is given here as biography, not as a virtue report.","src":"no authentic virtue report; the conversion account in the sirah","level":"none"}},
/* 21 Al-Anbiya, light, 112 ayat */
21:{"n":21,"depth":"light","context":"Makkan, opening with the warning that people’s reckoning draws near while they play. It then moves through a gallery of prophets in crisis, Ibrahim in the fire, Ayyub in illness, Yunus in the dark, each rescued through a cry Allah preserved for us.","themes":["Reckoning approaches","Prophets in crisis","Rescue after the cry","Mercy to the worlds"],"heart":"Recited slowly, it becomes a book of emergency numbers: the reciter leaves carrying Yunus’ words from the triple darkness, and the knowledge that thus do We save the believers is written in the present tense.","passage":{"ref":"21:87","why":"The cry of Yunus inside the whale, the plea the Prophet ﷺ said no distressed Muslim makes without being answered."}},
/* 22 Al-Hajj, light, 78 ayat */
22:{"n":22,"depth":"light","context":"A surah bridging both cities, with Makkan thunder and Madinan law. It summons mankind before the earthquake of the Hour, recalls Ibrahim’s call to pilgrimage, and carries the first permission for the oppressed believers to fight back.","themes":["The Hour’s earthquake","Ibrahim’s call to Hajj","Permission to resist","Blind hearts, not eyes"],"heart":"The slow reciter feels scale: crowds at the Ka’bah, crowds at the Resurrection, and between them one diagnosis that lands personally, it is not the eyes that go blind, but the hearts within the chests.","passage":{"ref":"22:46","why":"The verse that moves blindness from the eyes to the heart."}},
/* 23 Al-Mu'minun, light, 118 ayat */
23:{"n":23,"depth":"light","context":"Makkan, opening with a ladder of qualities, humility in prayer, guarded chastity, kept trusts, that ends in Firdaws, the highest garden. Revealed while the elite of Quraysh mocked, it quietly redefined what success is.","themes":["Success redefined","Ladder to Firdaws","Creation stage by stage","Not created in vain"],"heart":"Qad aflaha al-mu’minun, the believers have already succeeded: recited slowly, that opening past tense settles into the reciter as a verdict to grow into, and khushu’, humble presence in prayer, becomes the first rung.","passage":{"ref":"23:1","why":"The opening verdict: the believers have truly succeeded."}},
/* 24 An-Nur, deep, 64 ayat */
24:{"n":24,"depth":"deep","context":["An-Nur is Madinan and much of it was revealed around one specific injury. Aisha had been left behind by the caravan and returned escorted by a single man, and a slander spread through Madinah for roughly a month while the Prophet ﷺ received no revelation about it and the household lived inside the accusation. The passage that eventually came, ten verses of it, cleared her by name and legislated permanently about what a community may do with an unproven accusation.","Around that centre the surah builds a law of privacy and of sight: how a person enters another's home, where the eyes go, what may be worn before whom. It is the surah in which the Muslim household acquires a threshold."],"name_story":"Named for the Light verse, 24:35, which sits in the middle of a surah otherwise concerned with slander, evidence and household conduct. The placement is striking and deliberate: an extended image of a lamp within a niche within glass, lit from a blessed olive tree neither of the east nor the west, dropped into the middle of legislation about ordinary decency.","movements":[{"range":"1-10","h":"A surah We have made obligatory","note":"The surah announces itself as sent down and imposed, then legislates on accusation and evidence, including the four witnesses required for a charge of unchastity."},{"range":"11-26","h":"The slander","note":"The ten verses on the ifk: why did the believers not think well of their own, why did they not demand four witnesses, and the warning against passing on with your tongues what you have no knowledge of."},{"range":"27-34","h":"The threshold","note":"Do not enter houses other than your own until you have asked permission and greeted the people in them, then the lowering of the gaze, addressed to men first."},{"range":"35-46","h":"The Light","note":"The lamp, the niche, the olive tree, light upon light, set against the parable of deeds like a mirage in a desert, and the layered darkness of a deep sea."},{"range":"47-64","h":"Obedience, and the three times of privacy","note":"The promise of succession to those who believe and do righteous deeds, and the instruction about the hours when a household is not to be entered unannounced."}],"themes":[{"t":"The presumption of innocence, legislated","d":"The surah's answer to the slander is procedural: four witnesses, or the accuser is punished. It does not ask the community to be more charitable; it removes their ability to act on suspicion."},{"t":"Repeating is participating","d":"You received it with your tongues and said with your mouths that of which you had no knowledge. The offence is located in the passing on, not only in the inventing."},{"t":"Privacy as a right of the house","d":"The rules of entry, greeting and the three times of undress construct a household that other people cannot simply walk into."},{"t":"Light, described rather than defined","d":"The Light verse offers an image and then declines to explain it, and the commentators' many readings of it are themselves part of its history."}],"heart":["Recited slowly, the passage on the slander is uncomfortable in a way few passages are, because it does not address the person who invented the rumour. It addresses everyone else: why did you not think well, why did you not stop it, why did you consider it a light matter when it was, with Allah, tremendous. Every reciter has been in the second group.","Then the Light verse arrives in the middle of all that, with no transition, and the register changes completely. A reciter who has just been told exactly how a community wounds itself is shown a lamp burning in a niche, and the two things are left beside each other without explanation."],"passages":[{"ref":"24:35","why":"Allah is the Light of the heavens and the earth. Read it slowly and without hurrying to interpret it."},{"ref":"24:15","why":"You considered it a light matter, while it was, with Allah, tremendous. Said about repeating a rumour."},{"ref":"24:22","why":"Let them pardon and overlook. Would you not like Allah to forgive you? Revealed about a man withdrawing support from a relative who had joined the slander."},{"ref":"24:30-31","why":"The lowering of the gaze, addressed to the believing men first and then to the believing women."}],"connections":[{"to":33,"why":"Al-Ahzab carries the other major passage on household conduct, and the two are read together on the subject."},{"to":49,"why":"Al-Hujurat legislates the manners of a community, including suspicion and backbiting, and completes what An-Nur begins."}],"virtue":{"text":"No authentic report establishes a specific merit for reciting An-Nur. The surah is unusual in that it describes itself in its first verse as one Allah has sent down and made obligatory, which is a stronger self-description than most surahs carry and does not require a virtue report to support it.","src":"no authentic virtue report; the surah's own description at 24:1","level":"none"}},
/* 25 Al-Furqan, light, 77 ayat */
25:{"n":25,"depth":"light","context":"Makkan, named for the Quran’s power to split truth from falsehood. It records the objections of Quraysh, he eats food, he walks in the markets, and answers them, closing with the portrait of Ibad ar-Rahman, the servants of the Most Merciful.","themes":["Criterion of truth","Objections answered","Servants of the Merciful","Walking gently on earth"],"heart":"Recited slowly, its ending becomes a mirror the reciter cannot avoid: do I walk gently, answer ignorance with peace, spend the night between prostration and standing, weep over my own sins the way they do?","passage":{"ref":"25:63","why":"The opening line of the Merciful’s servants: they walk the earth in humility and answer harshness with peace."}},
/* 26 Ash-Shu'ara, light, 227 ayat */
26:{"n":26,"depth":"light","context":"Makkan, revealed while the Prophet ﷺ was nearly destroying himself with grief over their refusal. Seven prophets repeat one refrain, I ask you no payment, my reward is with the Lord of the worlds, and the surah ends by dividing revelation from the words of poets.","themes":["Grief over deniers","Seven repeated refusals","No payment asked","Poets versus revelation"],"heart":"The rhythm of its repeated stories teaches by drumbeat, and one verse detonates in the slow reciter: on the Day when wealth and children are useless, only the one who comes to Allah with qalbin salim, a sound heart, survives.","passage":{"ref":"26:89","why":"The only currency of the Last Day: a sound heart."}},
/* 27 An-Naml, light, 93 ayat */
27:{"n":27,"depth":"light","context":"Makkan, carrying Sulayman’s kingdom of wind, jinn, and birds: an ant warns her colony, a hoopoe brings news of Saba, and a queen’s throne travels in the blink of an eye. Power, in this surah, exists only to test gratitude.","themes":["Sulayman and the hoopoe","An ant’s warning","The queen’s surrender","Who answers the desperate"],"heart":"Amid its wonders, one question stops the slow reciter mid-breath: amman yujibu al-mudtarr, who else answers the desperate one when he calls, and removes the harm? Every reciter has been that caller at least once.","passage":{"ref":"27:62","why":"The verse of the desperate: only He answers the one with nowhere left to turn."}},
/* 28 Al-Qasas, light, 88 ayat */
28:{"n":28,"depth":"light","context":"Late Makkan, revealed as emigration neared, telling Musa’s story from a floating basket to prophethood, and Qarun’s from wealth to the earth swallowing him whole. To a Prophet ﷺ about to leave his city, it promised return.","themes":["A mother’s trust","Musa the fugitive","Qarun swallowed","Promise of return"],"heart":"The slow reciter meets Musa at his lowest, homeless, hunted, standing under a tree in Madyan, and learns his prayer of open-handed poverty: My Lord, I am in absolute need of whatever good You send down to me.","passage":{"ref":"28:24","why":"Musa’s prayer of need under the tree, answered within hours with home, work, and family."}},
/* 29 Al-Ankabut, light, 69 ayat */
29:{"n":29,"depth":"light","context":"Makkan, from the season of raw persecution shortly before the hijrah, when families pressured converts to recant. It opens by naming the law of trial, everyone who says I believe will be tested, and calls every refuge except Allah a spider’s house.","themes":["Faith will be tested","Parents versus truth","The spider’s fragile house","Striving meets guidance"],"heart":"Its first question, recited slowly, undoes the fantasy of an untested faith: the reciter stops asking why hardship came and starts asking what the hardship is verifying.","passage":{"ref":"29:2","why":"The question that frames every trial: did people think they would be left to say, we believe, untested?"}},
/* 30 Ar-Rum, light, 60 ayat */
30:{"n":30,"depth":"light","context":"Makkan, revealed when Persia crushed Byzantium and the pagans gloated, since Rome’s Christians stood nearer to the Muslims. It promised Rome’s victory within a few years, a prophecy fulfilled around the very days of Badr.","themes":["A fulfilled prophecy","Signs in creation","Love placed between spouses","Fitrah, the innate pattern"],"heart":"Its litany wa min ayatihi, and among His signs, retrains the slow reciter’s eyes: sleep, languages, lightning, a spouse’s companionship stop being the furniture of life and become correspondence from its Maker.","passage":{"ref":"30:21","why":"The verse of marriage: mates from yourselves, with love and mercy set between them."}},
/* 31 Luqman, deep, 34 ayat */
31:{"n":31,"depth":"deep","context":["Luqman is Makkan, from a period when the community was small and the pressure on it came from inside families as much as from outside them. Its central passage is not a prophet addressing a nation. It is a father speaking privately to his son, and the father is not a prophet either.","That choice is deliberate and is one of the more striking things in the Qur'an. Luqman is described as having been given hikmah, wisdom, and the counsel he gives is preserved in scripture and recited in prayer by people who will never know anything else about him. A short passage of one man's parenting was judged worth keeping for ever."],"name_story":"Named for Luqman, whom the majority of the early commentators regarded as a wise man rather than a prophet, and whom several describe as an Abyssinian. The Qur'an tells us almost nothing about his circumstances and everything about what he said to his child, which is a fair indication of where it wants the reader's attention.","movements":[{"range":"1-11","h":"The Book, and those who trade it away","note":"Guidance and mercy for those who do good, set against the man who buys idle talk to lead others astray without knowledge."},{"range":"12-19","h":"The counsel","note":"Gratitude, the warning against shirk, the debt owed to parents including the limit of that debt, and then six short instructions on prayer, patience, the face, the walk and the voice."},{"range":"20-34","h":"Signs, and the five that are not known","note":"The sea and the trees as ink for the words of Allah, and a closing list of five things whose knowledge is with Allah alone."}],"themes":[{"t":"Wisdom is gratitude first","d":"The description of Luqman's hikmah opens by defining it as being grateful to Allah, before any of the counsel begins."},{"t":"Character taught in specifics","d":"The advice is not abstract. Do not turn your cheek away from people. Do not walk in arrogance. Lower your voice. It is small, physical and immediately actionable."},{"t":"Obedience to parents, and its one limit","d":"The passage commands companionship with parents in kindness in this world and, in the same breath, says that if they strive to make you associate anything with Allah, do not obey them in that."},{"t":"What is not given to you","d":"The surah closes on five matters known only to Allah, which quietly ends the human appetite to have everything explained."}],"heart":["Recited slowly, this is the surah for a parent, and it is unusually humbling. Everything Luqman says to his son is short. None of it is a lecture. The instruction on modesty is one sentence about how you carry your face; the instruction on humility is one sentence about how you walk. A father who has been trying to hand his child a philosophy is shown a man handing his child six habits.","The passage on parents is the one most readers were not expecting. It is placed inside the father's advice, so a son reading his father's counsel is simultaneously told what he owes his own parents, and told, in the same passage, the single point at which that obedience stops."],"passages":[{"ref":"31:13","why":"O my son, do not associate anything with Allah. Indeed, association is a great injustice. The first thing he says, and he says it as a kindness."},{"ref":"31:14-15","why":"The debt owed to parents, and its limit, stated together so neither can be quoted without the other."},{"ref":"31:17","why":"Establish prayer, enjoin what is right, forbid what is wrong, and be patient over what befalls you. A whole life in one verse, ending with the acknowledgement that the first three will cost you something."},{"ref":"31:19","why":"Be moderate in your pace and lower your voice. Character taught at the level of how you actually move through a room."}],"connections":[{"to":17,"why":"Al-Isra gives the parallel charter of conduct, including the wing of humility lowered to parents."},{"to":46,"why":"Al-Ahqaf carries the other major passage on what parents are owed, from the child's side."}],"virtue":{"text":"No authentic report establishes a specific merit for reciting Surah Luqman. Its weight in Muslim practice comes from the counsel itself, which has been used to teach children for fourteen centuries without needing a virtue report to recommend it.","src":"no authentic virtue report","level":"none"}},
/* 32 As-Sajdah, deep, 30 ayat */
32:{"n":32,"depth":"deep","context":["As-Sajdah is Makkan and short, thirty verses, and its place in practice is larger than its length. The Prophet ﷺ recited it together with Surah al-Insan in the dawn prayer of Friday, and the report is authentic and well known, which has kept this surah in weekly circulation in a way most surahs of its size are not.","Its subject is the two things a Makkan audience found hardest: that the Qur'an is from the Lord of the worlds and not composed by a man, and that a body which has decayed into the earth will be raised. It answers both briefly and moves on."],"name_story":"Named for the prostration in verse fifteen, one of the places in the Qur'an where a reciter and those listening prostrate. The verse describes people who, when reminded of the verses of their Lord, fall down in prostration and glorify Him and are not arrogant, and the surah asks the reciter to do the thing being described while describing it.","movements":[{"range":"1-11","h":"From the Lord of the worlds","note":"The claim that this is revelation, the creation of the human being from a despised fluid, and the answer to the objection about being raised after decay."},{"range":"12-22","h":"Two responses","note":"The criminals with their heads lowered before their Lord, set against those whose sides part from their beds, calling on Him in fear and hope. The prostration falls in this passage."},{"range":"23-30","h":"The Book given to Musa, and the closing","note":"The pattern of scripture and patience, the barren land revived by water, and a warning to turn away from those who will not be reached."}],"themes":[{"t":"Rising after decay","d":"The objection, that a body dissolved into the ground cannot return, is stated plainly and answered without evasion."},{"t":"Worship in the dark","d":"The believers of this surah are described by what they do at night, when their sides part from their beds and nobody is watching."},{"t":"A reward nobody has been told about","d":"No soul knows what has been hidden for them of comfort for the eyes, which leaves the best thing in the surah deliberately undescribed."},{"t":"Reminder, then prostration","d":"The surah does not only argue. At its centre it asks the reciter to stop reading and put his forehead on the ground."}],"heart":["Recited slowly, this surah is short enough to hold whole and heavy enough to leave a mark. Its centre is a description of people who get out of a warm bed in the dark to pray, and the phrase used, their sides part from their beds, is physical enough that a reciter feels it in the body before he understands it.","Then comes the promise that no soul knows what has been kept hidden for them. Everything else the Qur'an describes of the next life is given in images a person can picture. Here it declines to, and the refusal does more than a description would."],"passages":[{"ref":"32:15","why":"The verse of prostration. Read it, and then do what it describes."},{"ref":"32:16","why":"Their sides part from their beds, calling upon their Lord in fear and hope. The most exact description of night prayer in the Qur'an."},{"ref":"32:17","why":"No soul knows what has been hidden for them of comfort for the eyes, as reward for what they used to do."},{"ref":"32:7","why":"Who perfected everything He created and began the creation of man from clay. The answer to the objection is that He has already done the harder thing once."}],"connections":[{"to":76,"why":"Al-Insan is its pair in the Friday dawn prayer, by the Prophet's ﷺ own practice."},{"to":67,"why":"Al-Mulk covers the same ground of sovereignty and accountability at a similar length."}],"virtue":{"text":"The Prophet ﷺ used to recite As-Sajdah and Al-Insan in the dawn prayer on Friday. This is an authentic report of his practice. It establishes the surah's place in the week; it is not a report promising a specific reward for reciting it at other times.","src":"Bukhari 891; Muslim 880","level":"sunnah"}},
/* 33 Al-Ahzab, deep, 73 ayat */
33:{"n":33,"depth":"deep","context":["Al-Ahzab is Madinan and takes its name from the confederates who besieged the city in the fifth year: a coalition of tribes assembled to end the community in a single campaign. The believers dug a trench across the exposed approach and waited through cold, hunger and fear, and the siege broke without a general battle when a wind scattered the camp of the besiegers.","The surah legislates around that siege on matters the community found difficult: the ending of the practice of treating adopted sons as biological ones, the marriage of Zaynab, the conduct of the Prophet's ﷺ household, and the manner in which visitors were to behave in his home. Several of its passages address awkward, specific and human situations by name."],"name_story":"Named for al-ahzab, the confederates or the combined parties. The naming keeps the siege at the centre, and the surah's opening account of it is unusually vivid: when eyes shifted and hearts reached the throats, and the believers were shaken with a severe shaking.","movements":[{"range":"1-8","h":"Adoption, and the covenant of the prophets","note":"The end of treating adopted sons as sons in lineage, with the instruction to call them by their fathers, and the solemn covenant taken from the prophets."},{"range":"9-27","h":"The trench","note":"The siege described from inside: the fear, the hypocrites asking permission to leave, the believers who saw in it only what Allah had promised, and the wind that ended it."},{"range":"28-40","h":"The Prophet's household","note":"The choice offered to his wives between the world and Allah and His Messenger, the conduct required of them, and the marriage of Zaynab which ended the adoption rule in practice."},{"range":"41-52","h":"Remembrance, and the witness","note":"Remember Allah with much remembrance, and the description of the Prophet ﷺ as a witness, a bringer of good tidings, a warner, and a lamp giving light."},{"range":"53-73","h":"Manners in the house, and the trust","note":"The instruction about entering his home and not staying to talk, the command to send blessings upon him, the outer garment, and the closing verses on the trust that the heavens and the earth declined."}],"themes":[{"t":"Fear described honestly","d":"The account of the siege does not present the believers as unafraid. Eyes shifted, hearts reached the throats, and they were shaken severely, and the surah records that before it records the relief."},{"t":"A pattern to follow","d":"There is for you in the Messenger of Allah an excellent pattern. The verse sits inside the siege account, so the pattern being praised is his conduct under exactly those conditions."},{"t":"Ending a practice people were attached to","d":"The adoption rule was changed in law and then changed in fact through a marriage the Prophet ﷺ found difficult, and the surah addresses the difficulty rather than hiding it."},{"t":"The trust that was declined","d":"The closing image of the heavens, the earth and the mountains refusing to carry the trust, and the human being carrying it, frames everything the surah has legislated."}],"heart":["Recited slowly, the siege passage is one of the few places in the Qur'an where a reciter is put inside collective fear rather than shown it from outside. The detail that undoes most people is small: the hypocrites saying our houses are exposed, when their houses were not exposed. The excuse of a frightened person, recorded permanently.","And in the middle of it, verse 21: an excellent pattern for whoever hopes in Allah and the Last Day and remembers Allah often. It is not praise offered in a calm moment. It is said about a man digging a trench with his companions on an empty stomach while a coalition assembles to kill them all."],"passages":[{"ref":"33:21","why":"An excellent pattern in the Messenger of Allah. Placed inside the account of the siege, so the pattern is his conduct under siege."},{"ref":"33:10","why":"When eyes shifted and hearts reached the throats. The Qur'an describing fear without softening it."},{"ref":"33:56","why":"Allah and His angels send blessings upon the Prophet. O you who believe, send blessings upon him. The basis of the salawat every Muslim says."},{"ref":"33:72","why":"The heavens, the earth and the mountains declined to carry the trust, and the human being carried it."}],"connections":[{"to":24,"why":"An-Nur carries the parallel legislation on the household and on entering homes."},{"to":3,"why":"Aal Imran treats Uhud as this surah treats the trench, and the two together are the Qur'an's account of the community under arms."}],"virtue":{"text":"No authentic report establishes a specific merit for reciting Al-Ahzab. Its weight in daily practice comes from one verse, 33:56, which is the basis of the blessings on the Prophet ﷺ that Muslims say in every prayer and at the mention of his name.","src":"no authentic virtue report","level":"none"}},
/* 34 Saba, light, 54 ayat */
34:{"n":34,"depth":"light","context":"Makkan, pairing two tests of abundance: Dawud and Sulayman, who answered power with gratitude, and Saba, a people of two gardens who answered ease with boredom and were scattered like a proverb. Its quiet refrain: few of My servants are truly grateful.","themes":["Two gardens lost","Gratitude of Dawud","Wealth cannot ransom","Spending always repaid"],"heart":"Recited slowly, it plants a single worry in the reciter: which test am I failing, hardship or comfort? And it leaves one assurance in the palm: whatever you spend, He replaces it, and He is the best of providers.","passage":{"ref":"34:39","why":"The promise attached to giving: whatever you spend, He will replace it."}},
/* 35 Fatir, light, 45 ayat */
35:{"n":35,"depth":"light","context":"Makkan, opening with angels of two, three, and four wings sent from the Originator of the heavens and earth. It divides those who inherit the Book into three ranks and insists that no soul will carry another’s burden.","themes":["Angels with wings","No borrowed burdens","Three ranks of heirs","Knowledge breeding awe"],"heart":"The slow reciter feels the surah weigh his own rank, self-wronging, middling, or racing ahead in good, and finds that khashyah, awe of Allah, is not a mood but the natural yield of actually knowing Him.","passage":{"ref":"35:28","why":"The verse tying awe to knowledge: only the knowing among His servants truly fear Allah."}},
/* 36 Ya-Sin, deep, 83 ayat */
36:{"n":36,"depth":"deep","context":["Ya-Sin came down in the middle Makkan years, when the quarrel between the Prophet ﷺ and his people had narrowed to one burning question: can the dead live again. The commentators relate that a Qurashi leader, named in the reports as Ubayy ibn Khalaf or al-As ibn Wa’il, came to the Prophet ﷺ crumbling an old bone into dust and asking, will your Lord revive this after it has rotted. The closing verses answer him by name of argument rather than name of man: the One who made it the first time will remake it, and He who hides fire inside green wood finds nothing hard.","For the early community this surah was a complete case for the faith in a form the heart could carry: revelation proven, a town’s story told as a mirror of Makkah, signs hung in the sky and sea, and the Garden and Fire shown at close range. The lone man who ran from the far side of the city to defend the messengers gave the persecuted believers a portrait of themselves, and his word from inside Paradise, if only my people knew, taught them how a believer feels even toward those who killed him."],"name_story":"The surah is named for its two opening letters, Ya and Sin, from the huruf muqatta’at, the disconnected letters whose meaning Allah kept to Himself while their sound keeps announcing the Quran’s inimitability. Some later books call it the heart of the Quran, but that title rests on a weak report, and the surah stands taller without borrowed honors. Its name is simply its opening breath, two letters followed by an oath upon the wise Quran.","movements":[{"range":"1-12","h":"An oath and a mission","note":"Allah swears by the wise Quran that Muhammad ﷺ is truly sent, describes necks stiffened against faith, and promises that every deed and every footprint is being written."},{"range":"13-32","h":"The town and the runner","note":"Three messengers are rejected by a city, one man comes running from its far edge to defend them, and his murder opens straight into Paradise and the words: if only my people knew."},{"range":"33-50","h":"Signs hung everywhere","note":"Dead earth revived, night peeled from day, sun and moon swimming in courses, laden ships on the sea: creation is read aloud as evidence."},{"range":"51-68","h":"The trumpet and the sorting","note":"From the blast to the sealed mouths, the surah stages the Day itself, with the people of the Garden busy in joy and a greeting of peace from a merciful Lord."},{"range":"69-83","h":"The bone and the answer","note":"Poetry is denied, the crumbled bone is answered by first creation, fire from green trees, and the command Be, and the surah closes in the hand that holds all dominion."}],"themes":[{"t":"Resurrection argued gently","d":"The surah never mocks the questioner, it multiplies analogies, seeds, sleep, fire in wood, until denial feels like forgetting something obvious."},{"t":"One believer against a city","d":"The runner from the far side shows that truth is not decided by counting heads, and that a single sincere voice is a whole population before Allah."},{"t":"Deeds and footprints","d":"Allah records not only what people did but the traces they leave behind, so a life is measured in echoes as well as acts."},{"t":"Mercy speaking peace","d":"At the center of terror stands salam, peace, a word from a merciful Lord, the destination the whole argument is trying to save people for."}],"heart":["Ya-Sin recited slowly does to the soul what dawn does to a field: things hidden by the dark of habit become visible again. The reciter watches his own city in the town of the messengers, his own excuses in the crumbled bone, his own hope in the man who ran. By the final verses the resurrection has stopped being a doctrine to defend and become a homecoming to expect, since the One whose command is only Be, and it is, has never once been tired by making.","It also softens how a believer holds his opponents. The runner enters Paradise and his first wish is for the very people who killed him to know what he found. Whoever recites this surah with presence learns that the goal of argument is not victory but rescue."],"passages":[{"ref":"36:12","why":"Deeds and footprints both recorded: a verse that makes you ask what traces you are leaving in other lives."},{"ref":"36:26","why":"Told to enter Paradise, the martyr’s first thought is his people: the believer’s heart shown from inside the next world."},{"ref":"36:58","why":"Salam, peace, spoken as a word from a merciful Lord: the tenderest verse in the Quran’s pictures of the Garden."},{"ref":"36:79","why":"The answer to the crumbled bone: He who made it the first time will bring it back, and He knows every creation."},{"ref":"36:82","why":"Kun fa-yakun, Be, and it is: the whole metaphysics of the Quran in six words."}],"connections":[{"to":67,"why":"Ya-Sin argues the resurrection from signs and al-Mulk walks the same sky and earth asking who holds you up beside ar-Rahman."},{"to":78,"why":"The great news the people of an-Naba dispute is the very question Ya-Sin answers with the crumbled bone and the command Be."}],"virtue":{"text":"The famous report that Ya-Sin is the heart of the Quran, and that reciting it equals ten recitations of the whole Book, is weak: its chain contains narrators who are unknown or abandoned, and careful scholars including at-Tirmidhi himself flagged it. The report about reciting it over the dying is also graded weak by many. Say it plainly: nothing firm is established for this surah in particular, and it needs no certificate, its own verses are its rank.","src":"Tirmidhi 2887, graded weak","level":"debated"}},
/* 37 As-Saffat, light, 182 ayat */
37:{"n":37,"depth":"light","context":"Makkan, sworn by angels standing in ranks, answering pagan myths that made the angels daughters of Allah. Its center is the most costly obedience in scripture: Ibrahim commanded in a dream, and Isma’il answering, father, do as you are ordered.","themes":["Angels in ranks","The dream of sacrifice","A son’s surrender","A tremendous ransom"],"heart":"The slow reciter reaches the hill of the sacrifice and finds his own attachments laid upon it: the surah asks what you would put down if the command came, and shows a boy who answered before his father finished asking.","passage":{"ref":"37:102","why":"The dialogue of father and son before the sacrifice, obedience at its absolute limit."}},
/* 38 Sad, light, 88 ayat */
38:{"n":38,"depth":"light","context":"Makkan, revealed when the chiefs of Quraysh walked out declaring, has he made the gods one god? It answers with rulers who knelt: Dawud repenting in his prayer niche, Sulayman returning his kingdom to its Giver, Ayyub restored after loss.","themes":["Chiefs walk out","Dawud’s repentance","Sulayman’s surrendered kingdom","A Book for pondering"],"heart":"Recited slowly, it corrects what power means: the reciter watches the mightiest kings in scripture fall to the ground in repentance, and hears the Quran name its own purpose, a blessed Book, that they may ponder its verses.","passage":{"ref":"38:29","why":"The Quran’s mission statement: sent down blessed, for tadabbur, deep pondering, and remembrance."}},
/* 39 Az-Zumar, light, 75 ayat */
39:{"n":39,"depth":"light","context":"Makkan, the surah of ikhlas, undiluted sincerity: religion belongs to Allah alone. It ends with humanity driven in throngs to two gates, and at its heart lies the widest verse of hope ever sent down to sinners.","themes":["Undiluted sincerity","Night worship’s rank","The widest hope","Two throngs, two gates"],"heart":"One verse of this surah has pulled thousands back from the edge: recited slowly, ya ibadi, O My servants who have wronged yourselves, sounds less like an announcement and more like being called home by name.","passage":{"ref":"39:53","why":"The most hopeful verse in the Quran: do not despair, Allah forgives all sins."}},
/* 40 Ghafir, light, 85 ayat */
40:{"n":40,"depth":"light","context":"Makkan, from the years of choking persecution, opening with Allah as Forgiver of sin, Accepter of repentance, Severe in punishment. Its long center belongs to a secret believer in Pharaoh’s own court who stood up alone and argued for Musa.","themes":["Forgiver and severe","Pharaoh’s hidden believer","Angels praying for you","Call and be answered"],"heart":"The slow reciter learns that he is prayed for: the carriers of the Throne ask forgiveness for every believer, and the command ud’uni astajib lakum, call on Me and I will answer, turns du’a from ritual into correspondence.","passage":{"ref":"40:60","why":"Allah’s direct invitation: call upon Me, I will answer you."}},
/* 41 Fussilat, light, 54 ayat */
41:{"n":41,"depth":"light","context":"Makkan, the surah recited to Utbah ibn Rabi’ah when Quraysh sent him to negotiate the Prophet ﷺ away from his message; he returned pale, urging them to leave the man alone. It describes a revelation made clear for a people who mostly turned away.","themes":["Utbah silenced","Creation in stages","Angels upon the steadfast","Evil repelled with better"],"heart":"Two remedies fasten onto the slow reciter: angels descending on those who say our Lord is Allah and then stand firm, and the strange alchemy of returning evil with what is better until an enemy warms into a friend.","passage":{"ref":"41:34","why":"The verse of moral alchemy: repel evil with what is better, and watch enmity become friendship."}},
/* 42 Ash-Shura, light, 53 ayat */
42:{"n":42,"depth":"light","context":"Makkan, yet it plants the principle Madinah would later live by: a community whose affairs are decided through shura, mutual consultation. It sets the Prophet ﷺ inside one unbroken line of revelation and asks no wage but love within kinship.","themes":["One line of revelation","Consultation as worship","Provision subtly measured","Pardon over revenge"],"heart":"Recited slowly, it rebalances the reciter’s ledger of grievances: misfortune is traced to his own hands, much is pardoned outright, and the higher road stays open, whoever pardons and makes peace, his reward is upon Allah.","passage":{"ref":"42:38","why":"The verse that names the surah: believers answer their Lord, pray, and decide their affairs by consultation."}},
/* 43 Az-Zukhruf, light, 89 ayat */
43:{"n":43,"depth":"light","context":"Makkan, answering two objections: why revelation came to Muhammad ﷺ rather than a great man of the two cities, and the pagans’ worship of angels as daughters. Its reply: gold and ornament are so cheap to Allah that disbelievers could have had roofs of silver.","themes":["Gold is cheap","Mercy divided by Allah","Friends turned enemies","Isa only a servant"],"heart":"One verse quietly extracts envy from the slow reciter: are they the ones distributing your Lord’s mercy? Status, wealth, even mockery between classes shrink once you see who holds the scales of livelihood.","passage":{"ref":"43:32","why":"The cure for envy: it is We who apportion livelihoods, and your Lord’s mercy is better than what they hoard."}},
/* 44 Ad-Dukhan, light, 59 ayat */
44:{"n":44,"depth":"light","context":"Makkan, revealed amid the famine that thinned Quraysh until they saw a smoke-like haze from hunger, after the Prophet ﷺ prayed they be given years like the years of Yusuf. It opens with revelation descending on a blessed night in which every wise matter is apportioned.","themes":["A blessed night","Famine as warning","Pharaoh’s legacy abandoned","No sky wept"],"heart":"The slow reciter tastes two nights: the night of decree when destinies are handed down in mercy, and the last night of Pharaoh’s people, over whom neither heaven nor earth wept. The surah asks which night your life is oriented toward.","passage":{"ref":"44:3","why":"The blessed night of revelation, in which every wise matter is decreed."}},
/* 45 Al-Jathiyah, light, 37 ayat */
45:{"n":45,"depth":"light","context":"Makkan, named for the Hour when every nation kneels around its own record. It piles sign upon sign, seas, ships, alternating winds, for a people who heard the verses of Allah recited and persisted in pride as if they had never heard.","themes":["Every nation kneeling","Signs for the certain","Desire enthroned as god","Records that speak"],"heart":"Its sharpest verse performs surgery on the slow reciter: have you seen the one who takes his own desire as his god? For a moment you audit which voice you actually obey when revelation and appetite disagree.","passage":{"ref":"45:23","why":"The verse exposing the oldest idol: one’s own desire, worshipped as a god."}},
/* 46 Al-Ahqaf, light, 35 ayat */
46:{"n":46,"depth":"light","context":"Late Makkan, named for the wind-curved dunes of Aad, revealed near the time a company of jinn overheard the Quran and went home as warners. It sets colossal vanished nations beside one intimate scene: a person at forty, praying to be grateful for his parents.","themes":["Aad beneath the dunes","Jinn turned warners","The prayer at forty","Patience of the resolute"],"heart":"The verse of the fortieth year reads the slow reciter’s own timeline back to him: carried in hardship, weaned, matured, and now asked to answer for it all with one prayer, my Lord, enable me to be grateful.","passage":{"ref":"46:15","why":"The prayer of maturity: gratitude for parents, righteous work accepted, descendants made good."}},
/* 47 Muhammad, light, 38 ayat */
47:{"n":47,"depth":"light","context":"Early Madinan, after the hijrah, when a driven-out community was first commanded to meet its pursuers in battle. Named for the Prophet Muhammad ﷺ, it draws the wartime line between those who follow falsehood and those who follow the truth from their Lord.","themes":["Truth against falsehood","Help Allah, be helped","Locks upon hearts","Stinginess with His cause"],"heart":"Its central question is aimed straight at the slow reciter’s own act of recitation: do they not ponder the Quran deeply, or are there locks upon their hearts? You feel the verse testing whether it can get in.","passage":{"ref":"47:24","why":"The verse of the locked heart: pondering the Quran is the key it demands."}},
/* 48 Al-Fath, light, 29 ayat */
48:{"n":48,"depth":"light","context":"Madinan, revealed on the road home from Hudaybiyyah, when a treaty that looked like humiliation was named a clear victory. Within two years its terms had opened Makkah itself, and the pledge sworn under the tree earned Allah’s announced pleasure.","themes":["Hudaybiyyah reframed","Pledge under the tree","Tranquility sent down","Victory in disguise"],"heart":"The slow reciter learns to reread his own setbacks: sakinah, tranquility from Allah, descends precisely where events look worst, and the closing portrait, stern before enemies, tender among themselves, faces marked by prostration, shows what that pledge became.","passage":{"ref":"48:29","why":"The portrait of the Prophet’s ﷺ companions: intense in resolve, tender with one another, marked by prostration."}},
/* 49 Al-Hujurat, light, 18 ayat */
49:{"n":49,"depth":"light","context":"Madinan, from the ninth year, the year of delegations, when tribes arrived shouting outside the Prophet’s ﷺ rooms. In eighteen verses it legislates a whole social ethic: verify news, no mockery, no spying, no backbiting, brotherhood across tribes.","themes":["Lower your voices","Verify before spreading","No mockery, no spying","Nobility is taqwa"],"heart":"Recited slowly, it feels like a code of speech written centuries before your group chats: the reciter finds his words, jokes, and assumptions each addressed by name, then lifted by one universal verse of human dignity.","passage":{"ref":"49:13","why":"The verse of human equality: one origin, many peoples, and the noblest is the most God-conscious."}},
/* 50 Qaf, light, 45 ayat */
50:{"n":50,"depth":"light","context":"Makkan, a surah the Prophet ﷺ recited in Friday and Eid sermons until companions memorized it from his mouth. It answers astonishment at resurrection with the earth’s own bookkeeping: We know what the soil diminishes of them.","themes":["Resurrection answered","The soil’s ledger","Nearer than the jugular","Two recording angels"],"heart":"One clause changes the slow reciter’s sense of privacy forever: We are nearer to him than his jugular vein. Recited at dawn, it makes solitude impossible and intimacy with Allah suddenly literal.","passage":{"ref":"50:16","why":"The verse of nearness: Allah closer to you than your own jugular vein."}},
/* 51 Adh-Dhariyat, light, 60 ayat */
51:{"n":51,"depth":"light","context":"Makkan, sworn by winds that scatter, clouds that carry, ships that glide. It recalls Ibrahim’s honored guests and the ruins of nations, then compresses the purpose of existence into a single sentence about jinn, mankind, and worship.","themes":["Oaths by the winds","Provision in the sky","Night’s small hours","Created only to worship"],"heart":"The purpose verse lands on the slow reciter with the weight of a job description: created only to worship. Suddenly the night prayers and dawn istighfar, seeking forgiveness, described earlier in the surah look less like extra credit and more like the work itself.","passage":{"ref":"51:56","why":"The sentence that states why anything exists: jinn and mankind created only for worship."}},
/* 52 At-Tur, light, 49 ayat */
52:{"n":52,"depth":"light","context":"Makkan, sworn by Mount Sinai and a written scripture. Jubayr ibn Mut’im, still a pagan, heard the Prophet ﷺ recite it at the sunset prayer and said his heart nearly took flight; its cascade of questions leaves denial nowhere to stand.","themes":["Oath by the Mount","Questions without escape","A heart takes flight","Families reunited above"],"heart":"The slow reciter reaches the passage that shook Jubayr, were they created from nothing, or are they their own creators, and feels the argument close every exit but one: kneel to the One who made you.","passage":{"ref":"52:35","why":"The question that pierced a listener mid-prayer: created from nothing, or creators of themselves?"}},
/* 53 An-Najm, light, 62 ayat */
53:{"n":53,"depth":"light","context":"Makkan, the first surah the Prophet ﷺ recited publicly to end in prostration, and even the pagans fell down with him. It testifies to what he saw at the farthest lote tree: the eye did not swerve, nor did it exceed its limit.","themes":["The vision defended","The farthest lote tree","Every soul’s own earning","A prostration none refused"],"heart":"Recited slowly, its account of the ascension steadies the reciter’s trust in the messenger: a heart that did not lie about what it saw. Then the ethic arrives like a plumb line: nothing is yours except what you strove for.","passage":{"ref":"53:39","why":"The law of striving: man will have nothing but what he himself worked for."}},
/* 54 Al-Qamar, light, 55 ayat */
54:{"n":54,"depth":"light","context":"Makkan, opening with the split moon that Quraysh witnessed and dismissed as passing magic. Nation after nation follows, each account sealed with the same astonishing refrain: We have made the Quran easy to remember, so is there anyone who will?","themes":["The moon split","Warnings dismissed","An easy Quran","Is there any rememberer"],"heart":"Its refrain is a standing invitation with your name left blank: the slow reciter hears fa-hal min muddakir, is there any who will take heed, four times over, and realizes the question is not rhetorical, it is recruitment.","passage":{"ref":"54:17","why":"The repeated pledge: the Quran made easy for remembrance, awaiting anyone willing."}},
/* 55 Ar-Rahman, deep, 78 ayat */
55:{"n":55,"depth":"deep","context":["Ar-Rahman came down in Makkah, by the sounder of two views, in a period when Quraysh were feigning ignorance of the very name it opens with: and when they are told to prostrate to ar-Rahman, they say, what is ar-Rahman. The surah answers by simply unrolling His resume. The Merciful taught the Quran, made man, taught him speech, set sun and moon to arithmetic, raised the sky, and laid down the balance, and after each unveiling it turns to men and jinn together and asks which of His favors they will call a lie.","In the Prophet’s ﷺ life it stands out as a surah addressed to two audiences at once, since he was sent to jinn as well as men. He is reported to have told his companions, after reciting it to them and meeting silence, that the jinn had answered better: at every refrain they replied, nothing of Your favors, our Lord, do we deny. The early believers, stripped of property and safety in Makkah, learned from it to count what could not be confiscated: speech, fruit, rain, the two seas, and the face of their Lord that outlasts everything on earth."],"name_story":"The surah is named ar-Rahman, the Entirely Merciful, because that name is its first word and its whole argument: everything that follows is mercy made visible. It is the only surah in the Quran that opens with a name of Allah standing alone. Some books call it the bride of the Quran, but that nickname rests on a weak report, and the truer description is the early teachers’ observation that it is the surah of the two weighty races, men and jinn, questioned side by side.","movements":[{"range":"1-13","h":"Mercy teaching and measuring","note":"The Merciful teaches the Quran before He mentions making man, then hangs sun, moon, sky, and scale in order, and lays the earth like a table for all creatures."},{"range":"14-30","h":"Two races, two seas","note":"Man from dried clay and jinn from smokeless fire, two easts, two seas meeting behind an unseen barrier, ships like mountains, and the sentence that levels everything: all upon it passes away, and the Face of your Lord remains."},{"range":"31-45","h":"The reckoning of the two","note":"Allah turns to the two weighty races, challenges them to pierce the edges of the heavens, and shows the criminals known by their marks between fire and boiling water."},{"range":"46-78","h":"Four gardens descending","note":"For whoever feared the standing before his Lord, two gardens, and beneath them two more, described branch by branch until the surah closes blessing the name of the Owner of Majesty and Honor."}],"themes":[{"t":"Favor demands an answer","d":"The refrain, which of the favors of your Lord will you both deny, repeats thirty one times, turning the whole surah into a court where blessings are the evidence."},{"t":"Balance in the sky and the scale","d":"The mizan, the balance, is set in the cosmos and in the marketplace in one breath, so cheating a customer becomes a crime against the architecture of the universe."},{"t":"Everything passes, He remains","d":"The surah’s hinge is fana, passing away: every face on earth is temporary, and only the Face of the Lord of Majesty endures."},{"t":"Fear rewarded with beauty","d":"The gardens are given not for casual belief but for one who feared the standing before his Lord, and the reward of excellence is declared to be nothing but excellence."}],"heart":["Ar-Rahman recited slowly is an inventory the reciter cannot escape. Each refrain lands like a hand on the shoulder: the speech in your mouth, the symmetry of the sky, the salt sea and the sweet, which of these will you call a lie? Denial rarely happens in words, it happens in inattention, and this surah cures inattention by asking the same question until the heart finally answers the way the jinn did: nothing of Your favors, our Lord, do we deny.","Then, in its second half, the surah does something to desire. It shows the two gardens, then two more, cool with shade and heavy with fruit, and quietly reprices every pleasure the dunya, the lower world, was selling. The one who rises from it has both fear and appetite pointed in the right direction: afraid of the standing, hungry for what lies past it."],"passages":[{"ref":"55:9","why":"Set the weight with justice and do not cheat the scale: cosmic law bending down into your shop and your home."},{"ref":"55:13","why":"The first sounding of the refrain that will ask you thirty one times which favor you dare call a lie."},{"ref":"55:26","why":"Everyone upon the earth passes away: the verse that empties every throne, and the next breath fills the loss with the remaining Face of your Lord."},{"ref":"55:29","why":"Every day He is engaged in a matter: forgiving, raising, lowering, answering, a universe never on pause."},{"ref":"55:60","why":"Is the reward of excellence anything but excellence: eight words that settle how Allah deals with those who deal beautifully."}],"connections":[{"to":56,"why":"Ar-Rahman ends in gardens for the fearful and al-Waqi’ah continues the sorting, the foremost, the right hand, and the left, scene by scene."},{"to":25,"why":"Al-Furqan records Quraysh asking, what is ar-Rahman, and this surah is the long, magnificent answer to that question."}],"virtue":{"text":"The title bride of the Quran, often quoted for this surah, comes from a weak report and should not be taught as the Prophet’s ﷺ word. What is soundly meaningful is the report from Jabir that when the Prophet ﷺ recited it to the jinn, they answered every refrain, nothing of Your favors, our Lord, do we deny, and he ﷺ commended their response; at-Tirmidhi called its chain unusual while others accepted it, so state it with that honesty. The surah needs no certificate beyond its own refrain.","src":"Tirmidhi 3291, grading contested","level":"debated"}},
/* 56 Al-Waqi'ah, light, 96 ayat */
56:{"n":56,"depth":"light","context":"Makkan, the surah that sorts all humanity into three companies at the Event none can deny: the foremost drawn near, the people of the right, the people of the left. The Prophet ﷺ counted it among the surahs that grayed his hair.","themes":["Three companies sorted","The foremost brought near","Water, fire, seed","A noble protected Book"],"heart":"The slow reciter cannot finish it without silently choosing a company, and its middle interrogation, who sends the water, grows the seed, sets the fire, turns an ordinary glass of water into an argument he now drinks daily.","passage":{"ref":"56:10","why":"The rank worth racing for: the foremost, the foremost, those are the ones brought near."}},
/* 57 Al-Hadid, light, 29 ayat */
57:{"n":57,"depth":"light","context":"Madinan, calling a now-secure community to spend before conquest makes giving easy and cheap. It opens with Allah’s names ringing like struck metal, the First and the Last, the Outward and the Inward, and asks how long hearts will wait to soften.","themes":["First, Last, Outward, Inward","Spending before the opening","Iron’s might and uses","Hearts due to humble"],"heart":"Its sixteenth verse reaches the slow reciter as a direct, almost embarrassing question: has the time not yet come for your heart to humble itself to the remembrance of Allah? Companions took it as a gentle rebuke to themselves, and it still lands.","passage":{"ref":"57:16","why":"The verse that once broke hearts mid-recitation: has the time not come to humble yourself?"}},
/* 58 Al-Mujadilah, light, 22 ayat */
58:{"n":58,"depth":"light","context":"Madinan, opening with Khawlah bint Tha’labah, who pleaded about her husband’s zihar, the pagan oath likening a wife to a mother’s back, while Allah listened from above the seven heavens and answered her. The surah then dismantles secret counsels and pledges that Allah’s party prevails.","themes":["A woman heard above","Zihar oath annulled","Secret talks governed","Fourth of every three"],"heart":"Aishah marveled that Allah’s hearing encompassed a complaint she could barely catch across the room: the slow reciter inherits that awe, learning that no whispered grievance of his is too quiet to have already reached the highest heaven.","passage":{"ref":"58:1","why":"The opening miracle: Allah heard the woman who pleaded, and ruled for her."}},
/* 59 Al-Hashr, light, 24 ayat */
59:{"n":59,"depth":"light","context":"Madinan, after the broken pact of Banu Nadir ended in their exile from Madinah in the fourth year. From that political rupture the surah rises to the most concentrated litany of Allah’s names in the Quran, and a command to every soul: look at what you have sent ahead.","themes":["Banu Nadir exiled","What was sent ahead","A mountain would crumble","The most beautiful names"],"heart":"Its close overwhelms the slow reciter twice: first the image of a mountain split and humbled had this Quran descended upon it, while my heart holds it casually; then name after name, al-Malik, al-Quddus, as-Salam, until vocabulary itself prostrates.","passage":{"ref":"59:21","why":"The mountain verse: stone would crack in awe of this Quran, so what excuse has a heart?"}},
/* 60 Al-Mumtahanah, light, 13 ayat */
60:{"n":60,"depth":"light","context":"Madinan, revealed after Hatib ibn Abi Balta’ah secretly wrote to Quraysh warning them of the march on Makkah, out of fear for his family there. It draws the line between betraying the community and treating peaceful non-Muslims with kindness and justice.","themes":["Hatib’s secret letter","Loyalty’s true limits","Kindness to the peaceful","Emigrant women examined"],"heart":"The surah hands the slow reciter two edges to hold together: never trade the community’s safety for private fear, yet never slander the faith by cruelty, for Allah Himself commends birr, warm kindness, toward those who never fought you.","passage":{"ref":"60:8","why":"The verse of coexistence: Allah does not forbid kindness and justice toward the peaceful."}},
/* 61 As-Saff, light, 14 ayat */
61:{"n":61,"depth":"light","context":"Madinan, revealed after believers wished to know the deed most beloved to Allah, then flinched when the answer involved fighting. It responds with a piercing question about saying what you do not do, and offers a commerce that saves from a painful punishment.","themes":["Say and then do","Ranks like fused walls","A saving commerce","Isa’s glad tidings"],"heart":"Its second verse audits the gap every believer carries between speech and practice: recited slowly, kabura maqtan, how hateful it is to Allah, makes the reciter inventory last week’s unkept resolutions before the verse even ends.","passage":{"ref":"61:2","why":"The verse that measures the distance between what we say and what we do."}},
/* 62 Al-Jumu'ah, light, 11 ayat */
62:{"n":62,"depth":"light","context":"Madinan, named for the congregation of Friday. It came to a community that once drifted from the sermon toward an arriving caravan’s drumbeat, and it recalibrates them: when the call is given, leave trade, and when prayer ends, disperse remembering Allah much.","themes":["The unlettered given wisdom","A donkey carrying books","Leave the trade","Dispersal with remembrance"],"heart":"Its image of a donkey hauling volumes it cannot read warns the slow reciter about his own bookshelf: recitation without transformation is freight. Friday, in this surah, is the weekly cure for that.","passage":{"ref":"62:9","why":"The Friday command: when the call sounds, hasten to Allah’s remembrance and leave off trade."}},
/* 63 Al-Munafiqun, light, 11 ayat */
63:{"n":63,"depth":"light","context":"Madinan, revealed after the Banu Mustaliq expedition, when Abdullah ibn Ubayy vowed that the mightier would expel the weaker from Madinah, then swore he never said it. Allah confirmed the young witness Zayd ibn Arqam and unmasked polished falsehood.","themes":["Oaths as shields","Impressive hollow forms","A boy vindicated","Wealth as distraction"],"heart":"Its portrait unsettles the slow reciter in the healthiest way: bodies that impress, speech that persuades, hearts absent, and then the closing plea, spend now, before death asks for the extension no one is granted.","passage":{"ref":"63:9","why":"The closing warning: do not let wealth and children distract you from remembering Allah."}},
/* 64 At-Taghabun, light, 18 ayat */
64:{"n":64,"depth":"light","context":"Commonly counted Madinan, named for Yawm at-Taghabun, the Day of mutual gain and loss, when winners and losers discover they have traded places. It was sent to households where some spouses and children pulled against faith, counseling caution without cruelty, and pardon.","themes":["Day of mutual loss","Trial within family","Calamity with permission","Guided hearts"],"heart":"Its eleventh verse rewires how the slow reciter absorbs bad news: no calamity strikes except by Allah’s permission, and whoever believes, He guides his heart. Faith does not deflect the blow; it steadies the heart the blow lands on.","passage":{"ref":"64:11","why":"The verse for the day everything goes wrong: belief met with a heart guided through it."}},
/* 65 At-Talaq, light, 12 ayat */
65:{"n":65,"depth":"light","context":"Madinan, legislating divorce at its most humane: counted waiting periods, housing, no expulsion, witnesses, maintenance. Into the driest legal terrain it plants the Quran’s great promise of provision for whoever keeps taqwa, careful duty to Allah, while a household comes apart.","themes":["Divorce with dignity","Counted waiting periods","A way out promised","Provision beyond planning"],"heart":"The slow reciter discovers where Allah placed the famous verses of the way out and unexpected provision: not in a surah of ease but inside divorce law, teaching that trust in Him is most rewarded exactly where hearts are breaking.","passage":{"ref":"65:3","why":"The promise embedded in hardship: provision from where you never expected, and Allah sufficient for whoever relies on Him."}},
/* 66 At-Tahrim, light, 12 ayat */
66:{"n":66,"depth":"light","context":"Madinan, opening with a moment inside the Prophet’s ﷺ own household, when he swore off something permitted in order to please his wives and Allah corrected him. It ends with women as arguments: two who betrayed prophet husbands, Pharaoh’s believing wife, and Maryam.","themes":["A household corrected","Repentance called nasuh","Fire fueled by people","Four women as proof"],"heart":"Its examples strip the slow reciter of every excuse of association: marriage to a prophet saved no traitor, marriage to Pharaoh doomed no believer. You stand inside Asiyah’s prayer, build me a house with You in Paradise, owning your file alone.","passage":{"ref":"66:8","why":"The call to tawbah nasuha, repentance so sincere it remakes the sinner."}},
/* 67 Al-Mulk, deep, 30 ayat */
67:{"n":67,"depth":"deep","context":["Al-Mulk came down in Makkah, in the years when the Quraysh treated death as the end of the argument: a man dies, they said, and the dust keeps him. The surah answers by widening the frame before it answers the question. It opens with the hand that holds all dominion, names death and life as things created, made on purpose, and made in that order, and then sends the listener’s eye up through seven heavens looking for a crack. Only after the sky passes inspection does it descend to the small kingdom of a human chest and ask what it conceals.","In the Prophet’s ﷺ own practice this surah had a fixed place at the edge of sleep: he would not rest until he had recited as-Sajdah and al-Mulk, as Jabir relates. The early community absorbed it as nightly armor, a way of closing the day by remembering who holds the day. Its final verse, asking who could bring back water that sank into the earth, spoke directly to a desert people, and through them to anyone whose life depends on provisions they cannot make themselves."],"name_story":"Al-Mulk means the Dominion, from its first line: blessed is He in whose hand is the dominion. The companions also knew it by names drawn from what it does rather than what it says: al-Mani’ah, the Protector, and al-Munjiyah, the Rescuer, because sound reports describe it pleading for its reciter until he is forgiven. Some early teachers called it al-Waqiyah, the Shielding, for the same reason: it is a surah known by its work.","movements":[{"range":"1-5","h":"A flawless sky, a purposeful death","note":"Dominion, then death and life created as a test of who is best in deed, then the challenge to find one flaw in the sky until sight returns humbled and tired."},{"range":"6-11","h":"The confession of the fire","note":"Hell nearly bursts with rage, its keepers ask whether no warner came, and the damned reply with the saddest sentence in the Quran: if only we had listened or used reason."},{"range":"12-19","h":"Fear of the Unseen, ground underfoot","note":"Forgiveness is promised to those who fear their Lord unseen, the Creator’s knowledge is proven by His creating, and the earth is made a tamed mount while birds hang on nothing but mercy."},{"range":"20-27","h":"Who provides if He withholds","note":"Imagined armies and stopped provisions expose how thin every other support is, the crawler and the upright walker are compared, and the promise once mocked arrives close enough to darken faces."},{"range":"28-30","h":"The final question of water","note":"The surah ends on the desert’s deepest nerve: if your water sank into the earth by morning, who but He could bring it flowing back."}],"themes":[{"t":"Death created on purpose","d":"Death is not a breakdown but a made thing with a function: to test who is best, not most, in deed."},{"t":"Looking as worship","d":"The command to look again and again at the sky turns observation into devotion, and makes wonder an argument."},{"t":"Hearing and reasoning","d":"The people of the fire condemn themselves for wasted ears and minds, so attention itself becomes a matter of salvation."},{"t":"Provision as suspended mercy","d":"Birds held mid-air and water hidden underground teach that every livelihood hangs from a hand that could close."}],"heart":["Al-Mulk recited slowly at night does two opposite things at once, and both are mercy. It shrinks you: your eye is sent up twice against the seven heavens and comes back defeated, and you remember you cannot even guarantee tomorrow’s water. And it settles you: the same hand that built the flawless sky holds your provision, hears your secret, and watches the bird above your head. Fear and rest arrive together, the fear of Him and the rest in Him.","Its sharpest gift is the verse of the ears and the mind. If only we had listened or used reason, say the people of the fire, and the honest reciter checks his own listening that same night. A person who ends each day inside this surah is quietly trained never to let a warning pass him unheard again."],"passages":[{"ref":"67:2","why":"Death and life created to test who is best in deed: the verse that replaces the question how long with the question how well."},{"ref":"67:10","why":"If only we had listened or used reason: the confession of the fire, recited now so it is never said then."},{"ref":"67:14","why":"Would He not know, He who created, while He is the Subtle, the Aware: the shortest proof of divine knowledge in the Quran."},{"ref":"67:19","why":"Birds spreading and folding their wings, held by nothing but ar-Rahman: look up and see faith’s physics."},{"ref":"67:30","why":"If your water sank away by morning, who could bring it back: the closing question that leaves every listener holding an empty cup before Allah."}],"connections":[{"to":32,"why":"The Prophet ﷺ would not sleep until reciting as-Sajdah and al-Mulk together, a nightly pairing of prostration and dominion."},{"to":36,"why":"Both surahs walk the same gallery of signs, sky, provision, and the tired eye of the denier, toward the same resurrection."}],"virtue":{"text":"The Prophet ﷺ said that a surah of thirty verses interceded for a man until he was forgiven, and named it: blessed is He in whose hand is the dominion. Scholars grade the report hasan-sahih, sound and dependable, and the companions linked it to protection in the grave. This is one of the best attested surah virtues after al-Fatiha and al-Kahf.","src":"Tirmidhi 2891; Abu Dawud 1400","level":"sunnah"}},
/* 68 Al-Qalam, light, 52 ayat */
68:{"n":68,"depth":"light","context":"Among the very first revelations of Makkah, sworn by the pen and what they write, answering the slander that the Prophet ﷺ was possessed. Against the insult it sets a verdict for all time, you are upon a tremendous character, and adds the parable of garden owners who excluded the poor.","themes":["Oath by the pen","Madness refuted","Tremendous character","The blighted garden"],"heart":"The slow reciter watches heaven answer name-calling not with counter-insult but with a character reference, and the garden parable quietly checks his own plans: what did I decide, last harvest, about the share of the poor?","passage":{"ref":"68:4","why":"Allah’s testimony about His Prophet ﷺ: truly you are of tremendous character."}},
/* 69 Al-Haqqah, light, 52 ayat */
69:{"n":69,"depth":"light","context":"Makkan, named for the Reality that crushed Thamud and Aad and will one day fold the sky. Umar heard it recited at the Ka’bah while still set against Islam and later said belief began entering his heart from those verses. It stages the two receptions of the record, right hand and left.","themes":["The crushing Reality","Umar overhears","Records right and left","No poet’s word"],"heart":"The cry of the saved man, ha’umu iqra’u kitabiyah, here, come read my book, is a joy the slow reciter rehearses for: a life so relieved at its own record that it invites the crowd to read it. The surah asks what your file would make you shout.","passage":{"ref":"69:19","why":"The happiest sentence of the Last Day: here, read my record!"}},
/* 70 Al-Ma'arij, light, 44 ayat */
70:{"n":70,"depth":"light","context":"Makkan, answering a mocker who demanded the punishment fall immediately. Allah measures time otherwise, a day of fifty thousand years, and diagnoses mankind as created halu’an, anxious and clutching, impatient in harm, withholding in good, except those who pray and keep praying.","themes":["A mocking demand answered","Fifty thousand years","Anxiety’s one exception","Rights of the asker"],"heart":"Its psychology reads the slow reciter like a chart: panic when touched by harm, tightness when touched by wealth. Then the exception, illa al-musallin, except the people of constant prayer, offers the only cure the surah recognizes.","passage":{"ref":"70:19","why":"The diagnosis of the human condition: created anxious, with prayer named as the exception."}},
/* 71 Nuh, light, 28 ayat */
71:{"n":71,"depth":"light","context":"Makkan, a single sustained account of Nuh’s nine hundred and fifty years of calling: night and day, public and private, promising that istighfar, seeking forgiveness, would bring rain, wealth, sons, gardens, rivers. They put their fingers in their ears, and the flood answered.","themes":["Nine centuries of calling","Forgiveness brings rain","Fingers in ears","Idols named and drowned"],"heart":"Nuh’s offer becomes the slow reciter’s own economics: forgiveness sought, skies opened, provision multiplied. Whoever recites this surah in drought of any kind, money, children, rain, hope, leaves knowing the first thing to try.","passage":{"ref":"71:10","why":"Nuh’s formula: seek His forgiveness, and He sends the sky pouring upon you."}},
/* 72 Al-Jinn, light, 28 ayat */
72:{"n":72,"depth":"light","context":"Makkan, revealed after a company of jinn overheard the Prophet ﷺ reciting the dawn prayer at Nakhlah on the road back from Ta’if’s rejection. They rushed home as believers and preachers, and their confession fills the surah: we have heard an astonishing Quran.","themes":["Unseen listeners converted","An astonishing Quran","Heaven’s guarded gates","Mosques for Allah alone"],"heart":"The slow reciter is humbled by the ranking: beings of smokeless fire heard a few verses once, at night, and surrendered on the spot. The surah asks what the same verses, heard a thousand times, have done to him.","passage":{"ref":"72:1","why":"The jinn’s own testimony: we have heard an astonishing Quran that guides to right conduct."}},
/* 73 Al-Muzzammil, light, 20 ayat */
73:{"n":73,"depth":"light","context":"Among the earliest revelations, addressed to the Prophet ﷺ wrapped in his cloak after the encounter at Hira: stand in prayer through the night, half of it, and recite with tartil, slow measured recitation, for a heavy word was coming. Its final verse later eased the measure for the community.","themes":["Night vigil commanded","Tartil, measured recitation","A heavy word","Patience with deniers"],"heart":"This is the surah that teaches the very act you are performing: recited slowly at night, its command to recite slowly at night folds back on the reciter, and the night stops being sleep’s leftover and becomes the forge where the heavy word is carried.","passage":{"ref":"73:4","why":"The command behind all slow recitation: recite the Quran with measured tartil."}},
/* 74 Al-Muddaththir, light, 56 ayat */
74:{"n":74,"depth":"light","context":"Makkan, the summons that ended the pause in revelation: the Prophet ﷺ came home trembling from Hira, asking to be covered, and was answered, O you who wraps himself, arise and warn. From that command the public mission began, with al-Walid ibn al-Mughirah’s calculated slander answered line by line.","themes":["Arise and warn","Comfort ended","A schemer dissected","Saqar’s nineteen keepers"],"heart":"Qum, arise: the slow reciter feels the word that pulled the Prophet ﷺ from his blanket into history still carrying force, an antidote to every season of hiding under one’s own cloak from what must be done.","passage":{"ref":"74:2","why":"The two words that began the public mission: arise and warn."}},
/* 75 Al-Qiyamah, light, 40 ayat */
75:{"n":75,"depth":"light","context":"Makkan, sworn by the Day of Rising and the self-reproaching soul, answering a man who asked whether scattered bones could really be regathered: yes, down to the fingertips. Mid-surah, Allah personally teaches the Prophet ﷺ how to receive revelation without racing his tongue.","themes":["Bones and fingertips","The reproaching soul","Do not hasten","Faces radiant, gazing"],"heart":"Two gifts settle in the slow reciter: permission to slow down, for upon Us is its collection and recitation, and the destination that makes every dry stretch worth it, faces that Day radiant, looking at their Lord.","passage":{"ref":"75:22","why":"The summit of all hope: radiant faces gazing at their Lord."}},
/* 76 Al-Insan, light, 31 ayat */
76:{"n":76,"depth":"light","context":"Counted Madinan in the common ordering though some place it in Makkah, and paired by the Prophet ﷺ with As-Sajdah in the dawn prayer of Friday. It follows man from a drop of mingled fluid to the abrar, the righteous who feed the poor, the orphan, and the captive for the face of Allah alone.","themes":["From a mingled drop","Feeding for His face","No reward sought","Camphor and ginger"],"heart":"Its secret is a sentence said only inside the heart, we feed you for the face of Allah alone, wanting neither repayment nor thanks: the slow reciter learns to give while deleting the invoice, and the surah shows what such hidden sincerity drinks in Paradise.","passage":{"ref":"76:9","why":"The creed of hidden sincerity: feeding others for Allah’s face alone, expecting nothing back."}},
/* 77 Al-Mursalat, light, 50 ayat */
77:{"n":77,"depth":"light","context":"Makkan, revealed, Ibn Mas’ud said, while the companions sat with the Prophet ﷺ in a cave at Mina, the surah still fresh on his lips when a snake darted out at them. Ten times its refrain falls like a gavel, woe that Day to the deniers, between scenes of loosed winds, extinguished stars, and shaded believers.","themes":["Oaths by sent winds","Refrain like a gavel","The cave at Mina","Woe to deniers"],"heart":"Ten repetitions do to the slow reciter what one cannot: each woe closes another shutter of excuse, until the final question, then in what word after this will they believe, leaves him holding the Quran as the last remaining door.","passage":{"ref":"77:50","why":"The closing question with no answer: if not this word, then which?"}},
/* 78 An-Naba, deep, 40 ayat */
78:{"n":78,"depth":"deep","context":["An-Naba came down in early Makkah, when word of the resurrection had become the city’s argument of the season. Men stopped one another in the market to ask what this new preaching claimed about dead bones and a day of judgment, some mocking, some uneasy. The surah opens by quoting the whole city at once, about what do they question one another, and then refuses to treat the matter as debatable: they will know, then again, they will know.","For the Prophet ﷺ and the few believers around him, this surah reframed the entire landscape they walked through. The bed of the earth, the pegs of the mountains, their own sleep and the black tent of night were re-presented as deliberate mercies from a Lord who plans, and a Lord who plans a cradle does not abandon the child. It belongs to the cluster of early surahs that the Prophet ﷺ said had aged him, because they carry the Day in almost unbearable resolution."],"name_story":"An-Naba means the Tiding, from its second verse: the tremendous tiding they dispute about, meaning the resurrection. The companions often called it Amma, after its opening word, about what, and it is recorded under that name in early lists. The name keeps the surah’s posture: all of human noise reduced to one question, and one answer coming.","movements":[{"range":"1-5","h":"The question and the warning","note":"The city’s dispute about the great tiding is quoted once, and answered only with a doubled promise: soon they will know."},{"range":"6-16","h":"A world built like a cradle","note":"Earth spread as a bed, mountains as pegs, sleep as rest, night as covering, seven strong heavens and a blazing lamp: a creation too deliberate to be aimless."},{"range":"17-30","h":"The Day of Sorting","note":"The trumpet, the opened sky, mountains turned to mirage, and Jahannam lying in ambush, where rebels taste a recompense measured exactly to what they did."},{"range":"31-36","h":"The safe estate of the God-conscious","note":"For the muttaqin, those who guarded themselves, gardens, vineyards, companions, and a full cup, given as gift and reckoned reward from a Lord of mercy."},{"range":"37-40","h":"The Day the Spirit stands","note":"Angels and the Ruh, the Spirit, stand in ranks unable to speak without leave, and the disbeliever utters the last wish of the surah: would that I were dust."}],"themes":[{"t":"Certainty against mockery","d":"The surah never argues with the scoffers on their terms; it states the Day twice as fact and lets creation do the persuading."},{"t":"Design implies destiny","d":"Beds, pegs, lamps, and rain form one argument: a world furnished this carefully is a place of purpose, and purpose requires a reckoning."},{"t":"Exact recompense","d":"Punishment is called jaza’an wifaqa, a fitting repayment, nothing arbitrary, everything answering the deed like an echo."},{"t":"The envy of the damned","d":"The surah ends with a man wishing to be dust, teaching that the real tragedy is not punishment but wasted existence."}],"heart":["An-Naba slows the reciter down by making him touch ordinary things: his mattress, his sleep, the dark he pulls over himself each night. Each one, the surah says, was set in place by the same Lord who has set a Day. The heart that receives this stops experiencing faith as a claim added onto life and starts experiencing life itself as evidence, and the tremendous tiding stops feeling like news from far away.","Its ending administers a dose of holy fear with surgical mercy. To stand unable to speak, to watch a man beg to be dust, and then to close the book and find yourself still in the time of deeds: that is the gift. Whoever recites it slowly walks away wanting to fill the remaining days with what will stand."],"passages":[{"ref":"78:1","why":"The opening question that catches every generation mid-argument about the same tremendous news."},{"ref":"78:9","why":"And We made your sleep a rest: the nightly proof of mercy you experience without noticing."},{"ref":"78:38","why":"The Day the Spirit and the angels stand in rows and none speaks without permission: silence as the deepest awe."},{"ref":"78:40","why":"Would that I were dust: the last sentence of regret, recited now while regret can still change something."}],"connections":[{"to":79,"why":"An-Naba announces the tiding and an-Nazi’at, revealed beside it, shows the single shout that makes it real."},{"to":56,"why":"Both surahs sort humanity on the Day and measure recompense exactly, al-Waqi’ah widening the ranks this surah sketches."}],"virtue":{"text":"No special reward for an-Naba alone is soundly reported, but it stands inside an authentic word: the Prophet ﷺ said that Hud and its sisters had turned his hair grey, and he named among them Amma yatasa’alun. That a surah weighed on the Prophet ﷺ himself is its truest credential; recite it to feel a fraction of that weight.","src":"Tirmidhi 3297","level":"sunnah"}},
/* 79 An-Nazi'at, deep, 46 ayat */
79:{"n":79,"depth":"deep","context":["An-Nazi’at came down in early Makkah, close in time and temper to an-Naba, while Quraysh sharpened their mockery into a taunt: so when is this Hour. The surah answers with motion. It opens on unseen forces, angels tearing souls out violently and drawing them out gently, racing and managing affairs, then collapses the entire cosmic drama into one fact: it is only a single shout, and they are awake on the surface of the earth.","For the small community around the Prophet ﷺ, the surah gave history as reinforcement. Musa was sent to a tyrant at the peak of worldly power, Pharaoh, who gathered his people and declared himself their highest lord, and Allah seized him in an exemplary punishment. Makkah’s chiefs were being told, without their names ever appearing, exactly which story they were living inside, and the believers learned that the arc of tyranny is short even when its shadow is long."],"name_story":"An-Nazi’at means Those Who Wrench Out, the angels who tear the souls of the dying from their bodies, by the reading of Ibn Abbas and the majority. The surah is named for its first oath, five verses of unseen movement sworn before a single claim is made. The name keeps death at the door of the surah: whatever you deny, the extractors are already dispatched.","movements":[{"range":"1-14","h":"Oaths of the extractors","note":"Angels wrenching and gliding, racing and managing, then the quaking blast and hearts pounding, until the deniers who asked about crumbled bones stand awake with one shout."},{"range":"15-26","h":"Musa before the self-crowned tyrant","note":"The story of Musa sent to Pharaoh with the gentlest of invitations, would you purify yourself, and the seizure of the tyrant as a lesson for whoever fears."},{"range":"27-33","h":"Are you harder to create","note":"The raised sky, the darkened night, the earth spread with water and pasture and mountains anchored: creation as the measure that makes resurrection easy."},{"range":"34-41","h":"The overwhelming and the two ends","note":"When the great calamity comes, hellfire is unveiled for the one who chose this life, and the Garden is home for whoever feared the standing before his Lord and refused his soul its whims."},{"range":"42-46","h":"The undatable Hour","note":"They ask when; the Prophet ﷺ is told he is only a warner, and on the Day it will seem they lingered a single evening or its morning."}],"themes":[{"t":"Unseen administration","d":"The opening oaths reveal a universe thick with angelic work, so nothing in death or history is unmanaged."},{"t":"Tyranny’s short arc","d":"Pharaoh’s claim to be the highest lord is answered in two verses of seizure, a compressed biography of every arrogant power."},{"t":"Restraining the soul","d":"Paradise is defined by one inner act, forbidding the nafs, the self, its hawa, its craving, making the decisive battlefield internal."},{"t":"Time collapsed","d":"On the Day, whole lifetimes will feel like an evening or its morning, so delay is exposed as an illusion."}],"heart":["An-Nazi’at is a surah of tempo. Recited slowly, it still moves fast, oaths in motion, a shout, a tyrant seized, the sky built in a breath, and the speed itself is the sermon: your life is passing at exactly this pace. The reciter feels the extractors already at work in the world and stops treating his own soul’s departure as a distant rumor.","Then the surah hands him the one thing it asks him to do with the fear: hold back the self from its craving. Not conquer armies, not date the Hour, only that daily wrenching of desire out of the driver’s seat. Whoever recites it honestly finds the verse of the two ends waiting at every temptation for the rest of the week."],"passages":[{"ref":"79:18","why":"Would you purify yourself: the softest sentence ever addressed to the hardest heart, and the model for every inviter."},{"ref":"79:27","why":"Are you harder to create, or the sky He built: one question that carries the whole argument for resurrection."},{"ref":"79:40","why":"Whoever feared the standing before his Lord and restrained the soul from craving: Paradise traced back to a single inner habit."},{"ref":"79:46","why":"As though they had lingered only an evening or its morning: the verse that shrinks every lifetime to its true length."}],"connections":[{"to":78,"why":"The tremendous tiding disputed in an-Naba arrives here as a single shout and an awakened plain."},{"to":20,"why":"Ta-Ha tells the meeting of Musa and Pharaoh in full; an-Nazi’at compresses the same story into its judgment-day essence."}],"virtue":{"text":"No specific reward is authentically reported for reciting an-Nazi’at on its own, and honesty is better than borrowed praise: the surah needs no certificate. Its standing is its subject, recited by the Prophet ﷺ within the short, dense Makkan surahs that made the Day of Judgment feel present in the room.","src":"","level":"debated"}},
/* 80 Abasa, deep, 42 ayat */
80:{"n":80,"depth":"deep","context":["Abasa came down in Makkah over a moment of human misjudgment that Allah chose to correct in permanent scripture. The Prophet ﷺ was deep in conversation with the chiefs of Quraysh, hoping their Islam would open the city, when Abdullah ibn Umm Maktum, a blind believer of precious sincerity, came asking to be taught. Unable to see the frown his interruption drew, he persisted, and the Prophet ﷺ turned to the men of rank. The report is sound, related from Aishah and others, and the surah descended to reweigh the scene: the seeking heart outweighs the influential ear.","What follows in the Prophet’s ﷺ life is the measure of the man ﷺ. He did not hide the correction; he recited it to the world for the rest of his life, and the books of tafsir relate that he would greet Ibn Umm Maktum with the words, welcome to the one on whose account my Lord reproached me. He left him in charge of Madinah during campaigns, and the blind seeker of one Makkan morning became a caller to prayer of the first community and, at Qadisiyyah, a standard bearer. The surah then widens from the incident to the whole story of man: his small origin, his eased path, his unburied arrogance, and the Day each face will carry its own concern."],"name_story":"Abasa means He Frowned, the surah forever named after the expression it came to correct. The naming itself is part of the message: the Quran records the reproach of the beloved ﷺ openly, which the scholars count among the proofs of its divine origin, since no man writes his own gentle rebuke into his book of authority. Some early lists also call it as-Safarah, the Scribes, after its verses on the noble recording angels.","movements":[{"range":"1-10","h":"The frown reweighed","note":"Heaven measures a moment: the blind man who came striving and fearful is the true opportunity, not the self-sufficient chief being courted."},{"range":"11-16","h":"A reminder in honored pages","note":"The revelation is declared a dignity, carried in purified scrolls by scribes noble and dutiful, offered to whoever wills to remember."},{"range":"17-23","h":"Man’s forgotten smallness","note":"From a drop, through a measured path eased for him, to the grave and the raising: man’s biography told against his ingratitude."},{"range":"24-32","h":"Look at your food","note":"Poured rain, split earth, grain, grapes, olives, and pasture: one meal traced backward becomes a complete lesson in provision."},{"range":"33-42","h":"The Day of the deafening cry","note":"A man flees his brother, mother, and children, every face carries its own concern, and faces end either bright with laughter or covered in dust."}],"themes":[{"t":"Worth measured by striving","d":"Heaven ranks the blind seeker above the courted chief, overturning every social scale in eleven verses."},{"t":"Revelation as honor","d":"The message travels in purified pages through noble scribes, so treating it casually is a failure of perception, not merely of manners."},{"t":"A meal as evidence","d":"The surah proves the Lord through breakfast, teaching that theology begins as close as the plate."},{"t":"Each face its concern","d":"On the Day even family bonds release their grip, and every person is finally a single soul with a single account."}],"heart":["Abasa recited slowly performs a quiet surgery on how the reciter sees people. It catches the heart in its oldest habit, sorting faces by usefulness, and replaces the sorting with one question: who came striving? After this surah, the interruption, the unpolished questioner, the person with nothing to offer, all begin to look like what they are before Allah, doors of mercy dressed as inconvenience.","And it teaches something tender about correction itself. The most beloved of creation ﷺ was corrected, and he carried the correction like a crown, honoring the man ﷺ it arrived through. Whoever recites Abasa learns to stop defending his own frowns, to let admonition in, and to measure every gathering by the seekers in it rather than the powerful."],"passages":[{"ref":"80:3","why":"What would make you know, perhaps he would purify himself: heaven pleading the case of the overlooked."},{"ref":"80:17","why":"Man’s ingratitude confronted in one cry, set between his tiny origin and his waiting grave."},{"ref":"80:24","why":"Let man look at his food: the command that turns an ordinary meal into a tour of providence."},{"ref":"80:37","why":"Every person that Day will have concern enough of his own: the verse that dissolves every crowd into single souls."}],"connections":[{"to":18,"why":"Al-Kahf commands the Prophet ﷺ to keep himself with those who call on their Lord and not to turn his eyes toward worldly adornment, the very principle Abasa enacts."},{"to":6,"why":"Al-An’am had already forbidden sending away the humble believers who call on their Lord morning and evening, and Abasa seals that teaching in a lived scene."}],"virtue":{"text":"No specific recitation reward is authentically reported for Abasa, and it needs none. Its virtue is what it preserves: proof that the Quran is above courtesy to power, and the sound scene of a blind man whose sincerity rewrote the etiquette of every gathering where truth is taught. The report of the incident itself is sound, related in at-Tirmidhi from Aishah.","src":"Tirmidhi 3331, for the occasion, not a recitation reward","level":"debated"}},
/* 81 At-Takwir, deep, 29 ayat */
81:{"n":81,"depth":"deep","context":["At-Takwir came down in early Makkah, in the first wave of surahs that taught the new community what the Day of Judgment actually looks like. Makkah at that hour trusted the permanence of things: the sun rising on schedule, the mountains fixed, wealth stored, and daughters, for some, buried quietly in the sand. The surah unfastens all of it in twelve clauses, sun folded up, stars falling dim, mountains set moving, prized camels abandoned, seas set boiling, and in the middle of the cosmic wreckage it seats one small girl and asks for what sin she was killed.","In the Prophet’s ﷺ life this surah also served as a public defense of the revelation itself. Quraysh whispered that he was mad, or that a devil brought him his words. The second half answers on oath: the message is carried by a noble envoy, Jibril, mighty and trusted near the Owner of the Throne, and your companion ﷺ saw him plainly on the clear horizon. The Prophet ﷺ said that whoever wishes to look at the Day of Rising as if with his own eye should recite this surah and its two sisters."],"name_story":"At-Takwir means the Folding Up, from its first image: when the sun is kuwwirat, wound up like a turban wrapped and put away. The name declares the surah’s method, taking the most dependable object in human experience and packing it away like cloth, so that nothing created can be leaned on again. Early collections also cite it simply by its opening words, idha ash-shamsu kuwwirat.","movements":[{"range":"1-14","h":"Twelve unfastenings and one question","note":"Sun, stars, mountains, camels, beasts, and seas are undone in sequence, souls are paired, the buried girl is asked her sin, and every soul learns what it brought."},{"range":"15-25","h":"The oath of the clear horizon","note":"By the retreating stars and the breathing dawn, the word is sworn to be Jibril’s delivery, and the Prophet ﷺ is cleared: not mad, not stingy with the Unseen, and he truly saw."},{"range":"26-29","h":"So where are you going","note":"One question hangs in the air, the Quran is declared a reminder for the worlds, and human willing is set inside the willing of the Lord of the worlds."}],"themes":[{"t":"Nothing stable but Allah","d":"The surah folds up sun, stars, and mountains precisely so the heart transfers its weight from creation to the Creator."},{"t":"The buried girl’s hearing","d":"Amid cosmic collapse, judgment pauses for one silenced child, teaching that no victim is small enough to be forgotten."},{"t":"A trusted chain of delivery","d":"From the Owner of the Throne through mighty Jibril to the truthful Prophet ﷺ, the surah certifies every link that carried the Quran to your ear."},{"t":"A question for drifting souls","d":"Fa-ayna tadhhabun, so where are you going, is left deliberately open, the Quran’s shortest audit of direction."}],"heart":["At-Takwir recited slowly produces the feeling the Prophet ﷺ promised: sight. The reciter watches the familiar furniture of the sky being carried out piece by piece and understands that his own securities, income, health, reputation, are earlier drafts of the same impermanence. What remains at the end of the smoke is a single sheet with his name on it: every soul will know what it has brought.","The surah’s mercy is that it ends in agency. After the wreckage and the oath comes a door left open, for whoever wills among you to go straight, and the reminder that your willing lives inside the will of a Lord who wants your rescue. The honest reciter closes the surah asking its own question of himself, where exactly am I going, while the road can still be changed."],"passages":[{"ref":"81:8","why":"When the girl buried alive is asked: stop where the Quran gives the silenced their day in court."},{"ref":"81:14","why":"Every soul will know what it has brought: the single line the whole storm was clearing space for."},{"ref":"81:26","why":"So where are you going: four words to carry into every decision of the week."},{"ref":"81:29","why":"You do not will except that Allah wills: ambition and surrender reconciled in one verse."}],"connections":[{"to":82,"why":"The Prophet ﷺ joined this surah with al-Infitar and al-Inshiqaq for whoever wants to see the Day as with the eye, and the two continue one unveiling."},{"to":53,"why":"An-Najm confirms the same vision this surah swears to, the Prophet ﷺ seeing Jibril plainly on the horizon."}],"virtue":{"text":"The Prophet ﷺ said: whoever is pleased to look at the Day of Rising as if seeing it with his own eye, let him recite when the sun is folded up, when the sky breaks apart, and when the sky splits open. The report is graded sound by the critics, and he ﷺ also counted this surah among those that turned his hair grey.","src":"Tirmidhi 3333; Tirmidhi 3297","level":"sunnah"}},
/* 82 Al-Infitar, deep, 19 ayat */
82:{"n":82,"depth":"deep","context":["Al-Infitar came down in early Makkah alongside its sister surahs of cosmic unveiling, in a city that had reduced religion to inherited ritual and commerce. Its opening is brief even by Makkan standards: sky broken, stars scattered, seas burst into one another, graves turned out, and then, with the universe still settling, the surah walks up to a single listener and asks the gentlest hard question in the Quran: O man, what deceived you about your generous Lord?","For the early believers the surah answered the mockery of the deniers with a doctrine of dignity. The One being denied is the very One who assembled each denier’s body in whatever form He willed, and He has not left them unattended: over every soul stand noble scribes, kiraman katibin, recording writers who know what each person does. The community learned to live watched, not by spies, but by honorable witnesses, and to measure every day against the Day when no soul possesses anything for another."],"name_story":"Al-Infitar means the Breaking Apart, from its first verse: when the sky is split open. The name belongs to a family of openings, at-Takwir folds the sun, al-Inshiqaq splits the sky again at the end of the mushaf’s ordering of the group, and this surah cracks it here, each name a different verb of undoing. The early teachers cited it by its opening words, idha as-sama’u infatarat.","movements":[{"range":"1-5","h":"Four ruptures, one disclosure","note":"Sky, stars, seas, and graves are undone in four clauses, and the result is knowledge: each soul sees what it sent ahead and what it left behind."},{"range":"6-12","h":"The question and the scribes","note":"O man, what deceived you about your generous Lord who shaped you as He willed; and above you, noble writers who know whatever you do."},{"range":"13-19","h":"Two records, one Owner","note":"The righteous in delight, the wicked in fire they cannot evade, the Day of Recompense named twice in awe, and the final verse handing all command to Allah."}],"themes":[{"t":"Deceived about generosity","d":"The surah diagnoses sin at its root: mistaking the patience of a generous Lord for absence, and His gifts for permission."},{"t":"Dignity of being watched","d":"The recording angels are called noble and writing, so accountability is framed as honor, a life important enough to document."},{"t":"The body as first blessing","d":"Created, proportioned, balanced: the surah points to the listener’s own assembled frame as the debt he never repaid."},{"t":"Command returns to Allah","d":"On that Day no soul avails another, and the affair, entirely, belongs to Allah: the last verse strips every intermediary."}],"heart":["Al-Infitar recited slowly works through its one question. What deceived you about your generous Lord? Not your harsh Lord, your generous one: the question wounds precisely because it names His kindness. The reciter begins listing his own answers, health mistaken for approval, delay mistaken for indifference, and the list itself becomes tawbah, repentance, before the surah is over.","Then it changes the texture of solitude. Over you are noble writers: the reciter is never again fully alone in a room, and the awareness is strangely warming rather than fearful, like living in the presence of gracious witnesses. By the final verse, the affair that day is Allah’s alone, dependence has quietly shifted off every created shoulder."],"passages":[{"ref":"82:6","why":"O man, what deceived you about your generous Lord: the question to sit inside until it produces an honest answer."},{"ref":"82:10","why":"Over you are noble recording writers: the verse that furnishes every empty room with honorable company."},{"ref":"82:19","why":"The Day no soul owns anything for another, and the command belongs wholly to Allah: the surah’s quiet, total conclusion."}],"connections":[{"to":81,"why":"Joined by the Prophet ﷺ with at-Takwir and al-Inshiqaq as the surahs that let a reciter see the Day as if with his own eye."},{"to":50,"why":"Qaf deepens this surah’s watchers, the sitting receivers on the right and left, and the nearness of the Lord who knows what the soul whispers."}],"virtue":{"text":"Al-Infitar is one of the three surahs of which the Prophet ﷺ said: whoever is pleased to look at the Day of Rising as if seeing it with his own eye, let him recite when the sun is folded up, when the sky breaks apart, and when the sky splits open. The report is graded sound, and no further private virtue needs inventing.","src":"Tirmidhi 3333","level":"sunnah"}},
/* 83 Al-Mutaffifin, deep, 36 ayat */
83:{"n":83,"depth":"deep","context":["Al-Mutaffifin stands at the hinge between the two cities. Ibn Abbas relates that when the Prophet ﷺ arrived in Madinah, its people were among the worst in measuring out goods, and this surah came down, after which they became among the most exact; the report is graded acceptable, and it explains why many teachers call this the last surah of the Makkan period or the first of Madinah. Either way its target is a sin polite society had normalized: taking in full and giving out short, the respectable theft of the scales.","For the community the Prophet ﷺ was building, the surah tied the marketplace to the cosmos. The same people who shortchange a customer, it argues, are the ones who cannot imagine standing before the Lord of the worlds, because a living sense of that standing makes cheating impossible. And it opened a window the believers needed in years of mockery: the record of the righteous is kept high in Illiyyin, witnessed by those brought near, and a day is coming when the laughter reverses direction."],"name_story":"Al-Mutaffifin means Those Who Give Short Measure, from tatfif, skimming a little from what you owe: the surah opens by pronouncing woe upon them. The name is deliberately small, a word for petty skimming rather than grand robbery, because the surah’s point is that no theft is petty before the Lord of the worlds. Early teachers also cited it by its first word, wayl, woe.","movements":[{"range":"1-6","h":"Woe to the skimmers","note":"Those who demand full measure for themselves and shave it for others are asked one question: do they not think they will be raised for a tremendous Day, the Day mankind stands before the Lord of the worlds?"},{"range":"7-17","h":"The record in Sijjin","note":"The register of the corrupt is locked in the lowest place, and their denial is traced to its cause: ran, rust, the film of repeated sins that coats a heart until it cannot see, and the heaviest loss, being veiled from their Lord."},{"range":"18-28","h":"The record in Illiyyin","note":"The register of the righteous is kept high and witnessed by those brought near; their faces shine, their drink is sealed nectar, and the verse cries out: for this let the competitors compete."},{"range":"29-36","h":"The laughter reversed","note":"The criminals who laughed, winked, and called the believers astray are watched from couches on the Day, and heaven asks with terrible calm whether the disbelievers have been repaid for what they used to do."}],"themes":[{"t":"Scales as theology","d":"How a person measures out for others is treated as a confession of whether he truly expects to stand before the Lord of the worlds."},{"t":"Rust on the heart","d":"Sin is pictured as corrosion, each repetition another layer, until denial is not an argument but a blindness."},{"t":"The greatest deprivation","d":"Worse than the fire, the surah counts being veiled from the Lord that Day, making His presence the true reward all along."},{"t":"Compete for the sealed cup","d":"Ambition is not condemned but redirected: let the strivers strive for the drink whose seal is musk."}],"heart":["Al-Mutaffifin recited slowly walks into the reciter’s ordinary dealings and turns the lights on. The measure is not only the merchant’s: it is the employee’s hours, the spouse’s patience, the friend who demands loyalty in full and pays it short. The surah makes one habit of the heart, insisting on your rights while trimming others’, feel like what it is, disbelief in the standing, practiced daily in small change.","Then it does something for the mocked. Whoever has been laughed at for prayer, for hijab, for honesty that cost money, finds here a promise kept in exact currency: the couches, the gazing, the laughter’s return journey. The reciter leaves the surah with clean scales and a long gaze, competing, as the verse commands, for something worth competing over."],"passages":[{"ref":"83:1","why":"Woe to those who give short measure: let the opening name the habit before you excuse it."},{"ref":"83:6","why":"The Day mankind stands before the Lord of the worlds: the single image that makes honest scales easy."},{"ref":"83:14","why":"Rust upon their hearts from what they earned: the Quran’s exact diagnosis of how denial actually forms."},{"ref":"83:26","why":"For this let the competitors compete: ambition released at last toward a prize that cannot rot."}],"connections":[{"to":55,"why":"Ar-Rahman set the balance in the architecture of the heavens and commanded, do not cheat the scale; al-Mutaffifin prosecutes the violation."},{"to":11,"why":"Hud carries Shu’ayb’s plea to his people over the same sin, give full measure and weight and do not shortchange people their due."}],"virtue":{"text":"No specific recitation reward for al-Mutaffifin is authentically reported, and the surah needs no certificate: it carries its proof in its subject. What is soundly reported is its effect, Ibn Abbas relating that after it came down the people of Madinah became among the most exact in measure, a virtue written in marketplace scales rather than reward lists.","src":"Ibn Majah 2223, hasan","level":"debated"}},
/* 84 Al-Inshiqaq, deep, 25 ayat */
84:{"n":84,"depth":"deep","context":["Al-Inshiqaq came down in early Makkah among the surahs that rehearse the Day until it becomes visible. Its distinctive note is obedience: the sky splits and listens to its Lord, as it rightly must, the earth stretches flat and empties what is inside her and listens, as she rightly must. Two enormous creations model the surrender that one small creation, man, keeps refusing, and into that contrast the surah drops its address: O man, you are laboring toward your Lord with a laboring, and will meet Him.","In the Prophet’s ﷺ practice this surah carried a live prostration. Abu Hurayrah prostrated while reciting it and said, I saw the Messenger of Allah ﷺ prostrate in it, at the verse asking why they do not bow when the Quran is recited to them, so the congregation would answer the question with their bodies. For the early believers, mocked in Makkah, the surah divided the future by which hand receives the book, and promised the deniers’ ease was a stage, since people ride stage after stage into what they were made for."],"name_story":"Al-Inshiqaq means the Splitting Open, from its first verse: when the sky is split. It completes the family of openings, at-Takwir folding the sun and al-Infitar cracking the sky, and the Prophet ﷺ tied the three together as one viewing of the Day. Reciters also know it by its first words, idha as-sama’u inshaqqat, and by its prostration, one of the places the Quran expects a forehead.","movements":[{"range":"1-6","h":"The obedient sky, the laboring man","note":"Sky and earth submit to their Lord as is their duty, and man is told the truth of his condition: a toiler moving toward his Lord, certain to meet Him."},{"range":"7-15","h":"Two hands, two reckonings","note":"The book in the right hand brings an easy accounting and a joyful return; the book behind the back brings a cry for ruin, for a man who lived delighted, certain he would never return."},{"range":"16-19","h":"Oath of the stages","note":"By the twilight, the night and what it gathers, and the full moon: you will surely ride stage upon stage, no condition final, every soul in transit."},{"range":"20-25","h":"The refused prostration","note":"Why do they not believe, why not bow when the Quran is recited; Allah knows what they store within, and the believers are promised a reward that never cuts off."}],"themes":[{"t":"Creation models surrender","d":"Sky and earth obey as is their right and duty, shaming the one creature who was offered the choice and declines."},{"t":"Toil that ends in meeting","d":"Everyone is laboring toward the Lord, believer and denier alike; the only open question is what the meeting will be like."},{"t":"The easy reckoning","d":"The Prophet ﷺ explained the easy accounting as presentation without interrogation, the mercy every reciter should ask for by name."},{"t":"Stage after stage","d":"Tabaqan an tabaq: life, death, and rising are ranks of one ascent, so no comfort and no hardship is a final address."}],"heart":["Al-Inshiqaq recited slowly names the tiredness every honest person carries: kadih, a laborer straining. You were never promised the toil would stop, the surah says, only that it points somewhere, and everything depends on which direction your straining faces. Work aimed at your Lord arrives at your Lord; work aimed anywhere else still arrives at Him, only without its wages.","The verse of stages then loosens the grip of every present condition. The delighted man who thought he would never change is the surah’s warning, and the believer in difficulty is its comfort: you will ride stage upon stage. The reciter rises from this surah with one du’a in his mouth, the Prophet’s ﷺ own, O Allah, give me an easy reckoning, and one habit renewed, answering recited verses with a lowered forehead."],"passages":[{"ref":"84:6","why":"O man, you are laboring toward your Lord and will meet Him: the verse that gives every exhaustion its true address."},{"ref":"84:8","why":"He will be reckoned with an easy accounting: hear the mercy the Prophet ﷺ taught us to ask for in these exact words."},{"ref":"84:19","why":"You will surely ride stage upon stage: for whoever thinks his present condition, sweet or bitter, is permanent."},{"ref":"84:21","why":"Why do they not prostrate when the Quran is recited: a verse the Prophet ﷺ answered with his forehead, and so should we."}],"connections":[{"to":81,"why":"One of the three surahs the Prophet ﷺ prescribed together for whoever wants to see the Day of Rising as if with his own eye."},{"to":69,"why":"Al-Haqqah stages in full the scene this surah compresses, the book taken in the right hand or otherwise, and the words of each receiver."}],"virtue":{"text":"Al-Inshiqaq is the third of the surahs of which the Prophet ﷺ said: whoever is pleased to look at the Day of Rising as if with his own eye, let him recite them; the report is graded sound. It also carries an established prostration: Abu Hurayrah prostrated in it and said, I saw the Messenger of Allah ﷺ prostrate in it.","src":"Tirmidhi 3333; Muslim 578","level":"sunnah"}},
/* 85 Al-Buruj, deep, 22 ayat */
85:{"n":85,"depth":"deep","context":["Al-Buruj came down in Makkah while torture was current events. Bilal under the boulder, Sumayyah and Yasir under Abu Jahl’s spear, Khabbab’s back against the coals: the first believers were meeting the old machinery of persecution, and Allah answered not with a promise of quick rescue but with a story. Long before them, believers were herded to trenches filled with fire by a king whose only complaint against them was that they believed in Allah, the Mighty, the Praiseworthy. The people of the ditch sat and watched the burning, and heaven watched them.","The Prophet ﷺ later told the fuller story of that boy and that king, preserved in Sahih Muslim, a monk, a lad who would not sell his faith, a people burned in trenches, and in it the stunning arithmetic of the surah: the burned believers won. Success in this surah is called al-fawz al-kabir, the great triumph, and it is awarded inside the fire, not after escape from it. For a community facing Quraysh, and for every scorched believer since, al-Buruj moved the scoreboard out of the tyrant’s reach."],"name_story":"Al-Buruj means the Great Constellations, the towers of stars by which the surah opens its oath: by the sky holding the buruj. The name lifts the eye deliberately, from a trench of fire scraped in the dirt to fortresses of light no king can reach, the same movement the surah performs for the tortured heart. Early reciters cited it by its oath, was-sama’i dhat al-buruj.","movements":[{"range":"1-9","h":"The trench and the watchers","note":"Under oath of the towered sky and the promised Day, the people of the ditch are cursed: they sat by their fire witnessing what they did to believers whose only offense was faith in the Mighty, the Praiseworthy."},{"range":"10-16","h":"The scoreboard of heaven","note":"Those who burned believers and never repented face the burning; those who believed hold the great triumph; and the Lord of it all is Forgiving, Loving, Owner of the Throne, doer of whatever He intends."},{"range":"17-22","h":"Armies end, the Quran remains","note":"Pharaoh and Thamud pass in a line apiece, deniers remain encircled by Allah from behind, and the surah closes on a glorious Quran kept in a guarded tablet."}],"themes":[{"t":"Faith as the only charge","d":"The tyrant’s indictment is quoted in full, they believed in Allah, exposing every persecution since as rage against belief itself."},{"t":"Victory redefined","d":"The burned believers receive the great triumph, so winning is loyalty kept, not outcomes secured."},{"t":"Al-Wadud amid the fire","d":"In the surah of atrocity Allah names Himself the Loving, teaching that His affection for His people burns brighter than any trench."},{"t":"Power that outlasts armies","d":"Pharaoh’s hosts and Thamud take one line each, while the guarded tablet endures, a lesson in what history actually keeps."}],"heart":["Al-Buruj recited slowly resets the reciter’s definition of losing. The believers in the trench lose everything a court could count, and the surah calls their case the great triumph, because they carried faith across the line intact. Whoever recites this while paying any price for religion, mockery, a passed promotion, a family’s cold shoulder, hears heaven keeping a different ledger, and the fire in the story shrinks next to the watching of Allah.","The name al-Wadud, the Loving, placed in this surah of all surahs, is its deepest medicine. The tortured are not abandoned; they are beloved, seen, and recorded, and their tormentors are encircled without knowing it. The reciter rises with a spine he did not have before, and a strange pity for the men beside the trench who thought they were the strong ones."],"passages":[{"ref":"85:8","why":"They resented them only for believing in Allah: the verse that names the real crime behind every persecution."},{"ref":"85:11","why":"Gardens beneath which rivers flow, called the great triumph: heaven’s scoreboard read aloud over the ashes."},{"ref":"85:14","why":"And He is the Forgiving, the Loving: al-Wadud, spoken exactly where love seems most absent."},{"ref":"85:21","why":"Rather, it is a glorious Quran: what remains when every army in the surah has turned to a line of history."}],"connections":[{"to":18,"why":"The youths of the cave fled with their faith and were sheltered; the people of the ditch stayed and burned; the two surahs teach one loyalty with two endings."},{"to":90,"why":"Al-Balad and al-Buruj both weigh hardship honestly, man created in toil, believers tried in fire, and both end sorting humanity by faith and denial."}],"virtue":{"text":"No specific reward for reciting al-Buruj alone is authentically established, but the Prophet ﷺ honored it in practice: Jabir ibn Samurah relates that he ﷺ would recite in Zuhr and Asr, the midday and afternoon prayers, by the sky holding the constellations and by the sky and the night visitor. A surah the Prophet ﷺ chose for daily prayer needs no further certificate.","src":"Abu Dawud 805, sahih","level":"sunnah"}},
/* 86 At-Tariq, deep, 17 ayat */
86:{"n":86,"depth":"deep","context":["At-Tariq came down in Makkah in the period when Quraysh had moved from mockery to strategy: plots in the assembly, pressure on clans, plans to end the matter of Muhammad ﷺ quietly. The surah answers with the night sky and a single doctrine of guardianship: by the heaven and the night-comer, the piercing star, there is no soul without a keeper standing over it. The Prophet ﷺ walked out of their councils guarded, and so does every soul walk guarded through its nights.","For the early community the surah also carried the argument they used at every doorstep: look at your own beginning. Man is created from an ejected drop, from between the loins and the ribs; the One who ran that first assembly line can certainly run it again on the Day the secrets are tested, when no strength and no helper stands with a man. And it ends with counsel the besieged believers needed: the plotters plot, Allah plots, so give them time, deal gently with them for a little while."],"name_story":"At-Tariq means the Night Visitor, the one who arrives knocking after dark, and the surah itself asks and answers what it is: an-najm ath-thaqib, the star that pierces the blackness. The old Arabs used tariq for a traveler knocking at night, so the name carries both senses at once, something luminous arriving in the dark, which is also a fair description of revelation reaching Makkah.","movements":[{"range":"1-4","h":"The star and the keeper","note":"An oath by the sky and its piercing night visitor seals one sentence: there is no soul without a guardian appointed over it."},{"range":"5-10","h":"Look at your first assembly","note":"Man is invited to examine his own making from a gushing drop, proof that his Maker can return him on the Day the secrets are laid bare, when he has neither strength nor helper."},{"range":"11-17","h":"A decisive word, a gentle delay","note":"By the sky that returns rain and the earth that splits with growth, the Quran is sworn to be a decisive word and no jest; the plotters are answered, and the Prophet ﷺ is told to grant them gentle respite."}],"themes":[{"t":"Guarded souls","d":"Every soul carries an appointed keeper, so no night, no plot, and no solitude is actually unattended."},{"t":"Origins as argument","d":"The surah proves resurrection from conception: the One who built you from a drop finds rebuilding light work."},{"t":"The day secrets are tested","d":"Sara’ir, the hidden things, will themselves be examined, moving the final exam from actions to interiors."},{"t":"A word that decides","d":"The Quran is qawlun fasl, a decisive word, not entertainment; every hearer leaves either divided from error or still joking."}],"heart":["At-Tariq recited slowly at night does exactly what its oath does: it makes the dark friendly to faith. The reciter looks up at one piercing star and hears that he, too, is watched over, every soul with its keeper, and the anxieties that patrol after midnight meet a guardian already posted. This is a surah to recite when plots, real or imagined, crowd the chest.","Then it turns the reciter inward with one phrase, the Day the secrets are tested. Not the resume, the secrets: the motives under the deeds, the grudges under the smiles. Whoever sits with that verse begins cleaning rooms no one else ever inspects, and learns from the surah’s ending to answer his own enemies as Allah counsels, with patience that can afford to wait."],"passages":[{"ref":"86:4","why":"There is no soul without a keeper over it: the night watchman verse, guardianship declared over you by oath."},{"ref":"86:9","why":"The Day the secrets are tested: one line that relocates the final exam to the heart’s interior."},{"ref":"86:13","why":"It is truly a decisive word: hear the Quran name its own seriousness, and no jest alongside it."},{"ref":"86:17","why":"Give the deniers respite, gently, for a while: divine patience prescribed as the believer’s tactic."}],"connections":[{"to":85,"why":"Recited together by the Prophet ﷺ in the daytime prayers, two oaths of the sky, one on its towers and one on its night visitor."},{"to":100,"why":"Al-Adiyat ends where at-Tariq begins, with what the chests conceal brought out and tested before the Lord who knows."}],"virtue":{"text":"No separate reward for at-Tariq is authentically reported, and it needs none: its established honor is the Prophet’s ﷺ own voice, for he would recite it in Zuhr and Asr, as Jabir ibn Samurah relates. A place in the daily prayers of the Messenger ﷺ is a virtue beyond any unverified promise.","src":"Abu Dawud 805, sahih","level":"sunnah"}},
/* 87 Al-A'la, deep, 19 ayat */
87:{"n":87,"depth":"deep","context":["Al-A’la came down early in Makkah, in the tender years when the Prophet ﷺ still feared losing the revelation faster than it arrived, reciting hurriedly with Jibril lest a word escape. This surah carried the promise that untied that knot: We shall make you recite, and you will not forget, except what Allah wills. The Quran’s preservation was moved off the Prophet’s ﷺ memory and onto its Sender, and the same surah promised, We will ease you toward ease, a sentence that became the melody of his whole mission.","In the community’s life this surah became a fixture of gathered worship: the Prophet ﷺ recited it in the two Eid prayers, in Jumu’ah, the Friday prayer, and in Witr, the closing odd prayer of the night, and when he heard its first verse he would say, glorify the name of your Lord, the Most High, obeying it mid-recitation. Ali relates that the Prophet ﷺ loved this surah. Its closing note, that this teaching stands in the first scrolls, the scrolls of Ibrahim and Musa, told the young community they were not a novelty but the latest voice of the oldest truth."],"name_story":"Al-A’la means the Most High, from the opening command: glorify the name of your Lord, the Most High. The surah is named for Allah’s own exaltedness, and the Prophet ﷺ answered its name every time it was recited, saying subhana rabbiya al-a’la, exalted is my Lord, the Most High, the words the ummah still says in every prostration. Reciters also call it Sabbih, glorify, after its first word.","movements":[{"range":"1-5","h":"Glorify the One who measures","note":"The Most High is glorified as the One who created and proportioned, who measured and then guided, who brings out the pasture and turns it to dark stubble: power and tenderness in one breath."},{"range":"6-8","h":"Memory carried by its Sender","note":"The Prophet ﷺ is promised recitation without forgetting, knowledge of the open and hidden, and a path eased toward ease."},{"range":"9-15","h":"Remind, and the two responses","note":"Reminder is commanded where it benefits; the fearful will take heed, the wretched will sidestep toward the greatest fire, and success is written for whoever purifies, remembers the name of his Lord, and prays."},{"range":"16-19","h":"The old truth about two lives","note":"People prefer the immediate life though the last one is better and lasting, and this very teaching, the surah says, stands in the first scrolls, of Ibrahim and Musa."}],"themes":[{"t":"Measured, then guided","d":"Qaddara fa-hada: everything is given its measure and then shown its way, a two-word map of providence from moth to man."},{"t":"Ease as a promise","d":"We will ease you toward ease, spoken first to the Prophet ﷺ, defines the religion’s grain: the path itself leans toward relief."},{"t":"Purification then prayer","d":"Success is sequenced, cleanse, remember, pray, an order of operations for any soul that wants to rise."},{"t":"One message, many scrolls","d":"The closing verses anchor the Quran in the scrolls of Ibrahim and Musa, making Islam a continuation, not an invention."}],"heart":["Al-A’la recited slowly tunes the reciter the way it tuned the Prophet’s ﷺ nights: it begins in glorification and everything after inherits the calm. The promise of ease is the surah’s heartbeat, and whoever recites it while overwhelmed, by memorization, by work, by grief, feels the load shift onto the One who eases. What Allah carries stays carried.","Its middle verses quietly test the reciter’s honesty: the reminder benefits the one who fears, and slides off the one who has chosen not to hear. And its ending performs the oldest correction, you prefer the immediate, though the lasting is better, in words old enough for Ibrahim’s scrolls. To recite al-A’la is to rejoin a glorification that has never once paused since the first prophet opened the first page."],"passages":[{"ref":"87:3","why":"He measured, then guided: four words to recite over every creature and every circumstance you cannot understand."},{"ref":"87:8","why":"We will ease you toward ease: the promise made to the Prophet ﷺ that every burdened reciter is invited to stand under."},{"ref":"87:14","why":"Succeeded is the one who purifies: success defined once, cleanly, before the world offers its other definitions."},{"ref":"87:17","why":"The last life is better and more lasting: the sentence that reprices everything currently on sale in front of you."}],"connections":[{"to":88,"why":"The Prophet ﷺ paired al-A’la and al-Ghashiyah in Jumu’ah and the two Eids, glorification first, then the Overwhelming Day."},{"to":53,"why":"An-Najm cites the same scrolls of Ibrahim and Musa and unpacks what they contained: no bearer carries another’s burden, and man has only what he strives for."}],"virtue":{"text":"The Prophet ﷺ recited al-A’la in the two Eid prayers and on Jumu’ah, and in Witr with al-Kafirun and al-Ikhlas, and Ali relates that he ﷺ loved this surah. When he heard its opening he would answer, exalted is my Lord, the Most High. These are established practices, a virtue of constant use rather than a single reward report.","src":"Muslim 878; an-Nasa’i 1729","level":"sunnah"}},
/* 88 Al-Ghashiyah, deep, 26 ayat */
88:{"n":88,"depth":"deep","context":["Al-Ghashiyah came down in Makkah while the city’s notables were demanding miracles and refusing arithmetic. The surah opens like a hand on the shoulder, has the news of the Overwhelming reached you, and then shows the Day as two processions of faces, one exhausted and scorched from a lifetime of labor spent on the wrong ledger, one soft with pleasure at its own striving. The frightening suggestion, drawn out by the commentators, is that the toiling faces worked hard: effort alone saves no one if it serves falsehood.","In Madinah this surah settled into the rhythm of public worship: the Prophet ﷺ recited it with al-A’la in the Friday and Eid prayers, so whole congregations heard the Overwhelming named on their days of celebration, joy kept honest by remembrance. Its middle verses handed the earliest believers their everyday apologetics, the camel, the sky, the mountains, the earth, arguments a shepherd could carry, and its ending defined the Prophet’s ﷺ office in two lines: you are only a reminder, you are not over them a controller."],"name_story":"Al-Ghashiyah means the Overwhelming, the calamity that covers everything, one of the Quran’s names for the Day of Rising, taken from the surah’s first verse. The name works like the surah: it does not argue that the Day will come, it asks whether its news has reached you, as though the only open question is your attention. Early reciters knew it as the companion of Sabbih in the prayers of gathering.","movements":[{"range":"1-7","h":"Faces that toiled for nothing","note":"On the Overwhelming Day some faces are humbled, laboring and exhausted, roasting at a boiling spring, fed from a thorn that neither nourishes nor stills hunger."},{"range":"8-16","h":"Faces soft with striving","note":"Other faces are pleased with their striving, in a high garden where no idle word is heard, among springs, couches, cups, cushions, and spread carpets."},{"range":"17-20","h":"Four exhibits for the doubter","note":"The camel and how it was created, the sky and how it was raised, the mountains and how they were set, the earth and how it was spread: evidence at eye level."},{"range":"21-26","h":"A reminder, not a warden","note":"The Prophet ﷺ is only a reminder, not a controller over hearts; whoever turns away meets the greatest punishment, and to Us, says Allah, is their return, and upon Us their account."}],"themes":[{"t":"Wasted labor","d":"The toiling, weary faces warn that effort is not merit: a life can be exhausting and still be spent against its own interest."},{"t":"No idle word","d":"The garden’s luxuries include silence from laghw, worthless talk, ranking clean speech among the pleasures of Paradise."},{"t":"Evidence at eye level","d":"Camel, sky, mountain, earth: the surah teaches ordinary people to argue for God from what stands in front of them."},{"t":"The limits of the office","d":"You are only a reminder: guidance of hearts is retained by Allah, freeing every caller from a burden that was never his."}],"heart":["Al-Ghashiyah recited slowly makes the reciter audit not his effort but its direction. The surah’s first faces are not lazy, they are exhausted, and that is the terror of it: whole careers of striving can arrive at a boiling spring. The honest reciter stops asking, am I working hard, and starts asking, for whom is this work, and feels the second set of faces, pleased with their striving, as the description he wants read over him.","Its closing pair of verses then unclenches two different hands. The caller stops gripping other people’s guidance, you are only a reminder, and the sinner stops imagining escape, to Us is their return, upon Us their account. What remains is a strange, spacious calm: do your striving, deliver your reminder, and leave the ledgers with their Owner, who was always going to hold them anyway."],"passages":[{"ref":"88:11","why":"No idle word is heard there: Paradise described by its silence, a verse that reorders what counts as luxury."},{"ref":"88:17","why":"Do they not look at the camel, how it was created: the Quran teaching theology from the nearest living argument."},{"ref":"88:21","why":"Remind, for you are only a reminder: the verse that defines the believer’s duty and its merciful limit in one breath."},{"ref":"88:25","why":"Surely to Us is their return: the sentence that closes every account you were never asked to settle."}],"connections":[{"to":87,"why":"Paired by the Prophet ﷺ in Jumu’ah and Eid: al-A’la lifts the name of the Most High, al-Ghashiyah shows the Day that name commands."},{"to":102,"why":"At-Takathur diagnoses the racing for more that leaves faces toiling and weary here, until visiting the graves interrupts the race."}],"virtue":{"text":"The established virtue of al-Ghashiyah is its station in the Prophet’s ﷺ public worship: an-Nu’man ibn Bashir relates that he ﷺ recited al-A’la and al-Ghashiyah in the two Eid prayers and on Jumu’ah, and when Eid and Jumu’ah fell on one day he recited them in both. No separate reward report exists, and none is needed for a surah the Prophet ﷺ chose for the ummah’s days of gathering.","src":"Muslim 878","level":"sunnah"}},
/* 89 Al-Fajr, deep, 30 ayat */
89:{"n":89,"depth":"deep","context":["Al-Fajr came down in Makkah while the city’s aristocracy still read wealth as verdict: gain meant heaven’s approval, loss meant its contempt. The surah opens with a string of hushed oaths, the dawn, ten nights, the even and the odd, the night as it travels, and then parades the corpses of that theory: Ad of the pillared Iram, Thamud who carved the rock valley, Pharaoh of the stakes, each mighty, each transgressing, each poured over with a whip of punishment by a Lord who is ever at the watchpost.","For the Prophet ﷺ and the believers stripped of goods and protection, the surah performed a rescue of meaning: being given much is not honor, being straitened is not humiliation, both are tests, and the real charges heaven files are these, not honoring the orphan, not urging the feeding of the poor, devouring inheritance, loving wealth with a piled-up love. Its last verses, the address to the soul at rest, became one of the most beloved passages in the whole Quran, recited at bedsides and gravesides ever since the first generation."],"name_story":"Al-Fajr means the Dawn, the surah’s first oath, the moment night’s back breaks. Many early commentators read the ten nights alongside it as the first ten of Dhul-Hijjah, the days of sacrifice, or the last ten of Ramadan, nights when darkness and devotion meet exactly as the surah’s oaths do. The name promises what the ending delivers: after the long night of trial, a soul greeted like sunrise, told to enter among My servants.","movements":[{"range":"1-14","h":"Oaths, ruins, and the watchpost","note":"Dawn, ten nights, the even and the odd swear witness, then Ad, Thamud, and Pharaoh pass as case studies of power that transgressed, under the verse that hangs over all history: your Lord is ever watching."},{"range":"15-20","h":"The false ledger of honor","note":"Man reads gifts as honor and tight provision as contempt; the surah answers kalla, no, and files the true charges: orphans unhonored, the poor unfed, inheritance devoured, wealth loved to hoarding."},{"range":"21-26","h":"The Day regret arrives late","note":"Earth pounded flat, your Lord arriving with angels rank on rank, Jahannam brought near: that Day man remembers, but how can remembering help, and he says, would that I had sent ahead for my life."},{"range":"27-30","h":"The soul at rest comes home","note":"O reassured soul, return to your Lord, pleased and pleasing, enter among My servants, enter My garden: the gentlest homecoming in the Quran."}],"themes":[{"t":"Provision is a test","d":"Wealth and want are both examinations, not verdicts, dismantling the oldest confusion between fortune and favor."},{"t":"The Lord at the watchpost","d":"Bil-mirsad: tyrants operate under observation, and the delay of justice is surveillance, not absence."},{"t":"Charges heaven files","d":"The surah’s indictment is social, orphans, the hungry, inheritance, hoarding, making neglect of the weak a matter of creed."},{"t":"The reassured soul","d":"An-nafs al-mutma’innah, the soul at rest through remembrance, is the surah’s destination and the Quran’s portrait of a finished heart."}],"heart":["Al-Fajr recited slowly first empties the reciter’s hands of the world’s scorecard. Watching Iram’s pillars and Pharaoh’s stakes fall in three verses, he stops reading his bank balance as heaven’s opinion of him, in either direction. Then the surah reads its charge sheet, and every count is about the weak, the orphan, the hungry, the inheritance of the voiceless, and the reciter understands what his Lord actually audits.","And then, after the pounded earth and the too-late remembering, the surah does something almost unbearably tender: it turns from the terror and speaks to one soul in the singular. O reassured soul, return. Pleased and pleasing. Enter among My servants, enter My garden. Whoever recites these verses slowly is given, for a moment, the sound of the welcome every believer is walking toward, and the rest of the surah becomes the price worth paying for it."],"passages":[{"ref":"89:14","why":"Your Lord is ever at the watchpost: the verse that explains every delay of justice as observation, not absence."},{"ref":"89:17","why":"No, rather you do not honor the orphan: heaven’s real charge sheet begins, and it begins with the weak."},{"ref":"89:24","why":"Would that I had sent ahead for my life: hear the sentence now, while sending ahead is still possible."},{"ref":"89:27","why":"O reassured soul, return to your Lord: the homecoming verses, the destination of the whole religion in four lines."}],"connections":[{"to":90,"why":"Al-Fajr swears by nights and cities of ruin, al-Balad by this city and man in toil: two audits of wealth, hardship, and the weak, side by side."},{"to":102,"why":"At-Takathur names the piling love of more that al-Fajr indicts, the race that only the visit to the graves interrupts."}],"virtue":{"text":"No specific recitation reward for al-Fajr is soundly established, and it needs no certificate: its closing address to the reassured soul is among the most beloved passages the ummah possesses, recited from the first generation over the dying and the beloved dead. Its virtue is what it promises, a soul brought home pleased and pleasing.","src":"","level":"debated"}},
/* 90 Al-Balad, deep, 20 ayat */
90:{"n":90,"depth":"deep","context":["Al-Balad came down in Makkah, and it is Makkah it swears by: I swear by this city, and you, ﷺ, are a lawful resident in this city, a verse the commentators heard on two levels, the Prophet’s ﷺ belonging to the sanctuary that was mistreating him, and a foretelling of the day its sanctity would be lifted for him for one hour of conquest. Around him, men boasted of wealth destroyed in heaps for show, and the surah answers with its blunt anthropology: We created man in kabad, in toil and strain, from the clasp of birth to the last breath.","For the struggling believers the surah then drew the map they needed: since hardship is the terrain of every life, the only question is which climb your strain serves. Man was given two eyes, a tongue, two lips, and guidance to the two high roads, and most decline the steep one. Al-aqabah, the steep path, is then defined without a single ritual in the list: freeing a neck from slavery, feeding the hungry in a day of famine, the orphan of kin, the poor man lying in the dust, then joining those who believe and counsel each other to patience and mercy."],"name_story":"Al-Balad means the City, and the city is Makkah, sworn by while its stones were still hostile to the one ﷺ it swore by. The name holds the surah’s irony with perfect economy: the most sacred ground on earth, filled with men spending fortunes on pride while necks stayed chained and orphans hungry, and heaven measuring the city not by its stones but by its mercy. Reciters know it by its opening, la uqsimu bi-hadha al-balad.","movements":[{"range":"1-4","h":"Sworn by the city of toil","note":"By Makkah, by the Prophet’s ﷺ residence in it, by begetter and begotten: man is created in kabad, strain upon strain, and no life escapes the climb."},{"range":"5-10","h":"Squandered strength, given tools","note":"Man boasts of wealth destroyed in heaps and thinks no one sees; the surah answers with his inventory, two eyes, a tongue, two lips, and guidance to the two high roads."},{"range":"11-16","h":"The steep path defined","note":"He has not attempted al-aqabah, the steep ascent, and what is it: freeing a neck, feeding in a day of hunger an orphan of kin or a poor man in the dust."},{"range":"17-20","h":"Then the company that carries you","note":"After the climb, belonging: among those who believe and counsel one another to patience and to compassion, the companions of the right, while deniers are the companions of the left, fire closed over them."}],"themes":[{"t":"Toil is the terrain","d":"Kabad, strain, is declared man’s created condition, so the choice is never ease or hardship, only which hardship."},{"t":"Mercy as mountain climbing","d":"The steep path is freeing slaves and feeding the desperate, ranking costly compassion above every cheap display."},{"t":"Tools imply accounting","d":"Two eyes, a tongue, two lips, and two shown roads: equipment given is testimony waiting."},{"t":"Belonging after striving","d":"The climb ends in a community of mutual counsel, patience and compassion traded like provisions among climbers."}],"heart":["Al-Balad recited slowly relieves the reciter of a lie he did not know he believed: that somewhere ahead is a version of life without strain. Created in toil, says his Lord, and the sigh that follows is strangely restful, because once strain is the given, the heart stops asking how to escape it and starts asking where to spend it. The surah answers with a slope: a neck freed, a mouth fed in famine, an orphan of your own kin.","Its quiet test is the wealth verse. I have destroyed wealth in heaps, boasts the man, and the reciter checks his own heaps, spending that performs, effort that impresses, strain that serves nothing that will meet him on the Day. Whoever recites al-Balad honestly walks out looking for the steep path in his own street, and for the companions of patience and mercy to climb it with."],"passages":[{"ref":"90:4","why":"We created man in toil: the verse that retires the fantasy of an effortless life and dignifies your strain."},{"ref":"90:10","why":"And We guided him to the two high roads: every choice you will ever face, drawn in one line."},{"ref":"90:11","why":"Yet he has not attempted the steep path: let the reproach find you, then let the next verses tell you where it is."},{"ref":"90:17","why":"Counseling one another to patience and to compassion: the job description of believing company."}],"connections":[{"to":89,"why":"Al-Fajr indicts the unfed poor and unhonored orphan, al-Balad turns the same charges into the climb that saves."},{"to":103,"why":"Al-Asr compresses this surah’s ending into its creed: loss for all, except those who believe and counsel one another to truth and patience."}],"virtue":{"text":"No specific recitation reward for al-Balad is authentically reported, and the surah needs no certificate: Allah swore by His own sanctuary and by His Prophet’s ﷺ residence within it, and that oath is honor enough. Its virtue is practical, whoever recites it is handed the steep path and shown exactly where it begins.","src":"","level":"debated"}},
/* 91 Ash-Shams, deep, 15 ayat */
91:{"n":91,"depth":"deep","context":["Ash-Shams came down in Makkah with the longest opening oath sequence in the Quran: sun and its morning light, the moon that follows, day that reveals, night that covers, the sky and its building, the earth and its spreading, and then the target of all seven, the soul and the One who proportioned it and inspired into it its rebellion and its guarding. Seven cosmic witnesses are sworn for one verdict about the thing inside your ribs: he has succeeded who purifies it, he has failed who buries it.","The Prophet ﷺ kept this surah in the community’s daily soundscape: when Mu’adh led the people in long prayers and complaints reached him ﷺ, he prescribed measure with it, pray with sabbihisma rabbika al-a’la, wash-shamsi wa-duhaha, wal-layli idha yaghsha, surahs complete enough to feed and short enough to carry. Its second half gave Makkah a warning in miniature: Thamud, one wretched volunteer, one hamstrung camel, and a leveling so total that their Lord, the surah says with terrifying serenity, does not fear its consequence."],"name_story":"Ash-Shams means the Sun, the first of the surah’s seven sworn witnesses, sworn with its duha, its morning brightness. The name fits more than the first verse: the surah is about illumination and burial, a soul polished until it shines like morning or covered handful by handful like a sun going down in dust, dassaha, buried, the word used for hiding a thing in the earth. Reciters know it by its opening breath, wash-shamsi wa-duhaha.","movements":[{"range":"1-8","h":"Seven oaths aimed at the soul","note":"Sun, moon, day, night, sky, earth, and then the nafs, the soul, proportioned by its Maker and inspired with both its recklessness and its guarding: the case is prepared."},{"range":"9-10","h":"The verdict in two lines","note":"He has truly succeeded who purifies the soul, and he has truly failed who buries it: the shortest, sharpest sentence ever passed on the human project."},{"range":"11-15","h":"Thamud: a soul buried at scale","note":"Thamud denied in its rebellion, the wretchedest of them rose, the messenger of Allah said, the she-camel of Allah and her drink, they hamstrung her, and their Lord leveled them and does not fear the outcome."}],"themes":[{"t":"Two inspirations within","d":"Every soul ships with both fujur, recklessness, and taqwa, guarding, so the inner war is standard equipment, not a defect."},{"t":"Purify or bury","d":"Tazkiyah, purification, is daily polishing; dassaha is burial by increments, each sin another handful of earth over the light."},{"t":"One man can doom a people","d":"Thamud fell by its wretchedest volunteer, and a community that does not restrain its worst signs its own sentence."},{"t":"Justice without tremor","d":"He does not fear its consequence: divine punishment answers to no review board, a closing line of absolute sovereignty."}],"heart":["Ash-Shams recited slowly makes the reciter feel the size of his own interior. Heaven does not swear seven oaths over kingdoms or armies; it swears them over the nafs, the soul, his soul, and then hands down the only success and failure that will outlive the sun it opened with. The two verbs stay with him for days: polish or bury. Every prayer polishes. Every hidden sin is a handful of soil.","The Thamud ending then moves the lesson from the private to the shared: one wretched man, one camel, one city flattened. The reciter learns that souls are buried socially too, by the cheer of crowds and the silence of friends, and he leaves the surah with a doubled resolve, to guard the light in his own chest, and never to be, in any gathering, the voice that rises for the wrong."],"passages":[{"ref":"91:7","why":"By the soul and the One who proportioned it: the seventh oath lands on you, stop and feel its weight."},{"ref":"91:9","why":"He has succeeded who purifies it: the Quran’s definition of winning, six words long."},{"ref":"91:13","why":"The she-camel of Allah and her drink: one prophet’s plea before a city chose its own leveling."}],"connections":[{"to":92,"why":"Wal-layl continues the oath and the verdict, striving scattered between the giver who guards himself and the miser who denies."},{"to":87,"why":"Prescribed together by the Prophet ﷺ for Mu’adh as prayer-length surahs, and both define success as tazkiyah, purification."}],"virtue":{"text":"The soundly established honor of ash-Shams is prophetic prescription: the Prophet ﷺ told Mu’adh, when he prayed too long with the people, why did you not pray with sabbihisma rabbika al-a’la, wash-shamsi wa-duhaha, and wal-layli idha yaghsha. He ﷺ chose it as a measure for congregational prayer, complete nourishment at a mercy’s length; no separate reward report is needed.","src":"Bukhari 705; Muslim 465","level":"sunnah"}},
/* 92 Al-Layl, deep, 21 ayat */
92:{"n":92,"depth":"deep","context":["Al-Layl came down in Makkah in the early years of the message, in the same season as its sister oath-surahs, when revelation still arrived as short bursts of rhythm meant to be carried in the memory of a small, pressured community. Makkah at that hour was a city where wealth decided worth: a man was measured by what he held, and the poor believer was treated as proof against his own religion. Into that market logic the surah dropped a different accounting, two hands moving in two directions, one giving and one gripping, and two roads being smoothed under two kinds of feet.","Classical commentators, Ibn Kathir among them, record that many early authorities read its closing verses in the light of Abu Bakr, who spent his wealth buying tortured slaves like Bilal out of their chains, seeking no favor and expecting no repayment, only the face of his Lord Most High. Whether or not one insists on that occasion, the surah lived in the community as its portrait of the purified giver. The Prophet ﷺ also named it among the surahs an imam should choose when leading people, short enough for the weak, deep enough for anyone."],"name_story":"The surah is named for its first oath, wal-layli idha yaghsha, by the night when it covers over. In the hadith collections and the earliest codices it is simply Al-Layl, The Night, cited by its opening words. No other name is soundly attached to it.","movements":[{"range":"1-4","h":"Oaths over a divided race","note":"Night, day, and the creation of male and female are called as witnesses to one verdict: human striving runs in opposite directions, and no two lives are spending themselves on the same thing."},{"range":"5-11","h":"Two paths, each made easy","note":"The one who gives, guards himself, and trusts the best promise is eased toward ease; the one who hoards, feels self-sufficient, and calls the promise a lie is eased toward hardship, and his wealth will not descend the cliff with him."},{"range":"12-16","h":"Guidance, warning, and the fire","note":"Guidance is Allah’s to give, the last life and the first are His, and the blazing fire ahead is entered only by the most wretched, the one who denied and turned away."},{"range":"17-21","h":"Giving only for His face","note":"The god-fearing one who gives his wealth to be purified, owing no one and collecting from no one, wanting only the face of his Lord Most High, is promised the last word of the surah: he will be satisfied."}],"themes":[{"t":"Giving against gripping","d":"The surah reduces every biography to the motion of a hand. Generosity joined to faith is one road; hoarding joined to denial is the other, and each road runs downhill in its own direction."},{"t":"Ease follows direction","d":"Allah does not only judge the traveler, He smooths the road the traveler chose. Fa-sanuyassiruhu, We will ease him: obedience becomes lighter with practice, and so does refusal."},{"t":"Wealth cannot ransom","d":"At the moment of falling, ma yughni anhu maluhu, his wealth avails him nothing. The surah lets money keep every power except the one that matters."},{"t":"Purity of motive","d":"The praised giver takes no repayment and settles no debts of favor. His giving has one address, the face of his Lord, which is why it purifies him instead of purchasing people."}],"heart":["Recited slowly, Al-Layl performs a quiet audit. It does not ask what you believe; it asks which way your hand was moving this week. The frightening mercy of the surah is verse seven and verse ten said together: whichever direction you lean, heaven greases the slope. Every generous act is making the next one easier, and every refusal is doing the same. A person reading this at night begins to feel his habits not as isolated choices but as a road being paved under him while he walks, and he checks, urgently, where the road is pointed.","Then the ending turns the audit into a promise. Wa lasawfa yarda, and he will surely be satisfied: the giver who wanted only His face is not told he will be rich or safe, he is told he will be content, which is the thing the hoarder was buying all along and never received. The surah closes by handing the poorest sincere giver the only prize the wealthy denier ever wanted."],"passages":[{"ref":"92:7","why":"Stop on the promise that obedience is made easy for the one who begins it, and feel how mercy works on the road itself."},{"ref":"92:11","why":"One verse ends the oldest illusion: wealth stays at the top of the cliff when its owner goes over."},{"ref":"92:20","why":"The purest sentence of motive in the Quran: giving only to seek the face of his Lord, the Most High."},{"ref":"92:21","why":"The surah’s last word, satisfaction, is the wage no market in Makkah could price."}],"connections":[{"to":93,"why":"The night of this surah gives way to the morning brightness of the next, and the mushaf itself moves from the two roads to the consoled traveler on the best of them."},{"to":76,"why":"Al-Insan shows the same motive in action, those who feed the poor saying they want only the face of Allah, no repayment and no thanks."}],"virtue":{"text":"When Mu’adh lengthened the prayer, the Prophet ﷺ told him to lead people instead with short luminous surahs and named this one among them, so Al-Layl carries his ﷺ own recommendation as a surah for congregational prayer.","src":"Bukhari 705, Muslim 465","level":"sunnah"}},
/* 93 Ad-Duha, deep, 11 ayat */
93:{"n":93,"depth":"deep","context":["Ad-Duha descended in Makkah after a wound. Revelation paused: in the sound account, the Prophet ﷺ was unwell and did not rise for night prayer for two or three nights, and a woman of Quraysh taunted him that his shaytan, the spirit she imagined dictated to him, had finally abandoned him. The silence of heaven, which he ﷺ felt more heavily than any mockery, was being used as evidence against him. Then this surah broke the quiet like light over a hill: your Lord has not taken leave of you, and He does not hate you.","For the early community, hunted and few, Ad-Duha became the grammar of consolation. It taught them that a pause is not an abandonment, that the story is read forward, the last better than the first, and that the proof of future care is remembered care: he ﷺ had been an orphan, sheltered; wandering, guided; poor, enriched. Then it turned comfort into command, because in this Book the consoled become consolers: do not crush the orphan, do not turn the asker away, and speak your Lord’s favor out loud."],"name_story":"The surah is named for its opening oath, wad-duha, by the morning brightness, the young strengthening light of forenoon. Early sources cite it by these first words, and no other name is soundly established. The name itself is the message: the dawn after a night that was never permanent.","movements":[{"range":"1-3","h":"The oath and the answer","note":"Morning light and the night when it stills are sworn by, and then the sentence the silence was waiting for: your Lord has not abandoned you, nor does He hate you."},{"range":"4-8","h":"Promise proven by memory","note":"The future is pledged, the last better than the first and a giving that ends in satisfaction, and the pledge is notarized by the past: orphaned and sheltered, wandering and guided, poor and enriched."},{"range":"9-11","h":"Pass the mercy on","note":"The rescued one is commissioned: no crushing the orphan, no repelling the one who asks, and the favor of your Lord, announce it."}],"themes":[{"t":"Silence is not absence","d":"The surah separates the feeling of being left from the fact of being loved. A pause in gifts is not a withdrawal of the Giver."},{"t":"The last better than the first","d":"Time is tilted upward for the believer. Every stage ahead, in this life and beyond it, outweighs the stage being grieved."},{"t":"Remembered care as proof","d":"Three past rescues are presented as evidence for one future promise. The believer’s own biography is a document of what Allah does with him."},{"t":"Comfort becomes duty","d":"The orphan who was sheltered must now shelter; the poor man enriched must now give. Consolation in this surah is a relay, not a possession."},{"t":"Speaking the favor","d":"Gratitude is commanded out loud. Naming blessings is not boasting when the Giver is named with them."}],"heart":["Ad-Duha is the surah for the season when heaven feels quiet. Read slowly, it does something almost physical: verse three lands like a hand on the shoulder of anyone who has secretly wondered whether his distance from Allah means Allah is finished with him. The surah answers the question underneath all our questions, does He still want me, and it answers with an oath by the morning. Then it does what no human comforter can do: it opens your own past as evidence. You were carried before, at moments you now forget; the memory of old rescue is summoned to stand guarantee for coming rescue.","And when the weeping has settled, the surah puts a task in your hands, because it knows that sorrow untied from service curdles. Find the orphan, receive the asker, tell of the favor. The one who walks out of this surah is not merely comforted, he is commissioned, and that is the deepest comfort of all: to be given work is to be told you are still wanted."],"passages":[{"ref":"93:3","why":"This is the verse that ended the silence, and it still ends every reader’s private version of it."},{"ref":"93:5","why":"A promise with no ceiling: your Lord will give you until you are satisfied, a verse the early scholars read all the way into his ﷺ intercession."},{"ref":"93:6","why":"The first of three remembered rescues, where your own history is turned into proof of His care."},{"ref":"93:9","why":"The exact hinge where comfort becomes command, and the consoled one is sent to the orphan."}],"connections":[{"to":94,"why":"Ash-Sharh continues the same consolation in the same breath, so seamlessly that some early scholars read the two surahs as one address."},{"to":92,"why":"Al-Layl ends with the sincere giver satisfied, and Ad-Duha promises the Prophet ﷺ giving until satisfaction, the same word answering across the night."},{"to":108,"why":"Al-Kawthar repeats the pattern in miniature: a taunt against the Prophet ﷺ, answered by a gift, sealed with a promise."}],"virtue":{"text":"No authentic hadith promises a specific reward for reciting Ad-Duha alone, and it needs no certificate: it is the surah with which Allah Himself consoled His Messenger ﷺ, and its virtue is that consolation, open to every reader in grief.","src":"no established report","level":"debated"}},
/* 94 Ash-Sharh, deep, 8 ayat */
94:{"n":94,"depth":"deep","context":["Ash-Sharh came down in Makkah in the same early period as Ad-Duha, and the classical commentators treat it as the second half of one consolation, so tightly joined that the address never changes: still to the Prophet ﷺ, still counting mercies, still steadying him for the road. The pressure of those years was real weight, mockery in the streets, kin turned enemies, the responsibility of a message the world did not want, and the surah names it exactly that, a burden that was breaking the back.","Its work in his ﷺ life was to reframe the past before commanding the future. The chest had already been opened to revelation, the burden already lifted, the name already raised, joined to Allah’s own name in the shahadah, the testimony of faith, and later in every adhan, every call to prayer, until no hour passes on earth without it. On that foundation the surah laid down the law the early believers would live by in Makkah’s worst years: hardship never comes alone, ease is packed inside it."],"name_story":"The surah is named from its first verb, a lam nashrah, did We not open up, so it is called Ash-Sharh, the Opening, and in many books Al-Inshirah, the Expansion of the chest. Both names point to the same gift: a heart made wide enough to carry revelation and injury at once.","movements":[{"range":"1-4","h":"What was already given","note":"Three past-tense mercies are laid out as ground to stand on: the chest opened, the back-breaking burden lifted, and his ﷺ remembrance raised so high that his name is spoken wherever Allah’s is."},{"range":"5-6","h":"The law of hardship and ease","note":"Twice, word for word, the promise: with the hardship is ease, one definite hardship shadowed by ease upon ease, and the preposition is with, not after."},{"range":"7-8","h":"Finish, then stand again","note":"The response to mercy is rhythm: when you are finished, rise to the next labor, and make your Lord the single object of your longing."}],"themes":[{"t":"The opened chest","d":"Sharh as-sadr is the capacity to hold hard truth without breaking. The first gift of prophethood was not ease of circumstances but width of heart."},{"t":"Ease inside hardship","d":"The verse says ma’a, with, not after. Relief is not waiting at the end of the tunnel; it is woven into the tunnel itself, in strength, company, and nearness."},{"t":"A name raised forever","d":"Wa rafa’na laka dhikrak: every adhan, every tashahhud, every salawat on earth is this verse still coming true about the Prophet ﷺ."},{"t":"Rest is a change of labor","d":"Fa-idha faraghta fansab: emptiness invites collapse, so one finished work is answered with another begun, and worship absorbs the hours grief would claim."},{"t":"One direction of desire","d":"Wa ila rabbika farghab: longing is gathered from its scattered objects and aimed at a single target, the Lord who lifted the last burden."}],"heart":["Read slowly, Ash-Sharh works like weight lifted off a carrier who had stopped noticing how bent he was. Its questions are gentle cross-examination: has He not already opened, already lifted, already raised? The reader is made to admit relief that actually happened, because despair survives on forgetting. Then comes the verse people have carried through hospitals and prisons and quiet private ruin: inna ma’a al-usri yusra, truly with the hardship is ease, repeated so the heart hears it twice, once as information and once as oath. The scholars noticed the Arabic holds one hardship between two eases, and the early Muslims said it aloud like a wager: one hardship will never defeat two eases.","The last two verses keep the comfort from going soft. They hand the consoled person a schedule: finish, then stand; work, then worship; and want Him. This surah does not promise an easy life. It promises a carried one."],"passages":[{"ref":"94:4","why":"Pause here during any adhan and realize you are hearing this verse being fulfilled in real time."},{"ref":"94:5","why":"The first saying of the law of ease, worth hearing alone before its echo arrives."},{"ref":"94:6","why":"The repetition that turns a comfort into a certainty, one hardship held between two eases."},{"ref":"94:8","why":"The surah’s final aim: all longing gathered and pointed at your Lord alone."}],"connections":[{"to":93,"why":"Ad-Duha and Ash-Sharh are twin consolations, the first answering abandonment, the second answering exhaustion."},{"to":65,"why":"At-Talaq carries the same law for later, harder years: whoever fears Allah is given a way out, and after difficulty Allah brings ease."}],"virtue":{"text":"No authentic hadith assigns a specific reward to reciting Ash-Sharh, and honesty keeps the record clean: its standing is its content, the surah of the opened chest and the doubled ease, needing no certificate beyond its own eight verses.","src":"no established report","level":"debated"}},
/* 95 At-Tin, deep, 8 ayat */
95:{"n":95,"depth":"deep","context":["At-Tin is Makkan, from the period when Quraysh treated resurrection and judgment as fantasies and treated the believers, many of them poor and unprotected, as worthless. Against that contempt the surah opens with a strange, beautiful map: the fig and the olive, the produce of the lands where Isa, Jesus, peace be upon him, walked; Tur Sinin, the mount where Musa, Moses, peace be upon him, was addressed; and this secure city, Makkah of Muhammad ﷺ. Many classical commentators, Ibn Kathir among them, read the three oaths as three geographies of revelation called to witness one claim about the human being.","The claim is dignity and danger in one line: man is created in the finest mold, and can fall to the lowest of the low, and only faith joined to righteous work holds the height. The Prophet ﷺ loved to recite this surah aloud: al-Bara ibn Azib heard him recite At-Tin in the night prayer on a journey and said he never heard anyone with a more beautiful voice or recitation than his ﷺ."],"name_story":"The surah is named for the fig of its opening oath, wat-tini waz-zaytun, by the fig and the olive, and is cited in the early sources by that first phrase. The homely fruit at the head of a surah about human grandeur is its own lesson: Allah swears by small nourishing things on the way to naming the finest of His creations.","movements":[{"range":"1-3","h":"Three lands under oath","note":"Fig and olive, Sinai, and the secure city: the landscape of prophethood itself, from Isa to Musa to Muhammad ﷺ, peace be upon them, is sworn by before the verdict on man is read."},{"range":"4-6","h":"Finest mold, lowest fall","note":"The human being is created in ahsan taqwim, the best of stature, then returned to the lowest of the low, except those who believe and do righteous deeds, whose wage never runs out."},{"range":"7-8","h":"The question that ends denial","note":"After such design, what can still call the recompense a lie, and the surah closes on a question meant to be answered: is not Allah the most just of judges."}],"themes":[{"t":"Dignity by design","d":"Ahsan taqwim is a statement about every human being before it is a statement about any believer: upright form, seeing heart, entrusted mind."},{"t":"Faith preserves the form","d":"The exception clause is the whole hinge: belief and righteous work are what keep the finest mold from the lowest fall, because a gift unthanked becomes a weight."},{"t":"One line of prophets","d":"Fig, olive, Sinai, Makkah: the surah quietly asserts that the message of Muhammad ﷺ stands in the same chain as Musa and Isa, peace be upon them."},{"t":"Judgment follows craftsmanship","d":"A being made with such care will be asked what he did with himself. The final question, is not Allah the most just of judges, turns creation itself into the argument for the Day."}],"heart":["At-Tin read slowly restores two things our age strips away at once: worth and accountability. First it hands you your dignity, not earned, but built in, ahsan taqwim, the finest mold, so the reader stands a little straighter. Then it shows the trapdoor, asfala safilin, the lowest of the low, and the reader understands that human beings are not fixed creatures but trajectories, and that the same person can be higher than angels or lower than instinct depending on what he does with faith. The exception clause becomes the most practical sentence in the surah: believe, and work, and the height holds.","The last verse is a question, and the sunnah of the early Muslims was to answer questions like it aloud. Is not Allah the most just of judges? The reader who says yes with his whole chest, bala, has just accepted the Day of Judgment not as a threat but as the final proof that his life, wronged or ignored by everyone else, was never unwatched."],"passages":[{"ref":"95:4","why":"Hear the Creator’s own estimate of the human form and stand up straighter under it."},{"ref":"95:6","why":"The exception that saves the surah from despair: faith and work, and a wage that never diminishes."},{"ref":"95:8","why":"A closing question addressed to you, meant to be answered: is not Allah the most just of judges."}],"connections":[{"to":103,"why":"Al-Asr carries the identical rescue clause, all humanity in loss except those who believe and do righteous deeds, the Quran’s repeated escape route."},{"to":96,"why":"Al-Alaq continues the story of the finest mold at its humblest beginning, man created from a clinging mass, honored by the pen."}],"virtue":{"text":"The Prophet ﷺ recited At-Tin in the Isha prayer on a journey, and al-Bara ibn Azib testified he never heard a voice or recitation more beautiful than his ﷺ that night, so the surah carries a sound memory of his own recitation in prayer.","src":"Bukhari 769, Muslim 464","level":"sunnah"}},
/* 96 Al-Alaq, deep, 19 ayat */
96:{"n":96,"depth":"deep","context":["The first five verses of Al-Alaq are the first Quran ever revealed. In the cave of Hira, in Ramadan, the angel Jibril, Gabriel, came to Muhammad ﷺ, pressed him hard and said, iqra, read. He ﷺ answered, I am not one who reads. Three times the embrace, and then the words that began everything: read in the name of your Lord who created. He ﷺ came down the mountain with his heart pounding and said to Khadijah, zammiluni, wrap me up, and she wrapped him and steadied him with the truest character reference in history: Allah would never disgrace a man like you. The account is in Bukhari from Aishah.","The rest of the surah came later in Makkah, when prayer itself was put under threat. Abu Jahl boasted that if he saw Muhammad ﷺ pray at the Ka’bah he would trample his neck, and in the sound report in Muslim, when he tried, he recoiled from what he alone could see, a trench of fire and wings. So one surah holds both poles of the mission: the first whisper of revelation in a cave, and the open defiance of a tyrant in the sanctuary, with the command that answers every tyrant at its end: prostrate, and draw near."],"name_story":"The surah is named for al-alaq, the clinging mass from which man is created, named in its second verse. It is equally known as Surat Iqra, Read, after its first command, and both names appear in early usage. One name remembers what we are made from; the other remembers what we were made for.","movements":[{"range":"1-5","h":"Read, in your Lord’s name","note":"The first revealed words join the two ends of human existence: created from a clinging mass, and taught by the pen what he never knew, all in the name of the most generous Lord."},{"range":"6-8","h":"The root of tyranny","note":"The diagnosis of every oppressor since: man oversteps when he sees himself as self-sufficient, and the cure is one line, to your Lord is the return."},{"range":"9-14","h":"The man who forbids prayer","note":"A slave of Allah is blocked from praying, and the surah circles the blocker with quiet questions that tighten like a ring: does he not know that Allah sees."},{"range":"15-19","h":"The forelock and the prostration","note":"The lying, sinful forelock will be seized, his gang cannot save him, and the believer is given the final command of the first surah: do not obey him, prostrate, and draw near."}],"themes":[{"t":"Knowledge as first gift","d":"Before any law was revealed, the pen was honored. The religion opened not with a command to fight or even to fast, but to read in His name."},{"t":"In His name or in vain","d":"Iqra bismi rabbik: reading itself is not salvation; the name it is done in decides whether knowledge humbles or inflates."},{"t":"Self-sufficiency breeds transgression","d":"Istaghna, he saw himself as needing no one: the surah locates tyranny not in power but in the illusion of independence from Allah."},{"t":"Allah sees","d":"A lam ya’lam bi-anna Allaha yara: one question is the whole deterrent. Every hidden cruelty and every hidden prayer happen in full view."},{"t":"Prostration as nearness","d":"Usjud waqtarib, prostrate and draw near: the lowest posture of the body is the closest position of the soul, and no tyrant can stand between a forehead and the ground."}],"heart":["To recite Al-Alaq slowly is to kneel at the source of the river. These are the syllables that broke the silence between heaven and earth after centuries, and they were addressed to an unlettered man ﷺ so that no reader could ever say the Book belongs to the credentialed. The surah tells you what you are, a clinging mass, and what you carry, taught knowledge you did not invent, and holds the two truths together so that neither despair nor arrogance survives. Then it walks you into the psychology of arrogance, istighna, the moment a person feels he no longer needs, and you recognize the moment, because you have had it, in health, in salary, in reputation.","The ending is one of the most intimate commands in the Quran. Kalla, do not obey him, and then: prostrate, and draw near. Whoever reads this surah and then places his forehead on the floor has completed its meaning with his body, and the Prophet ﷺ said the servant is nearest to his Lord while prostrating. The first surah revealed ends by showing where the whole religion was always heading: down to the ground, and therefore near."],"passages":[{"ref":"96:1","why":"This is where the Quran began: hear the first verse ever revealed as if the cave were yours."},{"ref":"96:14","why":"One question to carry through every private moment: does he not know that Allah sees."},{"ref":"96:19","why":"The final verse is a verse of prostration, and the sunnah is to bow down here, completing the recitation with your forehead."}],"connections":[{"to":97,"why":"Al-Qadr magnifies the very night these first verses descended, the surah of the event following the surah of the words."},{"to":68,"why":"Al-Qalam, among the earliest revelations, swears by the pen this surah honored, and defends the man ﷺ the pen was sent to."}],"virtue":{"text":"The surah ends with a prostration of recitation: Abu Hurairah said, we prostrated with the Prophet ﷺ in Iqra bismi rabbika and in Al-Inshiqaq, so the reciter bows at its last verse following his ﷺ example.","src":"Muslim 578","level":"sunnah"}},
/* 97 Al-Qadr, deep, 5 ayat */
97:{"n":97,"depth":"deep","context":["Al-Qadr is held by most scholars to be Makkan, though some said Madinan, and it descended to magnify a night the world could not see. Ibn Abbas explained in sound reports that the Quran was sent down in one descent to the lowest heaven on Laylat al-Qadr, the Night of Decree, and from there came to the Prophet ﷺ in portions across twenty three years, beginning in Hira. So this surah is the Quran telling the story of its own arrival: We sent it down in the Night of Decree.","In the life of the Prophet ﷺ and his community the surah turned one night of Ramadan into the axis of the year. He ﷺ would seek Laylat al-Qadr in the last ten nights, retreating in i’tikaf, seclusion in the mosque, tightening his waist-wrapper, waking his family, and he promised that whoever stands that night in faith and hope of reward is forgiven his past sins. An empire of devotion, millions awake before dawn every Ramadan, still runs on these five verses."],"name_story":"The surah is named for Laylat al-Qadr, the Night of Decree, which it names three times in five verses. Qadr carries two meanings the scholars loved together: decree, because the year’s appointments are handed down in it, and worth, because one such night outweighs a thousand months.","movements":[{"range":"1-1","h":"The sending down","note":"Allah Himself announces the event in the royal We: truly We sent it down in the Night of Decree, the Book and the night ennobling each other."},{"range":"2-3","h":"Worth beyond counting","note":"The rhetorical drumbeat, what will make you grasp what that night is, then the exchange rate of heaven: better than a thousand months."},{"range":"4-5","h":"Angels until the dawn","note":"The angels and the Ruh, the Spirit Jibril, descend with every decree by their Lord’s leave, and the night is peace itself until the rising of dawn."}],"themes":[{"t":"The Quran honors its night","d":"The night is great because of what descended in it. Value in this surah flows from revelation, a quiet argument that nothing dignifies time like the presence of Allah’s word."},{"t":"One night, a thousand months","d":"More than eighty three years of worship in a single night: the surah breaks the tyranny of short lifespans and gives small communities a way to outweigh centuries."},{"t":"A crowded, descending sky","d":"Tanazzalu al-mala’ikatu war-ruh: the night is not empty quiet but heavy traffic, angels descending with every affair that the coming year will carry."},{"t":"Peace until dawn","d":"Salamun hiya: the night’s very substance is peace, safety written over the worshippers until the light rises, a taste of the greeting of Paradise."}],"heart":["Al-Qadr recited slowly rearranges a person’s mathematics. We count value in years and output; the surah counts it in nearness and descent, and calmly informs us that one night can outweigh a thousand months, which is to say that a life is not measured by its length but by its moments of contact with Allah. For the reciter this is almost unbearable hope: whatever has been wasted, a single night remains capable of outweighing it. The image of the sky opening, angels and the Spirit coming down rank on rank with the decrees of the year, turns the last ten nights of Ramadan from a custom into a countdown.","And the surah ends on the word the heart was thirsty for without knowing it: salam, peace, stretched until dawn. Whoever has stood one true Laylat al-Qadr knows the verse is not a metaphor. There is a stillness in that night that feels less like silence and more like a greeting."],"passages":[{"ref":"97:1","why":"The Quran narrates its own descent: hear the Book speak of the night it entered the world."},{"ref":"97:3","why":"Stop on the exchange rate that makes one night outweigh eighty three years, and let it reprice your time."},{"ref":"97:5","why":"The closing word is peace until dawn, the verse to hold in the last hour of a Ramadan night."}],"connections":[{"to":96,"why":"Al-Alaq carries the first words revealed; Al-Qadr magnifies the night that carried them down."},{"to":44,"why":"Ad-Dukhan opens with the same event, a blessed night in which every wise affair is made distinct, the two surahs describing one descent."}],"virtue":{"text":"No sound hadith assigns a special reward to reciting this surah a set number of times; such reports are not authentic. The established virtue belongs to the night it names: whoever stands Laylat al-Qadr in faith and hope of reward is forgiven his past sins.","src":"for the night itself, Bukhari 1901; no sound recitation-report","level":"debated"}},
/* 98 Al-Bayyinah, deep, 8 ayat */
98:{"n":98,"depth":"deep","context":["Al-Bayyinah is counted Madinan by most scholars, though a minority said Makkan, and it reads like a settling of accounts at the crossroads of religions. It addresses the People of the Book, Jews and Christians, and the idolaters together, and states the hard historical fact: they would not leave what they were on until the clear proof came, a messenger from Allah ﷺ reciting purified pages. Proof arrived, and then the painful irony the surah records: the People of the Book divided not before knowledge came but after it.","The surah holds a tender place in the Prophet’s ﷺ Madinah. He called Ubayy ibn Ka’b, the master reciter of the Ansar, and said: Allah has commanded me to recite to you Lam yakun, this very surah. Ubayy asked, did He name me? He named you, said the Prophet ﷺ, and Ubayy wept. The community learned two things at once: how high a single believer can rank in the knowledge of Allah, and how weighty this surah must be, chosen by name for such a recital."],"name_story":"The surah is named for al-bayyinah, the clear proof, in its first verse: the messenger ﷺ himself, reciting purified pages. It is also cited as Lam Yakun from its opening words, and some early scholars called it Surat al-Qayyimah, from the upright religion it defines, several names for one argument.","movements":[{"range":"1-3","h":"The clear proof arrives","note":"Disbelievers of both camps would not leave off until the proof came: a messenger from Allah ﷺ reciting purified pages containing upright writings."},{"range":"4-5","h":"Splitting after the clear core","note":"The People of the Book split only after clarity came, though all they were commanded was the simple core: worship Allah with pure sincerity, establish the prayer, give the zakah, the purifying alms, and that is the upright religion."},{"range":"6-8","h":"Worst and best of creation","note":"Two endings stand facing each other: the fire of Jahannam forever for those who refuse after proof, and Gardens of Eden for those who believe and work, the best of creation, their Lord pleased with them and they with Him."}],"themes":[{"t":"Proof precedes accountability","d":"Allah does not condemn in the dark. The surah insists that judgment falls only after bayyinah, evidence so clear it leaves refusal without excuse."},{"t":"The simple core of religion","d":"Verse five compresses the entire law into sincerity, prayer, and zakah. The commands were never complicated; hearts were."},{"t":"Splitting after knowledge","d":"The sharpest tragedy in the surah: division caused not by ignorance but by pride after clarity, a warning aimed forward at this ummah too."},{"t":"Best of creation","d":"Khayru al-bariyyah: faith joined to works raises human beings above every created thing, an astonishing title handed to ordinary believers."},{"t":"Mutual pleasure","d":"Radiya Allahu anhum wa radu anhu: the final wage is not gardens but reciprocal contentment, Allah pleased with them and they pleased with Him, for whoever feared his Lord."}],"heart":["Al-Bayyinah slows the reciter down at verse five and asks an uncomfortable question: if the religion’s core is this simple, sincere worship, prayer, zakah, what is all my complication about? The surah diagnoses the disease of religious people in every age, dividing after knowledge, arguing past clarity, and it quietly relocates the problem from the head to the heart. Mukhlisina lahu ad-din, making the religion purely His: the reader begins to audit his own worship for hidden shareholders, habit, reputation, family expectation, and the surah scrubs them out one by one.","Then it lifts the ceiling. The best of creation is not a rank reserved for prophets; it is written over whoever believes and works righteousness. And the final verse names the wage above all wages, His pleasure and yours meeting, then folds it into a condition of four words: dhalika liman khashiya rabbah, that is for whoever feared his Lord. Awe, it turns out, is the door to mutual delight."],"passages":[{"ref":"98:5","why":"The whole religion in one verse: sincerity, prayer, zakah, worth memorizing as a personal creed."},{"ref":"98:7","why":"Hear the title Allah gives to believers who work: the best of creation."},{"ref":"98:8","why":"Stop on the highest wage in the Book, Allah pleased with them and they with Him, and its single condition, fear of the Lord."}],"connections":[{"to":109,"why":"Al-Kafirun draws in six verses the same clean line this surah draws in eight: worship purified of every mixture, with no bargaining."},{"to":99,"why":"Az-Zalzalah follows in the mushaf as the courtroom where the recompense promised here is weighed out atom by atom."}],"virtue":{"text":"The Prophet ﷺ said to Ubayy ibn Ka’b: Allah has commanded me to recite this surah to you, and when Ubayy learned that Allah had named him, he wept. A surah Allah singled out for such a recital carries its honor in that account.","src":"Bukhari 4959, Muslim 799","level":"sunnah"}},
/* 99 Az-Zalzalah, deep, 8 ayat */
99:{"n":99,"depth":"deep","context":["Az-Zalzalah is commonly counted Madinan in the transmitted lists, though its short hammering cadence made others hold it Makkan, and the scholars record the difference honestly. Its subject needs no dating: the final earthquake, the earth emptying her burdens, the dead and the buried secrets together, and mankind surfacing in scattered groups to be shown, not told about, their deeds.","One sound moment ties it to the Prophet’s ﷺ teaching. Asked about donkeys, whether any revelation covered them, he ﷺ answered that nothing had come down about them except this single, all-embracing verse: whoever does an atom’s weight of good will see it, and whoever does an atom’s weight of evil will see it. He called it al-ayah al-fadhdhah al-jami’ah, the unique, comprehensive verse, a complete law of moral accounting in two lines, and the early community weighed their smallest acts against it."],"name_story":"The surah is named for az-zalzalah, the violent shaking of its first verse, when the earth is convulsed with her true convulsion. Some books write the title Az-Zilzal, the Earthquake itself; both forms are early, and both name the surah after the sound of its opening.","movements":[{"range":"1-3","h":"The earth convulses and empties","note":"The final quake is the earth’s own, long appointed, and she throws out her burdens, the buried dead and the buried truths, while man asks the last confused question: what is wrong with her."},{"range":"4-5","h":"The earth testifies","note":"That day she tells her news, every deed done on her back, because her Lord has inspired her, the silent witness under our feet finally given speech."},{"range":"6-8","h":"Atoms on the scale","note":"Mankind proceeds in separated crowds to be shown their deeds, and the surah closes with the comprehensive law: an atom’s weight of good is seen, an atom’s weight of evil is seen."}],"themes":[{"t":"The earth as witness","d":"The ground that hosted every secret act is given a voice. Nothing was done nowhere; every deed had a floor, and the floor will speak."},{"t":"Nothing is too small","d":"Mithqala dharrah, the weight of a speck of dust: the surah abolishes the category of deeds that do not count, in both directions."},{"t":"Deeds shown, not summarized","d":"Liyuraw a’malahum, that they may be shown their deeds: the Day is not a verdict read at a distance but an exhibition each soul walks through."},{"t":"The end of concealment","d":"Burdens thrown out, news told, atoms weighed: the surah is one long unveiling, and its terror or comfort depends entirely on what was hidden."}],"heart":["Az-Zalzalah recited slowly makes the floor under the reciter feel briefly alive, because it is: the surah says the ground you are sitting on is a witness scheduled to testify. What that does to a heart is very precise. Sins one had filed away as too small to matter, and kindnesses one had dismissed as too small to bother with, both walk back into the ledger, because the unit of account here is the dharrah, the atom, the dust-speck in a sunbeam. The Prophet ﷺ told the Companions to guard against the fire even with half a date given in charity, and this surah is the mathematics behind that counsel.","The mercy inside the terror is the symmetry of the last two verses. The same law that guarantees no evil is lost guarantees no good is lost either. The smile, the moved stone, the swallowed retort, the two quiet rak’ahs, prayer units, at night: all of it is seen. For the discouraged doer of small good deeds, this is one of the most consoling passages in the Quran."],"passages":[{"ref":"99:4","why":"The verse where the earth herself begins to speak: hear the ground turn witness."},{"ref":"99:7","why":"The verse the Prophet ﷺ called uniquely comprehensive: an atom’s weight of good, seen."},{"ref":"99:8","why":"Its mirror and warning: an atom’s weight of evil, seen, the end of the category called minor."}],"connections":[{"to":101,"why":"Al-Qari’ah continues the same Day: the atoms counted here are weighed there, and the scales decide the two homes."},{"to":100,"why":"Al-Adiyat ends where this surah lives, with graves overturned and chests unsealed before a Lord fully aware."}],"virtue":{"text":"The famous report that Az-Zalzalah equals half the Quran is transmitted with a weak chain, and its grade is debated among the scholars, so it should not be taught as established. What is sound is the Prophet’s ﷺ praise of its seventh and eighth verses as the unique, comprehensive verse on recompense.","src":"Tirmidhi 2893, graded weak; the comprehensive verse, Bukhari 2371","level":"debated"}},
/* 100 Al-Adiyat, deep, 11 ayat */
100:{"n":100,"depth":"deep","context":["Al-Adiyat is Makkan in the reckoning of the majority, from the years when the Quran was training its first listeners with images their world already loved. Nothing stirred an Arab audience like horses, and the surah opens with a cavalry raid in five strokes of sound: mares panting, hooves striking sparks in the dark, the charge at dawn, the trail of dust, the plunge into the middle of the enemy. Then the oath lands its verdict somewhere no one expected: not on the enemy, but on man himself.","The word chosen is kanud, deeply ungrateful, and the classical commentators unpack it as the one who counts misfortunes and forgets gifts. In a city of traders the next line cut deeper: his love of wealth is shadid, intense, violent. The early community heard the contrast the surah paints without stating: the horse spends itself utterly for a master who only feeds it, while man withholds himself from the Master who gave him everything, and the surah walks that ingratitude forward to the morning the graves are poured out."],"name_story":"The surah is named for al-adiyat, the charging steeds of its first oath, the raiding mares heard panting before they are seen. Early sources cite it by this first word, and no other name is soundly attached. Even its name gallops.","movements":[{"range":"1-5","h":"The dawn raid","note":"Five oath-verses paint the raid in pure sound and motion, panting breath, struck sparks, dawn charge, stirred dust, the plunge into the midst, loyalty and fury spent for a human master."},{"range":"6-8","h":"The verdict on man","note":"Against the horse’s spent devotion stands the rider: deeply ungrateful to his Lord, himself a witness to it, and fierce in his love of wealth."},{"range":"9-11","h":"Graves emptied, chests exposed","note":"The cure for ingratitude is one question: does he not know that when what is in the graves is poured out and what is in the chests is gathered, their Lord that Day is fully aware of them."}],"themes":[{"t":"The loyal beast, the disloyal man","d":"The horse gives everything for oats and a stable; man hoards himself against the Lord who made him. The surah lets an animal shame its rider."},{"t":"Kanud, engrained ingratitude","d":"The heart that tallies every hardship and files every blessing under deserved: the surah names the accounting error at the root of unbelief."},{"t":"Wealth-love as diagnosis","d":"Love of good things is not condemned as feeling but exposed as fever, shadid, strong enough to shape a whole life’s direction."},{"t":"What chests conceal","d":"The surah ends not at opened graves but at opened hearts: hussila ma fis-sudur, the harvest of what chests hid, the deeper of the two exhumations."}],"heart":["Read slowly, Al-Adiyat starts in the ears and ends in the conscience. The opening verses are onomatopoeia you can feel, dabhan, qadhan, breath and sparks, and then the surah reins the whole cavalry to a halt in front of a mirror. Inna al-insana li-rabbihi la-kanud: the reader is invited to check his own ledger and finds, honestly, that he remembers his losses in detail and his gifts in general. That is kanud, and recognizing it in oneself is the surah doing its work.","The last movement quietly relocates the Day of Judgment. We imagine it as the emptying of graves, and the surah grants that, then goes further inward: the gathering of what the chests contained. Motives, grudges, hidden loves, the reasons under the deeds. The reciter who understands verse ten begins that same night to clean not just his record but his interior, because both are scheduled for daylight."],"passages":[{"ref":"100:6","why":"The oath’s landing point: the verdict of ingratitude, worth hearing with your own accounts in mind."},{"ref":"100:8","why":"One verse holds the fever of wealth-love up to the light: is its grip this strong on me."},{"ref":"100:10","why":"The deeper resurrection: not the graves but the chests, when what hearts concealed is gathered out."}],"connections":[{"to":99,"why":"Az-Zalzalah gives the same Day its scales: the chests unsealed here are weighed there, atom by atom."},{"to":102,"why":"At-Takathur follows the same fierce wealth-love to its terminus, the visit to the graves this surah sees poured out."}],"virtue":{"text":"No authentic hadith assigns a specific reward to reciting Al-Adiyat, and it needs no certificate: its virtue is the honesty of its mirror, an oath of Allah over the state of the human heart before its Lord.","src":"no established report","level":"debated"}},
/* 101 Al-Qari'ah, deep, 11 ayat */
101:{"n":101,"depth":"deep","context":["Al-Qari’ah is early Makkan, from the first years when the Quran’s task was to break open a closed imagination. Quraysh could not conceive of the world ending or of standing before Allah, so surahs like this one arrived as controlled detonations, short, rhythmic, unforgettable. It opens with a name of the Last Day never used before, al-qari’ah, the striking knocker, repeated like a fist on a door, then twice asks the question that humbles all claimed knowledge: what will make you know what it is.","For the Prophet’s ﷺ first listeners, the surah replaced their two anchors of permanence, crowds and mountains, with images of weightlessness: mankind like moths scattered around light, mountains like carded wool drifting apart. Then it introduced the instrument that would shape Muslim conscience forever, al-mawazin, the scales, and taught the community that eternity splits along a line as fine as a weight tipping: heavy, a pleasing life; light, a mother named the abyss."],"name_story":"The surah is named for al-qari’ah, the Striker, the calamity that knocks and pounds, one of the proper names of the Day of Resurrection. The surah takes its title from the Day itself, and repeats the name three times at its head the way a knock repeats.","movements":[{"range":"1-3","h":"A name repeated like a knock","note":"Al-Qari’ah, what is al-Qari’ah, and what will make you know what al-Qari’ah is: the Day is introduced by name, question, and awed refusal to be summarized."},{"range":"4-5","h":"The world comes apart","note":"The two symbols of solidity dissolve: mankind like scattered moths around a flame, and the mountains like loosened, carded wool."},{"range":"6-9","h":"Two weights, two homes","note":"The scales decide everything: whoever’s weights are heavy enters a well-pleasing life, and whoever’s are light, his mother is hawiyah, the abyss that receives him."},{"range":"10-11","h":"The abyss named","note":"The surah’s question returns one last time, what will make you know what she is, and answers with two words: a raging fire."}],"themes":[{"t":"The Day has names","d":"Al-Qari’ah joins al-Haqqah and al-Ghashiyah in the Quran’s roll of names for the Day, each name a different sound of its arrival; this one is the knock."},{"t":"Solidity is temporary","d":"Crowds scatter like moths, mountains drift like wool. Everything that looks permanent is on loan, including the ground under the proud."},{"t":"The scales decide","d":"Mawazin, weighings: deeds have mass, and eternity turns on which pan drops, a physics of justice no one escapes and no one can bribe."},{"t":"A mother called the abyss","d":"Ummuhu hawiyah: the fire is named his mother, the terrible tenderness of a refuge that consumes, for the one who made nothing else his refuge."}],"heart":["Al-Qari’ah works on the reciter through sound before sense: the knocking name, the rhymes that fall like strokes, the question repeated until the listener admits he does not know. Slowly read, it performs a strange reversal of scale. The things that dominate your week, crowds of people and immovable circumstances, are shown scattering like moths and drifting like wool, while the things you dismiss as weightless, a small sincerity, a private sin, are revealed as the only objects with mass. The surah is a recalibration of what is heavy.","Its most piercing line is the gentlest-sounding one: fa-ummuhu hawiyah, his mother is the abyss. The scholars heard in it the image of a child running to be held, and finding that the only embrace left is the fall. Whoever recites that verse slowly finds himself checking, honestly, what he runs to when he is afraid, because that, in the end, is his mother or his abyss."],"passages":[{"ref":"101:4","why":"The Day’s first image: all of mankind, every rank and tribe, scattered like moths around light."},{"ref":"101:6","why":"The verse of the heavy scale: hear the only wealth that keeps its weight on that Day."},{"ref":"101:9","why":"The most quietly devastating verse in the surah: the abyss as a mother’s lap for the one whose weights were light."}],"connections":[{"to":99,"why":"Az-Zalzalah supplies the atoms, this surah supplies the scales: two halves of one courtroom."},{"to":69,"why":"Al-Haqqah opens with the same architecture, a name of the Day, the question, and the refrain, what will make you know."}],"virtue":{"text":"No authentic hadith singles out Al-Qari’ah with a recitation reward, and it asks for none: it is one of the surahs that made the early Muslims’ hair grey with the vividness of the Day, and that vividness is its gift to the reciter.","src":"no established report","level":"debated"}},
/* 102 At-Takathur, deep, 8 ayat */
102:{"n":102,"depth":"deep","context":["At-Takathur is Makkan, revealed into a culture that kept score. Tribes boasted in numbers, of men, camels, gold, and the commentators relate that clans would even count their dead to win an argument, walking to the graveyard to finish the tally. The surah’s first verse seizes that whole way of being alive in one word, alhakum, it has distracted you, and its second verse follows the distraction to the only place it ever ends: hatta zurtum al-maqabir, until you visit the graves.","The Prophet ﷺ himself gave the surah its sharpest commentary. He recited Alhakum at-takathur and said: the son of Adam says, my wealth, my wealth, and do you own of your wealth anything except what you ate and used up, what you wore and wore out, and what you gave in charity and sent ahead? Everything else, he ﷺ taught, is left for others. The early community heard this surah as an intervention, a hand on the shoulder of a man running a race in the wrong direction."],"name_story":"The surah is named for at-takathur, rivalry in accumulation, the competition to have more that its first verse indicts. Some early sources cite it as Alhakum, after its opening word, so that even its titles remember the two poles: the pile, and the distraction.","movements":[{"range":"1-2","h":"Distraction unto the graves","note":"The race for more consumes life until the grave visit, and the word visit is its own sermon: the grave too is a stop, not a home, with a journey after it."},{"range":"3-4","h":"The doubled warning","note":"Kalla, no indeed, you will come to know, then again, kalla, you will come to know: certainty postponed is announced twice, like two tolls of one bell."},{"range":"5-7","h":"From knowing to seeing","note":"If only you knew with the knowledge of certainty; you will surely see the blaze, then see it with the very eye of certainty, knowledge ripening into sight."},{"range":"8-8","h":"The audit of delights","note":"Then, on that Day, you will surely be asked about an-na’im, the delights: cool water, safety, health, every comfort itemized and questioned."}],"themes":[{"t":"More as anesthesia","d":"Takathur numbs: the pursuit of increase is not condemned here for greed alone but for what it prevents, attention to why we are alive."},{"t":"Graves are visited, not kept","d":"Zurtum, you visited: the mildest word in the surah carries its heaviest news, that death is a doorway with something on the other side."},{"t":"Degrees of certainty","d":"Ilm al-yaqin, knowledge of certainty, becomes ayn al-yaqin, the eye of certainty: what is doubted now will be seen then, and the surah counts down between them."},{"t":"Delights will be itemized","d":"An-na’im is not a vague word: shade, water, health, safety. The comforts we never counted are counted, and gratitude is the only answer sheet."}],"heart":["At-Takathur read slowly is an interruption, and it is meant to be. Its first word walks into the middle of your scrolling, your comparing, your quiet tallying of what others have, and names the whole activity: alhakum, it has distracted you. The reciter feels the aim of the verse move from seventh-century camels to his own screens without a single word needing translation. Then comes the surah’s masterstroke, the word visit. You will not live in the grave, you will pass through it, and everything you piled stays on this side of the door while everything you sent ahead waits on the other.","The final verse changes the reciter’s relationship with ordinary comfort. You will be asked about the delights: so the cold water becomes a question, the safe street becomes a question, the healthy child becomes a question. The honest reader leaves this surah doing the only sane thing its logic allows, turning delights into gratitude and gratitude into giving, converting the pile into provision for the road."],"passages":[{"ref":"102:1","why":"One word, alhakum, names the disease of every acquisitive age including ours."},{"ref":"102:2","why":"Stop on the word visit and hear the grave demoted from destination to doorway."},{"ref":"102:8","why":"The last verse turns every comfort you own into a question you will answer."}],"connections":[{"to":104,"why":"Al-Humazah shows the counter at his worst, wealth counted and recounted as if counting could make him last."},{"to":103,"why":"Al-Asr is the cure sheet that follows in the mushaf: time is the capital being wasted, and the four rescues spend it rightly."}],"virtue":{"text":"Reports promising a set reward for reciting At-Takathur are not authentic and should not be relied on. What is sound is the Prophet’s ﷺ own commentary upon reciting it: the son of Adam claims, my wealth, my wealth, yet truly owns only what he ate, wore out, or gave in charity and sent ahead.","src":"the commentary, Muslim 2958; no sound recitation-report","level":"debated"}},
/* 103 Al-Asr, deep, 3 ayat */
103:{"n":103,"depth":"deep","context":["Al-Asr is Makkan, three verses long, and the tradition remembers it as the surah whose size is inverse to its weight. Imam ash-Shafi’i said that if people reflected deeply on this surah alone, it would suffice them, because it holds a complete map of salvation: the asset, time; the default, loss; and the four-part rescue, faith, righteous work, counseling one another to truth, counseling one another to patience.","It shaped the daily manners of the first generations in a way almost no other surah did. It is soundly related that when two of the Companions of the Prophet ﷺ met, they would not part until one had recited Surat al-Asr to the other, and then one would give the greeting of peace. Farewell itself became a reminder: time is draining, hold to the four ropes. A community that says goodbye with this surah has agreed, twice a day, on what life is for."],"name_story":"The surah is named for its oath, wal-asr, by time, the pressing ages through which every life drains, and the word also names the late afternoon, when the day’s remainder is visibly short. Both senses serve the surah’s point: the light is going, and the account is open.","movements":[{"range":"1-1","h":"The oath of time","note":"Allah swears by time itself, the one asset every human is spending at the same rate, the very thing running out while the verse is heard."},{"range":"2-2","h":"The verdict of loss","note":"Mankind, all of it, is in khusr, loss, capital draining like a merchant selling below cost, the default state of every unexamined life."},{"range":"3-3","h":"The four ropes of rescue","note":"One exception, four strands: those who believe, do righteous deeds, counsel one another to truth, and counsel one another to patience, a rescue no one completes alone."}],"themes":[{"t":"Time as draining capital","d":"The surah frames life as a merchant’s stock being sold every hour whether or not anything is earned; the only question is what the hours are exchanged for."},{"t":"Loss is the default","d":"Not neutrality: loss. Without deliberate faith and work, simply existing costs more than it returns, and the surah says so with an oath."},{"t":"Rescue has four parts","d":"Belief, work, mutual counsel in truth, mutual counsel in patience: inner conviction, outer action, and a community that keeps both alive."},{"t":"Salvation is plural","d":"Tawasaw, they counsel one another: the verbs of rescue are reciprocal. The surah does not describe a saved individual; it describes a saving fellowship."}],"heart":["Al-Asr is short enough to say in one breath and severe enough to reorder a decade. Recited slowly, its structure closes on the reader like an audit: an oath, a verdict, and one narrow exit. The verdict is the hard part to sit with, because it includes everyone by default, the busy, the successful, the well-liked, all in loss, since the asset being spent is time and most of it buys nothing that survives the grave. The reader checks his own ledger against the four conditions and usually finds the first two present in some form and the last two, counseling truth and counseling patience, thin, because they require other people and cost social comfort.","That is the surah’s deepest work: it makes isolation itself feel like a risk. The early Muslims recited it at parting because rescue, in its grammar, is something companions do for each other. Whoever takes these three verses seriously leaves with two resolutions: waste less of the draining asset, and find the people who will tell him the truth and steady his patience until the end."],"passages":[{"ref":"103:1","why":"A one-word oath by the thing you are spending right now, worth a full pause."},{"ref":"103:2","why":"The verdict that includes everyone by default: hear yourself inside the word loss."},{"ref":"103:3","why":"The four ropes of rescue in a single verse, the shortest complete map of salvation in the Quran."}],"connections":[{"to":102,"why":"At-Takathur shows the distraction; Al-Asr prices it: the pile costs time, and time is the capital of the loss."},{"to":95,"why":"At-Tin carries the same exception clause, faith and righteous work, the pair the Quran repeats wherever mankind’s fall is announced."}],"virtue":{"text":"It is soundly related of the Companions that when two of them met, they would not part until one recited Surat al-Asr to the other, then gave the greeting of peace, so the surah carries an authentic practice of the Prophet’s ﷺ community as a seal upon meetings.","src":"at-Tabarani, graded sound by al-Albani, as-Sahihah 2648","level":"sunnah"}},
/* 104 Al-Humazah, deep, 9 ayat */
104:{"n":104,"depth":"deep","context":["Al-Humazah is Makkan, from the years when mockery was Quraysh’s cheapest and most constant weapon against the believers. Some commentators name individuals behind the revelation, al-Akhnas ibn Shariq, Umayyah ibn Khalaf, al-Walid ibn al-Mughirah, but the chains for a specific occasion are not firm, and the surah itself refuses to narrow: waylun li-kulli, woe to every humazah lumazah, every gesture-mocker and word-slanderer, whoever fits the description in any age.","The surah drew the anatomy of a familiar Makkan figure: rich enough to sneer, counting and recounting his wealth, half-believing the pile made him permanent. For the mocked believers, many of them enslaved or poor, it reframed their humiliation completely: the laughter aimed at them was evidence in a case being prepared, and the fire waiting for unrepentant contempt was described with a precision found nowhere else, a fire that climbs to the hearts, the very organ the mockery came from."],"name_story":"The surah is named for al-humazah, the habitual fault-finder who wounds with gesture and glance, paired in its first verse with lumazah, the tongue-slanderer. Some early books also cite it by the fire it unveils, al-Hutamah, the Crusher, so its names hold both the crime and the sentence.","movements":[{"range":"1-2","h":"The mocker and his ledger","note":"Woe is pronounced on every needling mocker and slanderer, and the source of his confidence is named at once: wealth gathered and counted, counted again."},{"range":"3-3","h":"The illusion of permanence","note":"Yahsabu anna malahu akhladah: he half-believes his wealth has made him immortal, the quiet creed underneath every sneer."},{"range":"4-6","h":"Flung into the Crusher","note":"Kalla, by no means: he will be hurled into al-hutamah, and to the question, what will make you know what it is, comes the answer: the kindled fire of Allah."},{"range":"7-9","h":"The fire that reaches hearts","note":"A fire that mounts to the hearts, closing over its people in stretched-out columns: the sentence fitted exactly to the organ where contempt lived."}],"themes":[{"t":"Contempt as a habit","d":"Humazah and lumazah are intensive forms: not a man who once mocked, but a man whose mockery has become his craft and comfort."},{"t":"Counting as false immortality","d":"The recounted pile is a liturgy of self-reassurance. The surah exposes the arithmetic underneath arrogance: he thinks the total is a lifespan."},{"t":"The fire that finds the heart","d":"Tattali’u ala al-af’idah: uniquely in the Quran, this fire is described reaching the hearts, justice tracing the crime to its source."},{"t":"Wealth buys no exemption","d":"Ma aghna anhu maluhu: the currency he trusted is not accepted at the one gate that matters, a refrain this surah shares with its neighbors."}],"heart":["Al-Humazah read slowly forces a double honesty. The first is social: the reciter checks himself for the small tools of the humazah, the raised eyebrow, the imitation of someone’s accent, the message forwarded with a laughing remark, because the surah’s woe is written on the habit, not the century. The second honesty is financial: yahsabu anna malahu akhladah, he supposes his wealth has made him last. Almost no one says that sentence aloud, and almost everyone has felt its warmth, the sense that enough saved, enough owned, is a wall against death. The surah calls the wall a supposition and knocks it through in one syllable, kalla.","Then the fire, and the detail that stays with every attentive reciter: it climbs to the hearts. The heart that looked down on Allah’s servants, the heart that leaned on the pile, is the address the punishment knows. The reader closes this surah gentler with people and looser with money, which is exactly the repentance it was sent to produce."],"passages":[{"ref":"104:1","why":"Hear the woe pronounced on a habit our age has made effortless, mockery at a distance."},{"ref":"104:3","why":"The unspoken creed of accumulation, said aloud once in the Quran so you can recognize it in yourself."},{"ref":"104:7","why":"The most precise sentence in the surah: the fire that knows the way to the hearts."}],"connections":[{"to":102,"why":"At-Takathur diagnoses the counting sickness in a whole society; Al-Humazah shows it concentrated in one condemned figure."},{"to":111,"why":"Al-Masad is the named case study: a real mocker of the Prophet ﷺ whose wealth and earnings availed him nothing."}],"virtue":{"text":"No authentic hadith attaches a specific recitation reward to Al-Humazah, and it needs no certificate: it stands as the Quran’s permanent verdict on wealthy contempt, and its recital is its own admonition.","src":"no established report","level":"debated"}},
/* 105 Al-Fil, deep, 5 ayat */
105:{"n":105,"depth":"deep","context":["Al-Fil looks back at the most famous event in living Makkan memory: the Year of the Elephant, around 570 CE, when Abrahah marched from Yemen with an army led by an elephant to demolish the Ka’bah and redirect Arabia’s pilgrimage to his cathedral in San’a. At the edge of the sanctuary the elephant knelt and would not advance, and Allah sent birds in flights, pelting the army with stones of baked clay until it lay like devoured stalks. The Prophet ﷺ was born in that same year by the well-known accounts, and elders who had witnessed the event still walked Makkah when this surah was recited to them.","That is why the surah opens with a question, a lam tara, have you not seen: it argues from evidence the audience itself owned. Quraysh built prestige on the miracle, calling themselves the people of the House Allah defended, while refusing the Messenger ﷺ sent from that House. Decades later at Hudaybiyyah, when his ﷺ camel knelt and would not advance, he said: the One who restrained the elephant has restrained her, a sound word in Bukhari that shows the event living on in his ﷺ own reading of history."],"name_story":"The surah is named for ashab al-fil, the fellows of the elephant, the invading army remembered by its beast. Arabs dated years by the event itself, Am al-Fil, the Year of the Elephant, so the surah’s name plugs directly into the calendar of its first listeners.","movements":[{"range":"1-2","h":"Have you not seen","note":"The question is addressed to people with living witnesses among them: did your Lord not deal with the elephant’s men, did He not turn their plot into wandering waste."},{"range":"3-5","h":"Birds, stones, straw","note":"Flights of birds, stones of sijjil, baked clay, and an army of conquest left like the chewed stalks of a devoured field: the whole battle in three verses, with no Muslim army on it."}],"themes":[{"t":"The House has a Lord","d":"Abrahah fell to no human defender; Quraysh themselves had fled to the hills. The event proved the Ka’bah’s protection comes from its Lord, not its custodians."},{"t":"Plots turned to waste","d":"Tadlil, sending astray: the scheme was not merely defeated but bewildered, unraveled from inside, the signature of Allah’s dealing with arrogant plans."},{"t":"Small agents, total defeat","d":"Birds against an imperial army: Allah’s deliverance ignores proportion, and the surah trains the weak to stop measuring threats by size."},{"t":"Memory as proof","d":"The surah presents no argument, only a reminder, because the evidence was walking around Makkah: history itself, honestly remembered, testifies for Allah."}],"heart":["Al-Fil recited slowly is a surah for the outnumbered. Its five verses reenact the moment every believer eventually faces in miniature, a force too big to resist advancing on what is sacred, and it answers with the calmest question in the Quran: have you not seen what your Lord did? The reciter is invited to consult his own memory the way Makkah was made to consult its own, and every honest heart finds elephants that knelt, disasters that arrived and inexplicably dissolved. The surah converts remembered rescue into present courage.","It also quietly warns. Quraysh loved this miracle and still refused its meaning, proof that a person can be proud of Allah’s past favors while resisting His present call. The reciter asks himself the harder question: which mercy am I celebrating, and which command am I avoiding?"],"passages":[{"ref":"105:1","why":"The question that turns memory into evidence: have you not seen what your Lord did."},{"ref":"105:3","why":"The moment the sky takes the field: birds in flights against an imperial army."},{"ref":"105:5","why":"The end of all arrogant force in one image, a field of chewed and scattered stalks."}],"connections":[{"to":106,"why":"Quraysh continues the argument so directly that some early authorities read the two surahs as one breath: the rescue of the House obliges worship of its Lord."},{"to":48,"why":"Al-Fath belongs to the day the Prophet ﷺ invoked this event at Hudaybiyyah: the One who restrained the elephant restrained his camel, and a conquest of peace followed."}],"virtue":{"text":"No authentic hadith assigns a recitation reward to Al-Fil, and it needs no certificate: it is a standing monument of Allah’s defense of His House, sound in the community’s memory and cited by the Prophet ﷺ himself at Hudaybiyyah.","src":"no established report; the Hudaybiyyah citation, Bukhari 2731","level":"debated"}},
/* 106 Quraysh, deep, 4 ayat */
106:{"n":106,"depth":"deep","context":["Quraysh is Makkan and reads like an invoice presented to a tribe. The ilaf of Quraysh, their knitted-together security and covenanted trade, rested on their custodianship of the Ka’bah: because Arabia revered the House, the tribe of the House traveled unrobbed where others needed armed escort. On that safety ran the two great caravans, winter south to Yemen, summer north to Sham, greater Syria, and on those caravans ran Makkah’s food, wealth, and pride.","The surah names the whole arrangement and then presents the bill: fal-ya’budu rabba hadha al-bayt, so let them worship the Lord of this House, who fed them against hunger and secured them against fear. Quraysh were consuming the House’s blessings while rejecting the House’s Lord and persecuting His Messenger ﷺ. For the early community the surah distilled worldly wellbeing to its two irreducible elements, food and safety, and taught that both are gifts with a Giver, and the Giver has an address they already knew."],"name_story":"The surah is named for Quraysh, the Prophet’s ﷺ own tribe, the only surah in the Quran titled with a tribe’s name. It is also cited as Li-ilafi Quraysh from its opening phrase, and some reports describe early codices writing it joined closely to Al-Fil, so tightly the two arguments run as one.","movements":[{"range":"1-2","h":"Two caravans under covenant","note":"The knitted security of Quraysh, their winter journey and summer journey, is held up as the visible miracle they lived on every year without wondering who guaranteed the roads."},{"range":"3-4","h":"The invoice of mercy","note":"The conclusion is one command with two receipts: worship the Lord of this House, the One who fed them against hunger and made them safe from fear."}],"themes":[{"t":"Security is provision","d":"The surah pairs food and safety as the twin floors of civilization: markets, journeys, and families all stand on two gifts most people never audit."},{"t":"Gratitude has an address","d":"Rabba hadha al-bayt, the Lord of this House: not the House, not the tribe, not the trade routes. Blessing traced honestly leads to One door."},{"t":"Trade rests on unseen protection","d":"Quraysh thought their treaties and reputation secured the caravans; the surah shows the guarantee was always divine, dispensed through the House they were misusing."},{"t":"Worship is the owed response","d":"Fal-ya’budu, so let them worship: the surah’s only command. Every enjoyed mercy is an unanswered summons until worship answers it."}],"heart":["Quraysh is a small surah that performs a large audit on the reciter. Its method is to take the two blessings so constant they have become invisible, the meal that came without famine and the night that passed without fear, and hold them up as debts. Read slowly, verse four turns any ordinary day inside out: you ate, and you were safe, therefore two receipts are already on the table before you have done anything at all. The heart that absorbs this cannot treat worship as a favor it does Allah; worship becomes the barest honesty about how one is being carried.","There is also a tender specificity in rabba hadha al-bayt, the Lord of this House. Allah names Himself through the place He gave them, as if to say: you know where to find Me; you have circled My House your whole lives. For the reciter, the phrase gathers every qiblah-facing prayer into an answer to this surah’s command."],"passages":[{"ref":"106:3","why":"The surah’s single command, worship aimed at the Lord of the House you already face five times a day."},{"ref":"106:4","why":"Two receipts that cover every ordinary day: fed against hunger, secured against fear."}],"connections":[{"to":105,"why":"Al-Fil shows the rescue of the House; Quraysh presents the obligation the rescue created, two surahs forming one argument."},{"to":14,"why":"Surah Ibrahim carries the ancestor’s prayer, a secure city and provision for its people, which these four verses show fully answered."}],"virtue":{"text":"No authentic hadith singles out Quraysh with a recitation reward; reports of special equivalence for it are not sound. It needs no certificate: it is the Quran’s shortest complete lesson on gratitude for food and safety.","src":"no established report","level":"debated"}},
/* 107 Al-Ma'un, deep, 7 ayat */
107:{"n":107,"depth":"deep","context":["Al-Ma’un is Makkan in the view of most scholars, though some held its later verses came down in Madinah around the hypocrites; the classical books record both. It opens with a question that sounds like an invitation to gossip, ara’ayta, have you seen the one who denies the din, the judgment and the religion, and then gives a description no one expected: not a man arguing philosophy, but a man shoving an orphan and never urging that the poor be fed. Denial, the surah insists, is visible at the dinner table before it is audible in debate.","Then the surah turns and does something even more unsettling for religious people: it pronounces woe upon some who pray, those heedless of their prayer, those who perform to be seen, and those who withhold al-ma’un, the small neighborly things, the pot, the bucket, the hand-tool, the salt, as Ibn Mas’ud and the early commentators explained. For the first community it fused creed, prayer, and kindness into one fabric that cannot be torn along convenient lines."],"name_story":"The surah is named for al-ma’un, the small borrowed helps of neighborly life named in its final verse, the things so minor that refusing them exposes a heart with nothing in it. Some early books cite it as Ara’ayta, have you seen, after its opening word, and some as Surat ad-Din, the surah of the judgment it opens with.","movements":[{"range":"1-3","h":"Denial wears everyday clothes","note":"The one who calls the judgment a lie is identified by conduct: he is the one who pushes the orphan away and does not urge the feeding of the poor."},{"range":"4-5","h":"Woe to some who pray","note":"The Quran’s most feared woe for worshippers: prayer performed but unminded, sahun, hearts absent and duties slack, hollow at the center."},{"range":"6-7","h":"Display without mercy","note":"The portrait completes: worship done for human eyes, and even the bucket and the pot refused, religion inverted into performance minus kindness."}],"themes":[{"t":"Creed shown in conduct","d":"The surah tests belief in judgment not by questioning the tongue but by watching the hands: what a man does with orphans and food is his real theology."},{"t":"The orphan test","d":"Yadu’u al-yatim, he shoves the orphan: the treatment of the person who can repay nothing is the Quran’s recurring measure of a heart."},{"t":"Heedless prayer","d":"An salatihim sahun: not a missed prayer but an unminded one, kept as costume while its center, presence before Allah, has quietly died."},{"t":"Riya, worship for eyes","d":"Yura’un: prayer aimed at human audiences is aimed away from Allah, and the surah lists it beside cruelty, not beside devotion."},{"t":"The smallest generosity as the largest sign","d":"Al-ma’un, the borrowed pot and bucket: a soul that cannot release trifles reveals what all its display was hiding."}],"heart":["Al-Ma’un may be the most uncomfortable seven verses in the Quran for a practicing person, because its woe is aimed inside the mosque. Read slowly, it dismantles the quiet bargain many of us strike, ritual in exchange for exemption from character, and it starts with a scene anyone can picture: an orphan pushed aside by a man certain of his own respectability. The reciter is forced to ask not whether he prays, but where his prayer goes and what it produces; sahun, heedless, is a word that fits comfortable routines precisely.","The surah’s genius is its final word. It does not end with a cosmic image but with kitchenware, al-ma’un, the small things neighbors lend. Heaven, it turns out, watches the smallest transactions for the truth about the largest claims. Whoever finishes this surah honestly will do two things before the day ends: return his prayer to presence, and find one small, unglamorous kindness to complete, because in this surah that is what belief in the Day actually looks like."],"passages":[{"ref":"107:1","why":"The question that redefines denial as something done to orphans before it is said about God."},{"ref":"107:4","why":"The woe every praying person should hear at least once a week, aimed at hollow prayer."},{"ref":"107:7","why":"The last word is a borrowed pot: the smallest kindness as the final test of the biggest claims."}],"connections":[{"to":93,"why":"Ad-Duha commands, do not crush the orphan; Al-Ma’un shows the one who does, the command and its violation facing each other."},{"to":104,"why":"Al-Humazah indicts cruelty of the tongue and the hoard; Al-Ma’un indicts cruelty of the hand and the withheld bucket, two panels of one portrait."}],"virtue":{"text":"No authentic hadith attaches a recitation reward to Al-Ma’un, and it needs no certificate: it is the Quran’s standing definition of religion that has lost its mercy, and reciting it honestly is itself a correction.","src":"no established report","level":"debated"}},
/* 108 Al-Kawthar, deep, 3 ayat */
108:{"n":108,"depth":"deep","context":["Al-Kawthar, the shortest surah in the Quran, carries one of the tenderest revelation accounts. Anas relates that the Prophet ﷺ dozed lightly among his companions, then raised his head smiling. A surah has just been revealed to me, he ﷺ said, and recited Bismillah, then Inna a’taynaka al-kawthar. Do you know what al-Kawthar is? A river my Lord has promised me in Paradise, of abundant good, a basin to which my ummah will come on the Day of Rising. The account is in Muslim.","Behind the surah stands a sound and bitter backdrop: when the Prophet’s ﷺ infant son died, men of Quraysh, al-As ibn Wa’il named among them, called him abtar, cut off, a man without male heirs whose name would end with him. The surah answered the schoolyard cruelty with cosmic arithmetic: We have given you al-Kawthar, the abundance, so the loss they mocked was answered with a river, and the final verse turned the word around forever: your hater, he is the cut-off one."],"name_story":"Al-Kawthar is an intensive form of kathrah, abundance: the river in Paradise, the basin of his ﷺ ummah, and every overflowing good, as the commentators gathered. The surah is named for the gift that answered the taunt, and it is also cited by its opening words, Inna a’taynak.","movements":[{"range":"1-1","h":"The gift announced","note":"Inna a’taynaka, truly We have given you: past tense, already granted, abundance stated as fact before the wound is even mentioned."},{"range":"2-2","h":"The response of the gifted","note":"So pray to your Lord and sacrifice: gratitude given its two oldest forms, worship and offering, aimed at Him alone."},{"range":"3-3","h":"The taunt reversed","note":"Inna shani’aka huwa al-abtar: the one who hates you, he is the one cut off, the insult returned to its sender with the seal of eternity."}],"themes":[{"t":"Abundance measured by heaven","d":"Quraysh counted sons and Muhammad ﷺ had buried his; heaven counted differently and handed him a river. The surah reprices loss with eternal currency."},{"t":"Gratitude as prayer and sacrifice","d":"Fa-salli li-rabbika wanhar: the answer to receiving is giving, worship of the heart and wealth of the hand, both facing one Lord."},{"t":"Insults outlived","d":"The men who coined the taunt survive only as footnotes inside his ﷺ story, while his name is raised in every adhan: the verse fulfilled in plain history."},{"t":"The basin promise","d":"Al-hawd, the basin where his ﷺ ummah will drink on the Day: the surah plants a meeting-place in every reciter’s future."}],"heart":["Al-Kawthar is three verses of medicine for the wounded. Read slowly, its first mercy is grammatical: the gift comes in the past tense, a’taynaka, We have already given you, so the mocked and grieving man ﷺ is told that his account is already full while his critics are still counting what he lacks. Every reciter who has been diminished by others, for childlessness, poverty, failure, or faith, stands inside this verse and feels the ground steady: your worth was settled by the Giver, not the audience.","Then the surah teaches what to do with pain: fa-salli, so pray. Not answer them, not prove them wrong, but turn to your Lord with prayer and sacrifice, and let Him handle the reply. And He does, in five words that closed the argument for all time. The reciter learns the deepest lesson of the shortest surah: when you are cut, turn to Him, and what is cut off will never be you."],"passages":[{"ref":"108:1","why":"The past-tense gift: abundance already granted, the verse to stand in when others count what you lack."},{"ref":"108:3","why":"Five words that reversed a taunt forever and let history verify a prophecy."}],"connections":[{"to":93,"why":"Ad-Duha follows the same divine pattern: a grieved Prophet ﷺ, a gift recounted, a promise sealed against the mockers."},{"to":109,"why":"Al-Kafirun stands next in the mushaf answering the same Quraysh, the gift refused their bargaining as this surah refused their taunt."}],"virtue":{"text":"The Prophet ﷺ himself announced this surah’s descent, smiling as he woke, and unveiled its meaning: al-Kawthar is a river of abundant good his Lord granted him, with a basin where his ummah will meet him on the Day of Rising.","src":"Muslim 400","level":"sunnah"}},
/* 109 Al-Kafirun, deep, 6 ayat */
109:{"n":109,"depth":"deep","context":["Al-Kafirun is Makkan, and the books of tafsir widely relate its backdrop: leading men of Quraysh proposed a merger, worship our gods for a year and we will worship yours for a year, or at least touch our idols and we will follow your prayer. The individual chains for the story are discussed by the scholars, but the setting is accepted, and the surah’s wording is its own evidence: it is one long, structured refusal of religious barter, repeated until no loophole survives.","In the Prophet’s ﷺ own practice the surah held a fixed and honored place. He recited it with Al-Ikhlas in the two rak’ahs before Fajr and in the two after tawaf, circling the House, as Muslim relates, and he told a companion to recite it before sleeping, for it is bara’ah min ash-shirk, a declaration of innocence from worshipping anything beside Allah. Some early scholars called it al-Muqashqishah, the curer, because it shakes the disease of shirk out of the one who says it truthfully."],"name_story":"The surah is named for its address, ya ayyuha al-kafirun, O disbelievers, the ones then bargaining over God. Early scholars also called it al-Muqashqishah, the curer that shakes off shirk, and it travels with Al-Ikhlas as one of the two surahs of pure creed the Prophet ﷺ paired in prayer.","movements":[{"range":"1-3","h":"The address and the refusal","note":"Say it to their faces: I do not worship what you worship, and you are not worshippers of what I worship, the two religions stated as two facts."},{"range":"4-5","h":"No, not ever","note":"The refusal is repeated across time, past and future closed alike: no rotation, no gradual merger, no year of yours and year of mine."},{"range":"6-6","h":"Two ways, one boundary","note":"Lakum dinukum wa liya din: for you is your religion and for me is mine, a boundary drawn without a sword and without a concession."}],"themes":[{"t":"Worship is not negotiable","d":"Everything else can be discussed; the object of worship cannot. The surah plants one flag that no diplomacy may move."},{"t":"Repetition as finality","d":"The doubled refusals answer every escape clause, now and later, form and heart, until bargaining has nowhere left to stand."},{"t":"Clarity is mercy","d":"The kindest thing said to error is a clean no: the surah ends false hope of a merger so that real choice, and real faith, become possible."},{"t":"Coexistence without mixture","d":"For you your religion, for me mine: not approval of falsehood but a boundary that leaves the disbeliever his choice and the believer his purity."}],"heart":["Al-Kafirun recited slowly trains the one muscle modern life most weakens: the clean no. The surah is not angry; it is exact. Its refusals close every door softly and completely, and the reciter feels his own creed being wrung out like a washed garment, twisted until the last drops of people-pleasing leave it. This is why the Prophet ﷺ planted it at the day’s frontiers, in the sunnah of Fajr as the day opens and on the tongue before sleep as it closes: a soul that begins and ends with bara’ah, disavowal of every false object of worship, cannot drift far in the hours between.","The last verse gives the reciter his posture toward a disbelieving world: neither compromise nor cruelty, but boundary. Lakum dinukum wa liya din is not a treaty of indifference; it is the dignity of a faith that does not need to blur itself to survive. Whoever says it truthfully has decided who he is, and that decision is the surah’s gift."],"passages":[{"ref":"109:1","why":"The commanded address: hear the clean no said aloud, to faces, without apology."},{"ref":"109:6","why":"The boundary verse: two religions, no mixture, the sentence that ended the bargaining forever."}],"connections":[{"to":112,"why":"Al-Ikhlas is its lifelong partner in the Fajr and tawaf rak’ahs: this surah clears the ground of false gods, and that one builds the house of pure creed."},{"to":110,"why":"An-Nasr completes the account: the same Quraysh whose bargain was refused enter Allah’s religion in crowds."}],"virtue":{"text":"The Prophet ﷺ told a companion to recite it before sleeping, then sleep upon its ending, for it is a disavowal of shirk, worshipping others beside Allah; and he ﷺ recited it with Al-Ikhlas in the sunnah of Fajr and the rak’ahs of tawaf. The circulating report that it equals a quarter of the Quran is weak and should not be relied on.","src":"Abu Dawud 5055; Muslim 726","level":"sunnah"}},
/* 110 An-Nasr, deep, 3 ayat */
110:{"n":110,"depth":"deep","context":["An-Nasr is Madinan and stands among the very last of the Quran: Ibn Abbas related that it was the final surah revealed as a whole. Its horizon is the conquest of Makkah in the eighth year after hijrah, the emigration, and the year of delegations that followed, when tribe after tribe crossed Arabia to enter Allah’s religion in waves, afwaja, the crowds the surah names. Twenty years of refusal dissolved into processions of acceptance, and heaven marked the moment with three verses.","The Companions heard more in it than triumph. In Bukhari, Umar seated the young Ibn Abbas among the elders of Badr and asked them about this surah; they spoke of victory and praise, but Ibn Abbas said: it is the appointed end of the Messenger of Allah ﷺ, announced to him: when the work is complete, the worker is called home, so glorify and seek forgiveness. Umar agreed. And Aishah saw the surah enter his ﷺ very posture: after it came down he constantly said in his bowing and prostration, Glory to You, O Allah, our Lord, and praise; O Allah, forgive me."],"name_story":"The surah is named for an-nasr, the decisive help of Allah in its first verse. Some early scholars called it Surat at-Tawdi, the Farewell, because beneath its victory they heard the gentle announcement of the Prophet’s ﷺ approaching departure, and both names are true to it at once.","movements":[{"range":"1-2","h":"Help, conquest, crowds","note":"When Allah’s help and the opening of Makkah come, and you see people entering His religion in waves: the whole harvest of the mission gathered into two verses."},{"range":"3-3","h":"Praise and pardon at the summit","note":"The commanded response to total victory: glorify your Lord with praise and seek His forgiveness, for He is ever accepting of return."}],"themes":[{"t":"Victory belongs to Allah","d":"Nasru Allah, the help is His and the conquest is His opening: the surah files twenty years of sacrifice under one Owner, and pride finds no foothold."},{"t":"Endings announced gently","d":"The Companions who understood deepest heard farewell inside triumph: completion of the work is the signal that the worker will be called home."},{"t":"Istighfar crowns achievement","d":"At the summit, the command is to seek forgiveness, sealing every accomplishment against self-congratulation and repairing whatever the long road bruised."},{"t":"He is ever-returning","d":"Innahu kana tawwaba: the surah’s last name of Allah promises that every turner toward Him is received, the door open at the end as at the beginning."}],"heart":["An-Nasr read slowly reshapes how a person stands at his own summits. The world teaches victory laps; this surah teaches that the correct posture at the peak is bowed, tasbih, glorifying, hamd, praising, istighfar, asking pardon, because achievement is His gift passing through your hands, and because no long labor is finished without stains that need washing. Whoever completes anything, a degree, a business, a book of the Quran, a lifetime of raising children, is handed this surah as the manner of finishing.","And beneath that, the tender reading of Ibn Abbas waits for every reciter who is growing older: completed work is a summons. The surah lets you hear your own endings approaching not as loss but as the call that came to the most beloved of creation ﷺ, and it fills the remaining time with the three verbs that make any ending safe: glorify, praise, seek forgiveness. He is ever-returning to the one who returns."],"passages":[{"ref":"110:1","why":"The verse of the harvest: help and opening arriving together after twenty years of refusal."},{"ref":"110:3","why":"The manner of finishing everything: praise and pardon at the summit, the verse he ﷺ lived in his final bowings."}],"connections":[{"to":109,"why":"Al-Kafirun refused the bargain of the idolaters; An-Nasr shows those same people entering the religion in crowds, refusal ripened into welcome."},{"to":48,"why":"Al-Fath promised the clear opening; An-Nasr stands on the far side of that promise, watching it fulfilled."}],"virtue":{"text":"After this surah came down, Aishah relates, the Prophet ﷺ filled his bowing and prostration with, Glory to You, O Allah, our Lord, and praise; O Allah, forgive me, interpreting the Quran in his own limbs, so the surah carries a sound portrait of how he ﷺ received it.","src":"Bukhari 794, Muslim 484","level":"sunnah"}},
/* 111 Al-Masad, deep, 5 ayat */
111:{"n":111,"depth":"deep","context":["Al-Masad descends from a scene preserved in Bukhari. When the command came to warn his nearest kin, the Prophet ﷺ climbed the hill of Safa and called Quraysh clan by clan. If I told you horsemen were in the valley behind me about to attack, would you believe me? Yes, they said, we have never known you to lie. Then I warn you, he ﷺ said, of a severe punishment ahead. His own uncle Abu Lahab answered: tabban laka, ruin to you, is this what you gathered us for? And the surah came down carrying his word back to him: tabbat yada Abi Lahab, ruined are the hands of Abu Lahab.","Abu Lahab, Abd al-Uzza ibn Abd al-Muttalib, and his wife Umm Jamil, sister of Abu Sufyan, made a household of the persecution: he dogged the Prophet’s ﷺ steps crying liar, and she, the carrier of firewood, fed the fires of slander, or laid thorned branches in his path as some early commentators relate. The surah then became a standing wager the Quran placed on its own truth: it declared, while both lived, that they would die outside faith and burn. Either could have falsified the Book with one spoken shahadah, testimony of faith. Neither ever did. Abu Lahab died soon after Badr, untouched by belief, and the prophecy closed."],"name_story":"The surah is named for al-masad, the rope of twisted palm-fiber around the neck of the firewood-carrier in its last verse. It is equally known as Surat Tabbat from its first word and Surat al-Lahab from the man it condemns, whose nickname, father of flame, was given for his glowing face and answered by the Flame it names.","movements":[{"range":"1-3","h":"The curse returns to sender","note":"The ruin he pronounced falls back on his own hands; his wealth and all he earned avail him nothing, and a fire of lahab, of flame, waits to match his name."},{"range":"4-5","h":"The carrier of firewood","note":"His wife, hauler of wood for slander’s fires, enters the scene with a rope of twisted fiber on her neck, the couple’s shared cruelty given one shared sentence."}],"themes":[{"t":"Kinship does not exempt","d":"The condemned man is the Prophet’s ﷺ own uncle: nearness of blood to the best of creation saves no one who chooses enmity to his message."},{"t":"A prophecy in present tense","d":"Revealed while both targets lived free to fake a conversion and shatter it, the surah wagered the Quran’s truth on two human hearts and won."},{"t":"Wealth’s limit repeated","d":"Ma aghna anhu maluhu wa ma kasab: neither fortune nor achievements ransom a soul, the refrain of this whole final section of the mushaf."},{"t":"A name become destiny","d":"The father of flame ends in flame: the surah turns his proud nickname into his sentence, and mockery of the truth into a mirror."}],"heart":["Al-Masad is the only surah that condemns a contemporary of the Prophet ﷺ by name, and reciting it slowly one feels why it was preserved for all time: it is the Quran’s demonstration that no rank, no lineage, no wealth, and no proximity to holiness substitutes for faith. Abu Lahab had every advantage a soul could hold, Hashimi blood, wealth, the Prophet ﷺ as his own nephew, and the surah shows all of it weightless against one hardened heart. The reciter quietly checks his own borrowed credentials, family piety, community, reputation, and lets the surah strip him back to the only question that counts: what does my own heart hold?","There is also a strange comfort here for anyone opposed by their own kin for their faith. The Prophet ﷺ himself was cursed by his uncle and slandered by his uncle’s wife, and heaven answered on his behalf. The surah teaches the wounded believer to leave the answering to Allah, whose replies outlast every insult."],"passages":[{"ref":"111:1","why":"Hear a curse reversed in real time: the ruin he pronounced on Safa returned to his own hands."},{"ref":"111:2","why":"One verse retires the oldest false hope: wealth and earnings availing nothing at the reckoning."},{"ref":"111:5","why":"The final image, the fiber rope, where the surah’s justice reaches even the carrier of the firewood."}],"connections":[{"to":108,"why":"Al-Kawthar reverses a taunt against the Prophet ﷺ, Al-Masad reverses a curse: two enemies handed the endings they designed for him."},{"to":104,"why":"Al-Humazah draws the type, the mocker rich enough to sneer; Al-Masad names the case and closes the file."}],"virtue":{"text":"No hadith assigns a recitation reward to Al-Masad, and it needs no certificate: its distinction is to be a fulfilled prophecy, revealed in Bukhari’s sound account at Safa and verified by two lives that never falsified it.","src":"the occasion, Bukhari 4971; no recitation-report","level":"debated"}},
/* 112 Al-Ikhlas, deep, 4 ayat */
112:{"n":112,"depth":"deep","context":["Al-Ikhlas came down as an answer. The transmitted reports, graded fair by many scholars, relate that questioners demanded of the Prophet ﷺ, unsub lana rabbaka, trace your Lord’s lineage for us, idolaters of Makkah in one report, and in another, questioners in Madinah, which is why the scholars differ over its Makkan or Madinan origin. The surah replied with a definition that refuses all lineage: He is Allah, Ahad, uniquely One; as-Samad, the self-sufficient on whom all depend; He neither begets nor is begotten, and none is equal to Him.","No surah saturated the Prophet’s ﷺ daily worship more. He paired it with Al-Kafirun in the sunnah of Fajr and the rak’ahs after tawaf, sealed his witr with it, and recited the three Quls over his palms each night. When a commander of an expedition ended every recitation with it and was asked why, he said: because it is the description of ar-Rahman, the Most Merciful, and I love to recite it. Tell him, said the Prophet ﷺ, that Allah loves him."],"name_story":"Al-Ikhlas means pure sincerity, and the surah never uses the word: it earned the name by being purely about Allah, no command, no story, no other subject, and by purifying the creed of whoever holds it. It is also cited as Qul huwa Allahu Ahad from its opening, and some early books call it Surat at-Tawhid, the surah of divine oneness.","movements":[{"range":"1-2","h":"He is Allah, One, Samad","note":"The identity is stated in two names: Ahad, One without division or series, and as-Samad, the eternal refuge whom all creation needs and who needs nothing."},{"range":"3-4","h":"What He is not","note":"The negations that guard the affirmation: no offspring and no origin, and none in all existence is kufuwan, equal or comparable, to Him."}],"themes":[{"t":"Oneness without arithmetic","d":"Ahad is not the first of a series but the One who admits no series: unique in essence, names, and deeds, beyond division and beyond counting."},{"t":"As-Samad, the needed One","d":"Every creature leans on Him for every breath while He leans on nothing: the name that turns all human dependency into an address."},{"t":"Negation protects praise","d":"Lam yalid wa lam yulad: the surah fences the truth against every mythology of divine families, and against every subtle modern idol."},{"t":"A third of the message","d":"The Quran teaches creed, law, and the accounts of nations; this surah carries the creed whole, which is how the scholars explained its equivalence to a third."}],"heart":["Al-Ikhlas recited slowly is the heart returning to its one fixed point. Four verses, and every direction of human worship is corrected at once: Ahad dissolves the crowded pantheons, ancient and modern, and as-Samad quietly redirects all our leaning, on salaries, on people, on our own competence, toward the only support that does not itself need supporting. The reciter feels the surah working like a plumb line dropped through the self, truing whatever had tilted toward created things during the day.","Its shortness is its mercy and its test. Said in seconds, it can pass unweighed; said with presence, it is the heaviest speech a tongue can carry, the description of ar-Rahman by ar-Rahman. The Companion who could not stop reciting it was told that Allah loved him, and that door is not closed: love of this surah is love of the One it describes, and He answers it in kind."],"passages":[{"ref":"112:1","why":"The Quran’s definition of God in His own words: hear Ahad and let it empty every false throne."},{"ref":"112:2","why":"As-Samad: the name to lean on when every created support has bent."},{"ref":"112:4","why":"The final fence: none is equal to Him, the verse that completes the creed in seven words."}],"connections":[{"to":109,"why":"Al-Kafirun and Al-Ikhlas travel together in the Prophet’s ﷺ prayer: the first is disavowal of every false god, the second the description of the true One."},{"to":113,"why":"Al-Falaq begins the two refuges that follow: after the creed is pure, the believer is taught to shelter it."}],"virtue":{"text":"The Prophet ﷺ said that Qul huwa Allahu Ahad equals a third of the Quran, a sound and famous virtue, and he ﷺ told the man who loved it because it describes ar-Rahman: Allah loves him.","src":"Bukhari 5013, Muslim 811; the love report, Bukhari 7375","level":"sunnah"}},
/* 113 Al-Falaq, deep, 5 ayat */
113:{"n":113,"depth":"deep","context":["Al-Falaq came down paired with An-Nas, and the Prophet ﷺ announced them with wonder: do you not see verses revealed this night the like of which has never been seen? Qul a’udhu bi-rabbil-falaq and Qul a’udhu bi-rabbin-nas. The account is in Muslim from Uqbah ibn Amir. The scholars differ whether the pair is Makkan or Madinan; many tafsirs connect them to the sound Bukhari account of the spell cast on the Prophet ﷺ by Labid ibn al-A’sam, though the link of their revelation to that event is a later addition, and honesty keeps the two reports distinct.","What is beyond dispute is how he ﷺ used them. Aishah relates that every night he would cup his palms, recite Al-Ikhlas, Al-Falaq, and An-Nas into them, and wipe over his body, and in his final illness she did it for him with his own hands. He taught them as the morning and evening shield, and said that nothing compares to them for the one seeking refuge. With these surahs the community learned that fear has a liturgy: darkness, sorcery, and envy are real, and the answer to all three is a Lord who splits the dark with dawn."],"name_story":"The surah is named for al-falaq, the daybreak, the splitting-open: the Lord who cracks the night with dawn, the seed with the shoot, and every siege with rescue. With An-Nas it forms al-mu’awwidhatan, the two surahs of seeking refuge, a title given by the Prophet ﷺ himself.","movements":[{"range":"1-2","h":"Refuge with the Splitter of dawn","note":"The command is to say it aloud: I take refuge with the Lord of the daybreak from the evil of what He created, all harm at once placed under the authority of its own Maker."},{"range":"3-5","h":"Three darknesses named","note":"Then the fears are named one by one and shrunk by naming: the settling night, the blowers on knots practicing sorcery, and the envier when he envies."}],"themes":[{"t":"Refuge is an act","d":"Isti’adhah, taking refuge, is said, not merely felt: qul, say it, the soul physically running to its Lord the way a child runs behind a father."},{"t":"Evil is created and contained","d":"From the evil of what He created: harm has no independent throne; it exists inside His dominion, which is exactly why refuge with Him works."},{"t":"Named fears shrink","d":"Night, sorcery, envy: the surah drags the vague dreads of the heart into the light and lists them, and a named fear is already half-disarmed."},{"t":"Envy’s evil is conditional","d":"Idha hasad, when he envies: the eye’s harm activates when envy acts, so the surah teaches both refuge from enviers and vigilance against becoming one."}],"heart":["Al-Falaq recited slowly is the believer’s answer to the dark, and its first word of address is already the cure: not Lord of the night, but Lord of the daybreak. The surah makes you seek shelter from darkness with the One whose signature is splitting it, so hope is built into the grammar before any fear is named. Then the three darknesses file past, the night that hides things, the malice that works unseen, the envy that smiles to your face, and the reciter realizes the surah has covered every direction harm arrives from: circumstance, enemy craft, and the resentful heart nearby.","Whoever makes this surah a nightly habit, palms cupped as the Prophet ﷺ taught, discovers its quiet psychological gift: fear is no longer managed alone. The dark is still dark, but it has an owner, and you know Him, and the last thing your body feels before sleep is His name wiped over it."],"passages":[{"ref":"113:1","why":"The address that carries the cure: refuge from darkness sought with the Lord of the daybreak."},{"ref":"113:5","why":"The last named fear, envy, the harm that arrives through a smiling face, placed under His protection."}],"connections":[{"to":114,"why":"An-Nas is its inseparable twin: Al-Falaq shelters from harms outside the chest, An-Nas from the whisper inside it."},{"to":112,"why":"Al-Ikhlas states the creed and the two refuges guard it: the Prophet ﷺ recited the three together each night over his palms."}],"virtue":{"text":"The Prophet ﷺ said of Al-Falaq and An-Nas: verses revealed this night the like of which has never been seen, and he made them his nightly and morning refuge, reciting them over his palms and wiping his body.","src":"Muslim 814; the nightly practice, Bukhari 5017","level":"sunnah"}},
/* 114 An-Nas, deep, 6 ayat */
114:{"n":114,"depth":"deep","context":["An-Nas closes the Quran, revealed together with Al-Falaq as the two refuges the Prophet ﷺ said were without like. Where its twin lists harms of the outer world, night, sorcery, envy, this surah turns entirely inward to a single enemy, the last one standing when all others fall: al-waswas al-khannas, the whispering one who retreats, murmuring into the chests of mankind, whether that whisperer is of the jinn, the unseen beings of smokeless fire, or of people, for harmful suggestion can arrive in a friendly human voice.","There is a quiet architecture in the Quran ending here. The Book opens with Al-Fatihah, mankind asking guidance from the Lord of the worlds; it closes with mankind running to the Lord, King, and God of mankind to protect that guidance from the voice that would unpick it. The Prophet ﷺ sealed his nights with this surah among the three Quls, and taught that the whisperer shrinks and retreats, khannas, the moment Allah is remembered, so the surah is not only a prayer but a tactic."],"name_story":"The surah is named for an-nas, mankind, sounded five times in six verses like a bell: named for the ones it protects rather than the enemy it exposes. With Al-Falaq it forms al-mu’awwidhatan, the two refuges, the Prophet’s ﷺ own name for the pair that ends the Book.","movements":[{"range":"1-3","h":"Three titles of one Protector","note":"Refuge is sought in an ascending claim: Rabb, the Lord who nurtures mankind, Malik, the King who rules them, Ilah, the God they worship, care, then authority, then devotion."},{"range":"4-6","h":"The enemy described","note":"The threat is exposed with precision: the retreating whisperer who murmurs in the chests of mankind, whether from the hidden jinn or from people."}],"themes":[{"t":"A triple grip of protection","d":"Lord, King, God: three relationships, each one enough, stacked into a single refuge, because the enemy attacks the deepest room in the house, the chest."},{"t":"The whisper retreats at remembrance","d":"Khannas, the shrinking one: his entire power is suggestion, and he flees the name of Allah, so the surah carries its own victory condition inside it."},{"t":"Human devils too","d":"Min al-jinnati wan-nas: harmful whispering is not only unseen; it can come dressed as advice from people, and the surah teaches discernment about voices."},{"t":"Ending the Quran on refuge","d":"The Book’s last word of substance is mankind sheltered in its Lord: revelation ends by tucking the reader under the wing it opened."}],"heart":["An-Nas recited slowly is the most intimate security the Quran offers, because it guards the one territory no lock defends: the interior murmur. Every believer knows the voice, the suggestion that arrives mid-prayer, the doubt seeded at night, the resentment dressed as reason, and the surah’s mercy is to tell you two things about it: it is real, you are not uniquely broken, and it is weak, built to retreat the instant your Lord is named. Reciting the surah is therefore not describing the battle but winning the day’s round of it.","And the three titles are the deep comfort. Against a whisper you are given a Lord who raised you, a King who outranks every power that threatens you, and a God worth all your worship, three ropes for one small enemy. The Quran ends here deliberately: after every law, story, and warning, the final gift is a hiding place. The reader closes the Book already inside it."],"passages":[{"ref":"114:1","why":"The beginning of the Quran’s last prayer: refuge sought with the Lord of mankind for mankind."},{"ref":"114:4","why":"The enemy named exactly: the whisperer who retreats, so the reciter learns his weakness in his name."}],"connections":[{"to":113,"why":"Al-Falaq guards the outside of the fortress and An-Nas the inside: the Prophet ﷺ recited the pair as one shield."},{"to":1,"why":"Al-Fatihah opens the Book asking guidance, An-Nas closes it guarding that guidance: the Quran begins in prayer and ends in refuge."}],"virtue":{"text":"With Al-Falaq it forms the two refuges the Prophet ﷺ called verses without like, revealed in one night; he recited them in the nightly three over his palms and after every prayer, and no seeker of protection was ever given their equal.","src":"Muslim 814; the nightly practice, Bukhari 5017","level":"sunnah"}}
};
